/* 平成25年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h25.committeeSessions.push(...[{"id":"h25-20131004-4","meetingId":"h25-c-settlement","date":"2013年10月4日","dateIso":"2013-10-04","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３６分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を178件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"松澤委員","kind":"質問・要望","question":"２点、お伺いしたいと思います。同じく３項生活保護費、１３６ページ、１３７ページについてお伺いをしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"私から、認知症の高齢者の支援とケアの充実ということについてですけれども、重層的な支援をするという中身です。徘徊される高齢者の家族支援としてＧＰＳの探索システムや。","id":"exchange-001"},{"speaker":"松澤委員","kind":"質問","question":"平成２２年が新規申し込み３人、平成２３年６人、平成２４年４人。何でこんなに便利なものというか、これが何で増えていかないのか、それについてお聞きしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"まず費用がかかるということ、それと、あとはその高齢者の方が常に身につけていられるかどうかということもあります。実際に周知については、在宅支援センターのケアマネジャーがその高齢者の状態や家族の状態を見ながらお勧めはしているのですけれども、費用の関係や。","id":"exchange-002"},{"speaker":"松澤委員","kind":"質問・要望","question":"それと認知症、これは成果報告書の中ではたった１行なのですね。やはり、これから認知症というのは大きな問題になっていくと思いますので、今後の認知症の施策の展開について、お聞きしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"現在、そういうときの配慮の仕方などの理解を深めていただくところを広げているところで、かなりサポーター研修の参加者も増えているところです。そういうことができるかどうかという可能性も、その研修を受けた方とともに検討しながら考えていきたいと考えています。","id":"exchange-003"},{"speaker":"松澤委員","kind":"質問・要望","question":"２点目にまいります。生活保護の給付の適正化についてどのように施策を展開してきたのかということと、不正受給の実態について、お教えほしいと求めました。","respondent":"竹田生活福祉課長","answer":"課税情報ですと１年前の収入ですので、一度になかなか返還していただけないケースが多いのですが、回収に努めているところです。平成２４年度末の実績ですが、不正受給と認められた額から返還額を差し引いた未収入額は５２件、４,４７５万円余となっております。","id":"exchange-004"},{"speaker":"松澤委員","kind":"質問","question":"時間がないですけれども、８月１日から基準が引き下げられましたね。これについては本会議等々で質問がありましたけれども、生活困窮者向けの自立支援法が成立すると言われていますけれども、その動向がわかりましたら。","respondent":"竹田生活福祉課長","answer":"秋に国会に上程されて、審議される予定です。","id":"exchange-005"},{"speaker":"つる委員","kind":"質問","question":"障害を持つ親の子育て支援の観点でお尋ねしたいと思います。居宅介護、重度訪問介護のサービス提供の中で、育児支援を受けられている方について、状況を説明を求めました。","respondent":"中山障害者福祉課長","answer":"今の自立支援サービスの介護人派遣のうち、育児支援サービスを受けられている方がいらっしゃるかというお尋ねですけれども、育児支援を実際に給付されている方が、およそ３名ほどいらっしゃいます。","id":"exchange-006"},{"speaker":"つる委員","kind":"質問","question":"３名ということで、ありがとうあります。対応していただいているこの趣旨の周知方法は、どういう形で行っているのか、説明を求めました。","respondent":"中山障害者福祉課長","answer":"実際の周知の方法ですが、障害者の方が、例えばこちらの区の窓口であるとか、あるいは生活支援センターのほうに困り感ということで、実際にご相談いただいた中で、どういったサービスを組み立てて生活を続けていくことができるかということを、相談の中でやっているところです。","id":"exchange-007"},{"speaker":"つる委員","kind":"意見","question":"都道府県の主管部局に送られたものなので、今現在わかっている段階で３３の道県で、該当所管のホームページにその事務連絡を掲示しているのですね。その辺が品川区として掲示できるかどうかも含めて、また独自のチラシができるかどうかを含めて、この辺についてお考えを説明を求めました。","respondent":"中山障害者福祉課長","answer":"ただ、例えば赤ちゃんを出産するという前準備の保健センターとの連携の中でも、この６月に生まれたお子さんについても今まで対応してきたところです。そういったことも含めまして、今後の課題とさせていただければと考えています。","id":"exchange-008"},{"speaker":"つる委員","kind":"質問","question":"今年の４月から障害者総合支援法になって、難病患者の方もその支援サービスの対象になりました。参加を促進するようにしたほうがいいのではないかと思いますけれども、これまでの参加実績だとか周知方法、この辺の現状を説明を求めました。","respondent":"中山障害者福祉課長","answer":"こちらのまつりは実行委員会方式で行っております。実行委員会形式でボランティアを含めて開催しているものですので、そういったお声があれば、ぜひこちらのほうにお声かけいただければと考えています。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"あのウルトラ・オーファンドラッグ開発促進・支援のための法整備等を求める意見書の提出に関する請願、これは全会一致で採択をいただきました。１２４ページ、高齢福祉費ですが、そこに絡めてなのですけれども、介護におけるコミュニケーションについてお尋ねをしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"耳の遠くなった方に対しての対応ですけれども、委員のご質問のシニアサインというのは、ちょっとわかっておりません。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問","question":"それから目と目を合わすアイコンタクト、それからゆっくりはっきりと話すということだそうです。そうした中で活かしていっていただけたらと思うのですが、その辺も含めた研究について、お考えがあれば説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"委員ご提案のシニアサインにつきましても、もうちょっとこちらのほうで調査いたしまして、導入できるかどうかというところを検討してまいりたいと思います。","id":"exchange-011"},{"speaker":"つる委員","kind":"質問","question":"１２５ページ、熱中症等予防対策事業です。お休みどころというところでやっていただいておりますけれども、その周知方法はどういうふうにして取り組まれているか、説明を求めました。","respondent":"白鳥高齢者いきがい課長","answer":"避暑シェルターですけれども、区内６２カ所に設置した避暑シェルターです。私どもの所管であります東品川シルバーセンターほか１５カ所のシルバーセンターですけれども、周知をしてきたところです。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問","question":"わかりました。なかなか経費の問題もあると思いますが、この辺も含めた周知方法のお考えがもしあれば、説明を求めました。","respondent":"工藤総務課長","answer":"避暑シェルターのマップに関するご提案です。広報、のぼり等の周知に加えまして、どういった形で周知していくかは検討さていただきたいと考えています。","id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"いろいろな取り組みをやっていると思いますけれども、世田谷区のこういったマップもぜひ参考にしてほしいと求めました。１３５ページ、おもちゃで遊べる取り組みをやっていると思うのですが、その辺の状況を説明を求めました。","respondent":"伊崎子育て支援課長","answer":"おもちゃの広場ですが、大井倉田児童センターで毎週金曜日、午前１０時から１２時までやっております。それから、後地児童センターでも、毎週土曜日の１０時から２時半までという形で実施をしております。","id":"exchange-014"},{"speaker":"つる委員","kind":"提案","question":"時間がないので、また改めての質問にしたいと思いますけれども、ぜひ拡充をしてほしいと求めました。そういうことも絡めて取り組んでいるようなところもあるそうなので、そうしたことを含めて、また改めて提案をしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"木村委員","kind":"質問・要望","question":"本日はこの民生費の中で、１２４ページの中ほどより少し下にあります、高齢者の趣味・健康づくり事業３９５万円余からの質問をいたします。お答えほしいと求めました。","respondent":"白鳥高齢者いきがい課長","answer":"健康な６５歳から健康で活動的な８５歳へのリーフレットの七つの項目のほうを読み上げていただきました。やはりこれらを、周知・ＰＲをしていますけれども、成果については徐々には上がっているのかという感じは持っているところです。","id":"exchange-016"},{"speaker":"木村委員","kind":"質問・要望","question":"先ほど言いました１人用の自分の食べ物だと思いますけれども、つくること、それ以外に何か狙いがあるのかどうか。この料理教室を行うことによって何かを願っているのかどうか、言い方はちょっと変ですけれども、お答えいただけたらと思います。","respondent":"白鳥高齢者いきがい課長","answer":"やはり買い物から、それから調理器具の使い方等、これらを一からいろいろと勉強していっていただく。同じ境遇の方がいらっしゃいますので、そういう方々と仲間づくり、交流に発展していっていただければという思いの中で、この事業を展開しています。","id":"exchange-017"},{"speaker":"木村委員","kind":"質問・要望","question":"しかし、正しい運動をすれば、まだまだ筋力や体の機能、能力を保つことができるということを私はいろいろ聞いたことがあります。元気に人生を楽しんでいるのではないかと私自身も感じていますが、皆様はどのようにそのことに対して捉えているか、お聞かせほしいと求めました。","respondent":"白鳥高齢者いきがい課長","answer":"そのそれぞれの思いの中で、自分に合ったものに参加していただくということは、大変大切なことだろうと考えています。社会参加という中で、さまざまな区の施策の中で行われているものの中に、いろいろと積極的に参加していただけるものではないかと感じております。","id":"exchange-018"},{"speaker":"木村委員","kind":"意見","question":"どのようにしたら、男性をこういうイベントやサークルなどに参加をさせることができるか、そういう秘策がありますか。何か考えているかどうか、説明を求めました。","respondent":"白鳥高齢者いきがい課長","answer":"大変難しい質問かと思いますけれども、やはり男性よりも女性のほうが圧倒的に積極性が見られる。さまざまな工夫を凝らしながら、いろいろとこの地域をじっくりと把握しながら、いろいろな方々のお声を拝聴していきたいと考えています。","id":"exchange-019"},{"speaker":"木村委員","kind":"質問・要望","question":"次に、１２４ページの上から１１行目に、高齢者生きがい対策事業というものがあります。最初見たときに、何がどうかはちょっとわからなかったのですけれども、この違いを教えてほしいと求めました。","respondent":"白鳥高齢者いきがい課長","answer":"ご説明をするに当たりまして、高齢者クラブのほうの会員クラブの助成金のほうからご説明させていただきたいと思います。それぞれ高齢者クラブ連合会に対する支援ということで、会員の人数ですとか、あるいはその他特別事業をもって助成という形で支援をしているものです。","id":"exchange-020"},{"speaker":"木村委員","kind":"意見","question":"先ほどお話がありましたが、約１万２,０００人弱ということですけれども、高齢者クラブ連合会というのは大変大きな団体になりますね。ボランティア、頭の下がる思いでありますけれども、活動を通しての生きがいとは一体どのようなこととお考えになりますかとの意見を述べました。","respondent":"白鳥高齢者いきがい課長","answer":"同じ趣味を持つ方々同士、一緒に環境美化という視点で町の美化活動に励んだり、あるいは登下校の子ども達の見守り活動を行う。独居高齢者の方々の見守りも一部のクラブでは行っているという、こういったところから、生きがいを見出しているのではないかと感じております。","id":"exchange-021"},{"speaker":"木村委員","kind":"意見","question":"区としても、高齢者の健康のためにも大変大事な事業だと思っています。こういう活動のためにも、助成の枠を広げるようなお考えがあるかどうか、お聞かせ願いたいと思いますとの意見を述べました。","respondent":"白鳥高齢者いきがい課長","answer":"区のほうでの支援の仕方につきましては、自分たちの力で何かこの社会を明るくするための方策を、さまざまな工夫を凝らしながらやっていただく。","id":"exchange-022"},{"speaker":"木村委員","kind":"質問・要望","question":"このクラブの間での、よい意味での競争がボランティアの回数にあらわれていると思いますけれども、行政としてのお考えもお聞きしたいと考えています。１００回と１,０００回とでは大きな違いがありますけれども、この差というものはどういうところから出ているのか、お聞かせほしいと求めました。","respondent":"白鳥高齢者いきがい課長","answer":"その差というご質問ですけれども、会員の規模が３０名から二百数十名にわたるものですので、その会員数によりまして、その活動、行動もごく限られてしまうという、ボランティアも同じことだと考えております。","id":"exchange-023"},{"speaker":"鈴木（博）委員","kind":"質問","question":"それとも、それほど多くないと考えるべきなのでしょうか。区のご見解をお伺いしたいと思います。","respondent":"立川保育課長","answer":"第１点目のお尋ねですが、最近の傾向といたしましては、８時半ですとか１０時という長時間については減っているという現状があります。それから、利用者ですけれども、やはりリピーターがほとんどです。","id":"exchange-024"},{"speaker":"鈴木（博）委員","kind":"質問","question":"例えば６時半から夜の１０時まで、子どもにとっては決して好ましい環境ではないということは、当然言うまでもないことだと思います。あるいは区として何か特別に配慮したり、それに寄り添う対応を特に考えたり、そのようなことはされているのか尋ねました。","respondent":"立川保育課長","answer":"長時間お預かりしているお子様につきましては、やはり週末などには、ほかのお子様と比較しまして、疲れが出ているというようなことが子どもの様子でうかがえる場合がありますので、そうした場合には休む時間を多くしたり、そういった配慮をしていると聞いています。","id":"exchange-025"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次に、１３２ページの家庭的保育事業（保育ママ）１億４１３万６,０７６円についてお伺いいたします。まず、保育ママ制度について、簡単にご説明をお願いいたします。","respondent":"今井制度改革・待機児童対策担当課長","answer":"家庭的保育事業の主な目的ですが、就労等で保育ができない保護者にかわって、保育資格および経験を有する保育ママが、ご自宅や借り上げしましたマンション等で保育を行うものです。","id":"exchange-026"},{"speaker":"鈴木（博）委員","kind":"質問","question":"家庭的保育において最も大きな問題は、保育される保育者の資質だと思いますが、保育ママを行う方というのは、どのような資格をお持ちの方がされるのか尋ねました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"資格ですが、保育士、教員、看護師、助産師または保健師のいずれかの資格を持つ方で、かつ所定の研修を終了された方を区のほうで認定いたしまして、保育ママとして保育に従事していただいております。","id":"exchange-027"},{"speaker":"鈴木（博）委員","kind":"質問","question":"保育士、看護師、それから保健師などの資格を持っている方が、保育ママで事業を展開したところ、あまりその資格者がいなかったので、現在は資格を持たない方でも、一定の研修をすれば保育ママ事業ができるということをちょっと調べたのですが、そうではないのか尋ねました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"家庭的保育事業は、国のほうで一定の基準を定めておりまして、国の基準ではそのような制度もありますが、品川区では平成２３年からの運用につきましては、今、申し上げました資格を持つ方という形でしています。","id":"exchange-028"},{"speaker":"鈴木（博）委員","kind":"質問","question":"よくわかりました。やはり保育の質が非常に大切だと思いますが、特に保育ママの場合は、どのような点に配慮して事業展開しなくてはいけないと区ではお考えか尋ねました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"保育ママにつきましては、在宅型、そして事業所型とありますけれども、公立の保育園が連携保育所となりまして、保育内容、または保育だよりとか園だよりとかをお渡しするとともに、月に１回、園長経験者の指導員が巡回しておりまして、相談や指導に当たっております。","id":"exchange-029"},{"speaker":"鈴木（博）委員","kind":"質問","question":"最後に、成果報告書１３５ページの児童センター運営費１０億６,７５９万２,４６４円についてお伺いします。来院した９６８名の保護者の方に育児アンケートをとったところ、今後とも精力的に児童センターのほうも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問","question":"そして、この５８４人の中で８７名は、要介護５ですが、この要介護５で入所できた方が何人か、伺いたいと思います。旧みやこ荘跡の特養ホームが完成するまでは、次の増設計画は発表しないというのが区の方針なのか、伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"平成２６年度に杜松小学校跡地、平成２８年度に平塚橋会館跡、平成２９年度にみやこ荘跡で特別養護老人ホームの建設を予定しております。国のほうの制度改正も検討されておりまして、第６期の事業計画に向けて、今後のことを考えていきたいと考えています。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"５８４人中１３２人というご説明でしたけれども、恐らくこれは１年間だと思うのですね。そうではなくて、今年３月の入所調整会議にかかった５８４人のうち、この半年間で入所がかなったのは何人かということを改めて伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"第１回の入所調整会議のときは７８人入所されておりまして、第２回では１３２人ということになります。なぜ第２回の人数が多いかというところになるかと思いますけれども、そこで４０人増えておりますので、両方があります。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"今後の高齢者の人口動向を見ても、これから４年間で２２９人分の特養ホームが増えますが、私はまだまだ足りないと思います。旧第一日野小学校、旧荏原第四中学校など、跡地に特養ホームをつくるという考えがあるのかを伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"高齢者の事業は特養ホームだけではないと思いますので、特養ホームのほかに、どういうセーフティネットの仕方があるかということも含めまして、これから考えていきたいと考えています。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"そこは違うのかどうか、改めて伺いたいと思います。跡地となっている第一日野小学校や荏原第四中学校などに、老健施設や特養ホームをつくるという考えがあるのか、改めて伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"みやこ荘跡の部分まで予定されているのですけれども、そこでの定員というのが、現在の予定だと２２９名となっております。さらにどういうふうな利用の需要が出てくるかということの検討をしつつ、必要なものであれば、土地についても探していきたいと考えております。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"保育園についても伺いたいのですけれども、区立認可保育園を入れない理由について、区は将来的な財政負担という説明がありました。つまり、なぜ財政負担が区立認可保育園をつくらない理由なのか、ご説明ほしいと求めました。","respondent":"永尾高齢者福祉課長、今井制度改革・待機児童対策担当課長","answer":"特養ホームにつきましては、国のほうの制度改正も、今、検討されておりますので、そういうところも視野に入れながら、必要なものをつくっていきたいと考えております。 家庭的保育事業など、総合的な対策で、今後も待機児童の解消に努めると申したところです。区民のいろいろなニーズに応えるためにも、区立だけではなく、私立のいろいろな力をお借りして運営していく必要があると考えております。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"なぜ財政負担が区立認可保育園をつくらない理由なのかと伺いましたが、一般財源化されていることがなぜ理由になるのでしょうか。改めて、今後の増設計画に区立認可保育園を入れない理由が、なぜ財政負担が理由になるのか、ご説明ほしいと求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"そういう中で、区も含めまして、今年度平成２５年度は区立もあけ、そして私立のほうも４園あけという形で、総合的に対策を進めております。以上の点から、区立、私立を問わず、認可保育園を中心とした対策を進めていくのは、考え方の基本です。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"つまり、これから区立認可保育園の増設を素案に記載する考えがあるということなのか、ないということなのか。私はぜひ、待機児童解消のためにもつくってほしいと求めましたが、ご説明ほしいと求めました。","respondent":"金子子ども未来事業部長","answer":"区立の幼保一体施設については建設を進めてまいりましたし、今後も認定こども園等は検討いたしますが、保育園の主体としては私立の認可保育園を主体としていきたいと考えております。","id":"exchange-037"},{"speaker":"沢田委員","kind":"質問","question":"成果報告書の１２２ページふれあい作業所、１３３ページ一日保育士体験事業と延長夜間保育についてお伺いします。この何年間かで結構ですけれども、つまり８時半以降の延長保育を開設した園というのは、大体何園ぐらいあったか尋ねました。","respondent":"立川保育課長","answer":"ここ数年の開設ですが、私立につきましては、８時半ということで開設をしていただいております。公立につきましては、７時半までということで開設しております。","id":"exchange-038"},{"speaker":"沢田委員","kind":"質問","question":"８時半以降の開設をした園が、平成２３年度が３園で、平成２４年度は６園ということでよろしいでしょうか。１時間延長は増えておりますけれども、１時間延長は７時半までですので、区としてはどのように分析していらっしゃるか尋ねました。","respondent":"立川保育課長","answer":"最近の傾向ですが、平成２３年の東日本大震災の影響により、その後、延長夜間保育の利用者というのが率にしてかなり減ったという時期がございました。そういった意味で、最近の減少傾向というのは、やはり働き方に関して保護者の方の意識が変わったと認識しております。","id":"exchange-039"},{"speaker":"沢田委員","kind":"質問","question":"そういった保護者の方の意識も変わってきた。特に９時以降といった時間の延長夜間保育について、区としてどのように今後は考えられているのか、説明を求めました。","respondent":"立川保育課長、金子子ども未来事業部長","answer":"小学校に入学いたしますと、やはりそれほど長時間預ってくれるところというのは、現在、区としては実施していないということもあります。いわゆる小学生を９時、１０時まで預かるというところも出てきてはありますけれども… 要するにその必要性についてきちんと説明をして、要するにこういう範囲で利用すべきだということをお約束しながら使っていただいていたのですね。","id":"exchange-040"},{"speaker":"沢田委員","kind":"質問・要望","question":"ああ、今後とも、ぜひともそういった親とのコミュニケーションを深めてほしいと求めました。一日保育士体験事業のことでお伺いしますけれども、今、改めてこの内訳についてお伺いさせてほしいと求めました。","respondent":"立川保育課長","answer":"この中身ですが、保育士体験をしていただくときに、保護者の方に一緒に給食を食べていただきます。その経費です。","id":"exchange-041"},{"speaker":"沢田委員","kind":"質問","question":"そうすると１人４００円ぐらいですけれども、ぜひそういったことも今後考えられたらどうかと思いますけれども、その点はいかがか尋ねました。","respondent":"立川保育課長","answer":"今後とも、給食費につきましては区のほうで負担していきたいと考えております。","id":"exchange-042"},{"speaker":"沢田委員","kind":"質問・要望","question":"ふれあい作業所の件でお伺いさせてほしいと求めましたけれども、今、山形県の新庄市で野球ボールの再生というのを行っているところがあります。こういった野球ボールの再生とか、こういった新たな事業の取り組みについてはどうお考えか尋ねました。","respondent":"中山障害者福祉課長","answer":"障害者の方にとっての就労の場というのは、経済的な自立に向けた重要な施策だと考えています。なかなかいい中身というのが見つからないところですので、ご提案の件につきましては研究させていただければと考えています。","id":"exchange-043"},{"speaker":"塚本委員","kind":"質問","question":"それから１３５ページの児童センター運営費、この２点について、中心的にお伺いしていきたいと思います。非常勤が２名というようなことで記載されておりますが、その利用実績数みたいなものでどういう状況にあるのか、最初にお伺いしたいと思います。","respondent":"中山障害者福祉課長","answer":"平成２４年度の実績ですが、基本相談支援ということで４,４４０件ほどの相談を受けているところです。地域活動支援センター事業のほうでは、利用者が延べ人数ですけれども７,０４７名ということで、大変活用されているところです。","id":"exchange-044"},{"speaker":"塚本委員","kind":"質問","question":"キャパシティ一杯一杯でご利用されているというお話を伺いしましたけれども、品川区内にはこういった居場所というのですか、お伺いしたいと思います。","respondent":"中山障害者福祉課長","answer":"精神障害の方の居場所支援といたしまして、憩いの場ですとか、それから地域生活サポート２４事業なども行っているところです。区内に３カ所、そういう形で居場所支援ということで行っておりますので、今後考えていければと思っているところです。","id":"exchange-045"},{"speaker":"塚本委員","kind":"質問","question":"１３５ページ、大変に大切だというか、お母様方から利用されるセンターということでお話がありました。平成２４年度に児童センターのあり方の検討会という報告が文教委員会のほうにされていて、その背景というところをまずお伺いしたいと思います。","respondent":"伊崎子育て支援課長","answer":"幼児クラブのお話ということでよろしいでしょうか。幼児クラブにつきましてはご登録をいただいて、ご利用いただいております。","id":"exchange-046"},{"speaker":"塚本委員","kind":"質問","question":"ページで言えば９ページですけれども、２５館で幼児クラブ、定員を定めた登録制が併存していると。これは自主グループだけではないのかと私は認識したのですが、それは、自主グループだけということでよろしいのか尋ねました。","respondent":"伊崎子育て支援課長","answer":"失礼いたしました。親の子育て支援をする自主グループと、あとチャイルドステーションとしまして、ご登録をいただきご利用をいただくという仕組みもとってあります。","id":"exchange-047"},{"speaker":"塚本委員","kind":"質問","question":"それで、その狙いですね。登録制という形にした狙いというか背景というのをお伺いしたいと思います。","respondent":"伊崎子育て支援課長","answer":"児童センター、幼稚園ともに、チャイルドステーションという形でご登録をいただくことになっております。登録者の方にご案内をしておりますし、ご相談をお受けするようにもしております。","id":"exchange-048"},{"speaker":"塚本委員","kind":"質問","question":"やっているときに来た人は誰でも受け付けるというような性格に見えるのですけれども、その辺のそごというのか、そういったものが利用者に誤解を与えているようなことはないのかというところをお伺いしたいと思います。","respondent":"伊崎子育て支援課長","answer":"基本的に児童センターは常に開かれている施設ですので、おいでいただいた方について、ご利用していただけないということはございません。ただ、チャイルドステーション事業講座という形でやっているものにつきましては、ご登録の方のみのご利用になります。","id":"exchange-049"},{"speaker":"塚本委員","kind":"質問","question":"これは１０代の方々のための集いの場の事業かと思いますけれども、今、そういった中高生をまちで見かけることが本当になくなったかと思います。１０代の方たちがどういうところで、生活をしているというか、居場所がどうなっているのかという認識をお伺いしたいと思います。","respondent":"伊崎子育て支援課長","answer":"こちらはティーンズタイムとしまして、児童センターの開館時間を延長し、中学・高校生に限ってご利用いただけるという仕組みをとってあります。平成２４年度につきましては見られないところではありますので、さまざまですが、現在もいただけていると考えております。","id":"exchange-050"},{"speaker":"塚本委員","kind":"提案","question":"その辺は、今、ご答弁いただいたことが正しいのかと思います。ここでは一つの提案として、今、現状ではなかなかすぐにというものではないという認識でよろしいか尋ねました。","respondent":"伊崎子育て支援課長","answer":"ティーンズプラザを実施している館につきましては、ほかの館よりも１人多く職員を配置しておりまして、シフトを組む形で、それぞれの時間の事業に対応しております。","id":"exchange-051"},{"speaker":"塚本委員","kind":"質問","question":"ちょっと時間がありますので、１３６ページの生活保護総務費についてお伺いをしたいと思います。２カ月という形で死亡されたままになれば、そういう見守りみたいなことが可能かどうかということを、最後にちょっとお伺いしたいと思います。","respondent":"竹田生活福祉課長","answer":"ご提案の銀行でのチェックということですが、今後研究してまいります。","id":"exchange-052"},{"speaker":"高橋委員","kind":"質問","question":"この６１人以外の非常勤職員の方も含めた生活保護行政に携わっている職員の方々の、安全確保についてお伺いします。この検討結果について、どのようになされたのか、お伺いいたします。","respondent":"竹田生活福祉課長","answer":"防犯カメラについては、本年６月１日から相談室に設置しまして、問題なく順調に運用しています。警察に勤務経験のある方２名を、生活福祉支援員という名称の非常勤職員として採用しています。","id":"exchange-053"},{"speaker":"高橋委員","kind":"確認","question":"突然玄関の鍵をかけられて暴行をくらいそうになった、緊急時に居場所確認ができるＧＰＳを備えた携帯電話を配備したということを伺っています。先ほどのこの２名の警察官ＯＢの方々の職務の範囲、どのような役割を位置づけられているのかということをお伺いします。","respondent":"竹田生活福祉課長","answer":"生活福祉支援員の主な業務ですが、ケースワーカーが家庭訪問する際の同行です。訪問時の役割としましては、ケースワーカーが適切な相談・助言・指導ができるための安全の確保です。","id":"exchange-054"},{"speaker":"高橋委員","kind":"意見","question":"警察官ＯＢの方は大変なご苦労だと思いますが、未然の防止、引き続き配置をお願いいたします。このようなことがあって、それが防げたというようなことがありましたら、最後にお尋ねしますとの意見を述べました。","respondent":"竹田生活福祉課長","answer":"４月から９月までの訪問実績ですが、約３０件です。その際は生活福祉支援員が助けたという事例もあります。","id":"exchange-055"},{"speaker":"高橋委員","kind":"意見","question":"１２９ページの重症心身障害者通所施設の運営費です。大変意義のあるものなのですが、通所事業で延べ２０９人とありますが、１日どれぐらいの方が利用されているかということをお尋ねいたしますとの意見を述べました。","respondent":"中山障害者福祉課長","answer":"こちら、１日の定員が５名ということになっております。現在ですけれども、６名の登録者の方がいらっしゃいまして、大体１日最大で３名ぐらいの方がお越しいただいていることになっております。","id":"exchange-056"},{"speaker":"高橋委員","kind":"質問","question":"１日５名という定員ですが、これは登録３人で、就学前の幼児の方で重症心身障害の方ですね。施設の有効利用も考え、そして就学前のお子さんと保護者のためのことも考えて、その可能性についてはいかがか尋ねました。","respondent":"中山障害者福祉課長","answer":"開始に当たりましては未就学児の方を対象としていたのですけれども、今年の７月から要綱改正をいたしまして、学齢児の方も対象にしたところです。","id":"exchange-057"},{"speaker":"藤原委員","kind":"質問","question":"本日は民生費ということで、まず、本日は決意から始まって、決意で終わるような質問をしたいと思います。各ページの質問をする前に、まず事業部として、区長のこういう思いに対しての決意を説明を求めました。","respondent":"今井制度改革・待機児童対策担当課長、永尾高齢者福祉課長","answer":"そのために区といたしましても、平成２２年から平成２４年までで２,０００人以上、そして今年度ももう５００人近く上げております。約２,５００人の拡大の中で、保育需要の高どまりも踏まえて… 今年度は高齢化率が２０.６％になり、今後も団塊世代の方の高齢化が進むことから、どんどん増えてくると認識しております。","id":"exchange-058"},{"speaker":"藤原委員","kind":"質問","question":"大規模改修が平成２４年度は２園ですが、どういう基準で改修しているのか、教えてください。１３５ページ、どういうふうに訪問しているのか、説明を求めました。","respondent":"永尾高齢者福祉課長、今井制度改革・待機児童対策担当課長、伊崎子育て支援課長、立川保育課長","answer":"成年後見センターの件ですけれども、１２１ページの成年後見制度利用支援事業につきましては、直接的な事業に対する部分になります。それで… 一つの場所でやる実施形態ですが、やはりそういう担い手がいなかったということで、現在は実施しておりません。… すくすく赤ちゃん訪問事業です。","id":"exchange-059"},{"speaker":"藤原委員","kind":"質問","question":"その実態をお伺いしたいのと、それと決算額を３０件で単純に割ると、１件当たり約１３万円強となりますよね。この約１３万円強というのは、私は１３万円強はかかり過ぎるのではないかと思うのですけれども、この金額に対しての区の見解も説明を求めました。","respondent":"永尾高齢者福祉課長、今井制度改革・待機児童対策担当課長、立川保育課長、伊崎子育て支援課長","answer":"ちょっと説明が不十分で申しわけありませんでした。１２１ページの成年後見制度利用支援事業は、個別のケースに対してご本人に対する支援をする取り… 今後、新制度では地域型保育事業として、区の認可によります給付事業となってまいります。ですので、区のほうで条例を定めまして、基準等を定めまし… こちらにつきましては、現在進めております待機児童対策と、また区全体の施設の有効利用という観点から検討を進めてまいります。","id":"exchange-060"},{"speaker":"藤原委員","kind":"質問・要望","question":"もうちょっと明確な答弁をいただきたいのと、保育園の改修という意味では、課長の答弁を伺っていても想像できないのです。「こうなって、ああなって、いずれこうなって、何年にこうなる」という、だからその辺のことを具体的にきちんと教えていただけますか。","respondent":"伊崎子育て支援課長、立川保育課長","answer":"説明が不足していて申しわけございません。保健所で訪問しております方の分まで子育て支援課で購入して、保健センターのほうに渡すという仕組みになっております。 将来的な改築計画につきましては、先ほどご答弁申し上げたとおりです。今後につきましては、今後１０年ぐらいは入所希望のお子様の高どまりが続いておりますので、今後の計画を具体化していきたいと考えております。","id":"exchange-061"},{"speaker":"藤原委員","kind":"質問・要望","question":"私、一般質問でさせていただきましたが、区長会は特別区への移管を積極的に進めているという答弁がありました。現在の状況と、移管に当たっての決意を改めてお伺いします。","respondent":"伊崎子育て支援課長","answer":"児童相談所の移管につきましては、都と区のあり方検討会の中で、それだけ先に取り出して検討するということになっております。さまざま移管に向けてのロードマップ等の検討をしておりまして、そちらをあわせて、区としては積極的に移管を進めていきたいという意思があります。","id":"exchange-062"},{"speaker":"渡部委員","kind":"質問・要望","question":"この辺を教えていただきたいのと、仲のいいグループですよ、趣味のグループですよとかいうのはあると思うのです。品川区高齢者クラブ連合会に入っていないようなところがあるのかどうか、総枠的なところですが、お話を説明を求めました。","respondent":"白鳥高齢者いきがい課長","answer":"実態がこのような状況の中で、４９％ほどがこの町会・自治会単体で、この地域の中で結成されているという状況になります。幾つかのクラブ、まだその結成に至らないというさまざまな要因の中で、相談を受けているところもあります。","id":"exchange-063"},{"speaker":"渡部委員","kind":"質問・要望","question":"先ほどおっしゃっていた任意サークルでしょうか、また町会とも相談をされて、やはり加入していただく。ますます発展させていただきたいと思うのですが、その辺どのような取り組みをされているか、説明を求めました。","respondent":"白鳥高齢者いきがい課長","answer":"そういった中で、いろいろとお隣の地域の方々には、こういったクラブを結成したらどうかというような働きかけも必要ではないかと考えています。そのための支援につきましては、区としてもさまざまな相談を行っていきたいと考えています。","id":"exchange-064"},{"speaker":"渡部委員","kind":"確認","question":"さまざまな観点で研究していただいて、それだけちょっと確認したかったので、よろしくお願いいたします。いろいろなところと話し合いを進めていくのか、どういう形で進んでいくのか、何かビジョンがあれば説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"今回、さわやか信用金庫と社会福祉協議会との協働事業で、見守りネットワーク事業というのを開始いたしました。今後はこの民間企業、いろいろな企業があると思いますので、そことの協力を願いながら進めていきたいと考えています。","id":"exchange-065"},{"speaker":"渡部委員","kind":"質問・要望","question":"高校生から「７時に出されちゃうんだよね」なんていう話を、当然７時までになったから帰されてしまいますけれども、実際にどうでしょうか。８時が７時になった影響というのは、もうそれに慣れているから大丈夫なのか、何か声があったら説明を求めました。","respondent":"伊崎子育て支援課長","answer":"ティーンズタイムの時間につきましては、今年の６月から変更しております。８時から７時になったわけですが、８時まで特別認めているということもございまして、特に困るというようなご意見はいただいておりません。","id":"exchange-066"},{"speaker":"渡部委員","kind":"質問","question":"僕は７時でいいと思っているのですけれども、そういう声もあるのかと思って聞いてたものですから、ちょっと質問させていただいたのですけれども。その１３館をある程度集約するのか、やはり２５館をもって児童センター体制でいくのか、今後の方向性みたいなものをお示しほしいと求めました。","respondent":"伊崎子育て支援課長","answer":"全部で２５館あります。昨年度いたしましたあり方検討会の中で、ただ、今現在は特に数を統合させるとかいったところまでは考えてはおりません。","id":"exchange-067"},{"speaker":"渡部委員","kind":"質問・要望","question":"この体制のまま頑張って続けていただきたいのですが、さまざまな活動をしていくと思っていたのですけれども、いまだそれが全く見えてこない。すまいるスクールと児童センターの関係に聞き直して、教育のときにやります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"こんの委員","kind":"質問・要望","question":"１３０ページの子育て支援事業の中の、そして時間があれば、１２７ページの杖の交付についてお伺いします。そこで、まずこの二つの事業の目的など事業の概要と、区民の方への広報の仕方をお知らせほしいと求めました。","respondent":"伊崎子育て支援課長","answer":"子育て支援ネットワーク講習につきましては、あとは父親の子育てというところがございまして、それとあとネットワーク交流研修というものがあります。","id":"exchange-069"},{"speaker":"こんの委員","kind":"質問","question":"この差異についてお聞きしたいのと、またこの事業の評価をどうされて、説明を求めました。","respondent":"伊崎子育て支援課長","answer":"ですので、お申し込みが見込みよりも少なかったということで減額となっております。このそれぞれの設定の年代のお子さんを持つ方、あとは特に子育て支援ということに興味がある方、地域で子育て支援の活動をしていらっしゃる方です。","id":"exchange-070"},{"speaker":"こんの委員","kind":"質問","question":"我が子の変化のサインをどういうふうに親として見ていったらいいのか、いろいろと本当にこれから大変だし、悩むという会話があったわけなのです。年１回という講習もありますので、これをもっと展開していくべきではないかと考えておりますけれども、いかがか尋ねました。","respondent":"伊崎子育て支援課長","answer":"現在のところは定員３０名程度でやっておりますので、これは事業の実施上の講師の都合とか、こういった形で実施しております。こちらが拡大できるかどうかについてはさまざまな課題がありますので、前向きに検討していきたいと考えております。","id":"exchange-071"},{"speaker":"こんの委員","kind":"質問","question":"１０月、「誰にでも起こり得る思春期の心の病」として、品川区の中にある小児精神科医のお医者さんの講座でしょうか。年に１回講演会を設けましょうというのがあるのですが、お母さんたちがご自分たちでされようとするところへ働きかけるというのはいかがか尋ねました。","respondent":"伊崎子育て支援課長","answer":"子育て支援課といたしましては、今、募集をしています。それぞれのＰＴＡの独自の考えがあると思いますので、必要であれば、こちらから講師のご紹介などはしていきたいと思います。","id":"exchange-072"},{"speaker":"こんの委員","kind":"質問・要望","question":"そういった意味からすると、この講習には少しお母さんたちとの距離があるかと私は思っております。前向きな検討ということですので、今後、ぜひよろしくご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"向委員","kind":"質問","question":"今、区内の外国人の方で国保の加入者の方というのは、大体５,０００人いかないぐらい、平成２３年度だと多分４,６００人ちょっとですかね。どういった形で対応されているのかというのをお伺いしたいのですけれども、そのあたり、補足を加えてちょっと簡単に説明をお願いします。","respondent":"間部国保医療年金課長","answer":"その申請日に当たりまして、確実に海外に行かれていたかどうか、このようなチェック。それと委員からもお話がありましたけれども、現地で発行された領収書やそれにかわるもの等のチェックをしています。","id":"exchange-074"},{"speaker":"向委員","kind":"質問","question":"そういった現地で取得してきた証明書のたぐいというのは、翻訳も大事な一つの手段だと思うのです。そういった領収書とかその他診療内容の翻訳というのは、今、どういうふうにして精査をされているのか尋ねました。","respondent":"間部国保医療年金課長","answer":"ただ、翻訳が困難な場合につきましては、我々職員対応ということでやっている部分もあります。ですから、これは２３区一括して、そういうような海外療養費の業務を委託できないかということも現在検討を進めているところです。","id":"exchange-075"},{"speaker":"向委員","kind":"質問","question":"ちょっと前に大阪府警が摘発した分だと、２年間近くの間で９件の虚偽申請２４０万円ほどということで、３桁に行くわけですよね。そういうのは、今、されているのか尋ねました。","respondent":"間部国保医療年金課長","answer":"ただいまのところ、お墨付きは必要はないということで、処理しています。","id":"exchange-076"},{"speaker":"向委員","kind":"意見","question":"もう一つお尋ねしたいのが、後期高齢者医療でしたら２０４ページ、介護保険だと２１７ページにちょこちょこと各事務について金額も載っております。そこに請求する事務だと理解しているのですが、これについて補足等があれば、お願いしますとの意見を述べました。","respondent":"間部国保医療年金課長","answer":"そういうものもあります。我々が７割の保険給付分については損害を保険会社を通じて取り戻すというような対応になりますが、例えばこの事業を進めている中で一番の問題点は。","id":"exchange-077"},{"speaker":"向委員","kind":"質問","question":"ここでお尋ねしたいのが、国保の加入者への呼びかけ、広報というのは一つ大事なことだと思っています。品川区でこういった広報の主な形態、どういうふうに呼びかけをして、早目の事務対応につなげているかを説明を求めました。","respondent":"間部国保医療年金課長","answer":"この事故が起きたときの対応ですが、まず、そのまま保険証を使っていただいて構いませんという形になってあります。治療が全部終わりまして、その７０万円については損害保険会社や加害者のほうに請求して、取り返していくという形になるものです。","id":"exchange-078"},{"speaker":"向委員","kind":"質問・要望","question":"保険に加入されている方、そういったことを書いていただくような、わかりやすくするような周知徹底がされているかを教えてほしいと求めました。そういった資質といいますか、どういった方が担当されているのか、説明を求めました。","respondent":"間部国保医療年金課長","answer":"専門機関が実施する研修会その他、あと自己学習にもなりますが、勉強していただいて対応されているです。ただ、費用がかかるわけですが委託がいいのか、そういう点は随時検討してまいりたいと思います。","id":"exchange-079"},{"speaker":"向委員","kind":"質問","question":"やはり保険会社の方は本当にプロですから、症状を早目に固定されてしまう、まだ時間が経過しないとわからないことも交通事故は多いですよね。今回、会計のほうでこの金額、１８９ページだと５５１件の３,７００万円少々か尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"成果報告書の１２５ページのひとり暮らし高齢者についてお聞きしたいと思いますけれども、それぞれ一緒に教えていただきたいのと、あとひとり暮らし高齢者がどれだけ区内にいるのかという人数を説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"ひとり暮らしの高齢者については、合計いたしまして８,３１５人です。なおかつ周囲５００メートルに二親等以内の親族がいない世帯ということで、高齢者のみの世帯ということで、１万９７４人となっております。","id":"exchange-081"},{"speaker":"石田（ち）委員","kind":"質問","question":"この案内、こういうものですよというパンフレット的なものもいただいたのですけれども、ちょっと分かりづらいかとも思うのです。ＰＲというか周知というか、これだけまだ数が少ないというのは、区はどういうふうに考えているのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"こちらの設置については、ケアマネジャーを通じてご相談に応じるという場合が非常に多くなっています。全部確認しておりますので、あとまた本人のほうからご希望があれば、その相談を受けるという形をとっているところです。","id":"exchange-082"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それとあと、ケアマネジャーの方は、皆様こういうものがあるということはきちんと周知されて知っているのでしょうか。ですので、どんどんＰＲの強化などを進めていってほしいと求めましたが、いかがか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"この火災安全システム、自動消火装置の対象者ですけれども、おおむね６５歳以上のひとり暮らし等の認知症の高齢者という定義になっております。","id":"exchange-083"},{"speaker":"石田（ち）委員","kind":"質問","question":"それと、あと、パンフレットのほうも、もうちょっとわかりやすく、私も見ていても何がどういうふうになっているのだろうかと思うのです。平成２４年度がこの助成団体が２８団体ということですけれども、これは町会・自治会を中心にということですけれども、内訳をちょっと説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"町会と自治会のそれぞれの内訳というのは、今、すぐに数えられないのですけれども、もう少しお時間いただきたいと思います。","id":"exchange-084","title":"町会・自治会支援"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで孤立死を未然に防ぐということで、東京都監察医務院調べで、平成２４年度の孤立死亡数２９７人と出ていまして、７割が６０歳以上。そうやって地域で見守って助け合ってというのもあるのですけれども、区として孤立していく原因は主にどこにあるとお考えか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"誘われても、あまりそういうところに出向くのはどうもという方が多いのではないかと考えています。やはり本人の意向もありますけれども、民生委員や町会の方のご協力も得ながら、見守りの関係をつくっていきたいと考えているところです。","id":"exchange-085"},{"speaker":"石田（ち）委員","kind":"質問","question":"このよさを活かすためにも自治体が実態調査を行って、やはり経済的・健康的というのはなかなか地域でも入っていきづらい面だと思うのです。ですので、実態調査等々、行政が入っていくべきだと思いますけれども、いかがか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"そういうものも通しながら、孤立しがちな高齢者を確認して、対応していきたいと考えております。それと、先ほど地域見守りネットワークの自治会と地域見守りの件数の内訳ですけれども、自治会が１１団体で町会が１３団体となっております。","id":"exchange-086"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"もう時間がないですけれども、この緊急通報システム、こういったなかなか外に出られない方の命を守るというところには有効だと思いますので、ぜひ無料化を検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"渡辺委員","kind":"質問","question":"成果報告書１２５ページで、高齢者外出習慣化事業で伺います。定員というのでしょうか、そのあと回数がわかれば、１回当たりのもろもろ含めての経費的なものが１人当たり幾らなのかがわかれば説明を求めました。","respondent":"白鳥高齢者いきがい課長","answer":"そういう中で交流の輪も広げていきたいということで、実施をしているものです。会費につきましては、参加費をお一人４００円ということで頂戴しているものです。","id":"exchange-088"},{"speaker":"渡辺委員","kind":"質問","question":"それと教室終了後、教室終了後というのは、この事業自体は、僕はこれからも発展していってほしいという前提で伺います。そういう意味では、大もとの外出習慣がままならない方というのは、本来というか、理想とすべき対象者というのはどういう位置づけなのか尋ねました。","respondent":"白鳥高齢者いきがい課長","answer":"対象の年齢ですけれども、おおむね６５歳以上の方で、この会場に自力でお越しいただける方。そういう中で、ご自身が実際に申し込みをしていただいているという状況です。","id":"exchange-089"},{"speaker":"渡辺委員","kind":"質問","question":"そういう中で、まず、行政の段階的な経過だと思いますが、場所の問題、今はシルバーセンターが展開している。今後こういうことを考えているみたいな場の提供という意味と、対象者、今後こう広げていきたいのだというような中長期を含めた目標を説明を求めました。","respondent":"白鳥高齢者いきがい課長","answer":"今現在３会場、昨年度、大井林町のほうまで拡大をしたところですけれども、やはり調理場がなければならないということが、一つ問題です。","id":"exchange-090"},{"speaker":"渡辺委員","kind":"質問","question":"金額どうこうではないないのですけれども、以前は喫茶店というくくりで伺ったことはあったのですが、この趣旨にすごく合ってくる気がしています。どうですか、地元の食事処、あるいは喫茶店等の活用というのはいかがか尋ねました。","respondent":"白鳥高齢者いきがい課長","answer":"この事業の目的でありますそのものだと私も認識していますので、研究しながら、今後進めてまいりたいと考えております。栄養学ですとか、難しい話ではございませんけれども、簡単な体操も取り入れた内容でもって実施しているものです。","id":"exchange-091"},{"speaker":"山元委員","kind":"質問・要望","question":"次に隣の１２７ページ、次の１２８ページ、マッサージサービス経費についてお伺いしたいと思います。初めに、１２６ページの同行援護につきましてお伺いしたいと思います。","respondent":"中山障害者福祉課長","answer":"同行援護についてのお尋ねですが、平成２３年度までは、隣のページの地域生活支援の移動支援で対応していたところです。法律が変わりまして、視覚障害をお持ちの方のいわゆるガイドヘルプにつきましては、同行援護という形で給付事業に移ったところです。","id":"exchange-092"},{"speaker":"山元委員","kind":"質問・要望","question":"時間を見ると、１万６,４５３時間というすごい時間で、区内にはどのくらいの視覚障害者の方がいらっしゃるのか。できれば、この中で年代別、大雑把でいいのですが何十代というか、使っている方たちの数がわかれば教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"区内に視覚障害者の方はおよそ５７０人いらっしゃいます。６０代が合わせまして１１２名、７０歳以上の方が３１２名ということで、総合計５７０名になっております。","id":"exchange-093"},{"speaker":"山元委員","kind":"質問・要望","question":"実際に、この同行援護というのは、具体的にどういうところにご一緒していただけるのでしょうか。教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"社会参加の支援ということも兼ねていますので、お買い物に行きたいであるとか、そういったことでも使われているものです。それで、すみません、目的ごとのサービスのランキングについては、把握していないところです。","id":"exchange-094"},{"speaker":"山元委員","kind":"質問・要望","question":"実際、こういう方々が最大何時間くらい使えるのか教えていただきたいのと同時に、または２３区共通の時間とかはあるのでしょうか。使える時間というのは。","respondent":"中山障害者福祉課長","answer":"２３区統一の時間数というのはないですけれども、おおむね区内の方は、月当たり五、六十時間使っていらっしゃるところです。","id":"exchange-095"},{"speaker":"山元委員","kind":"質問・要望","question":"後ほど、五、六十時間使っている方がどのくらいいらっしゃるのか教えていただきたいということと、また、同行援護は、目の不自由な方であれば、全員が使えるのか尋ねました。","respondent":"中山障害者福祉課長","answer":"対象者を特定するための評価指標がありまして、そちらの指標を使ってアセスメントをした方を対象に、ご利用いただいているところです。先ほど手帳をお持ちの方は５７０人だったのですけれども、登録人数としては、平成２４年度は６０人ということになってあります。","id":"exchange-096"},{"speaker":"山元委員","kind":"質問","question":"多少見える４級、５級というのでしょうか、同行援護は使えるのでしょうか。それとも使えないのか尋ねました。","respondent":"中山障害者福祉課長","answer":"実際、若干見えるような方は、アセスメントをした結果では、多分該当から外れてしまうと考えています。何となく見える方については、アセスメントをした結果、対象から外れているということになっております。","id":"exchange-097"},{"speaker":"山元委員","kind":"質問","question":"先ほど、課長から、お医者様とかは同行援護で使えるという話でありましたけれども、基本的に、仕事のためには同行援護というのは使えないと聞いていますが、それは事実なのか尋ねました。","respondent":"中山障害者福祉課長","answer":"就労目的についての同行援護は使えないということになってあります。","id":"exchange-098"},{"speaker":"山元委員","kind":"質問","question":"実際、これはどうなのでしょう。自分自身のスキルアップのためというのは、仕事としてみなされてしまうのか尋ねました。","respondent":"中山障害者福祉課長","answer":"相談の中でどちらになるのかというのを見きわめながら、対象となる、あるいは対象とならないという形をとらせていただいているところです。もしお悩みのケースとかがありますれば、具体的にこちらにご相談いただければと考えています。","id":"exchange-099"},{"speaker":"山元委員","kind":"質問・要望","question":"次に、日常生活用具給付についてお伺いしたいと思います。その辺を教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"こちらは平成２４年度実績で合計１３件になります。こちらも１件ほど支給しています。","id":"exchange-100"},{"speaker":"山元委員","kind":"質問","question":"その中に、デイジー再生機というものもあると思いますけれども、これもやはり全員が給付されるわけではないと思いますが、その辺は、使えるにはどういう条件が必要か尋ねました。","respondent":"中山障害者福祉課長","answer":"デイジーは読み上げ機能のものだと思います。その方にとって、そういった判断をこちらでさせていただいて、具体的に支給の対象となるかならないかという判断をさせていただいているところです。","id":"exchange-101","title":"町会・自治会支援"},{"speaker":"山元委員","kind":"質問・要望","question":"お年を召していると、ちょっと目が見えたとしても、夜見えなかったり、さまざま条件があると思いますので、ぜひともお話を聞いていただいて、枠にはめずに使えるようにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"西本委員","kind":"質問","question":"それから、幼児の二人同乗用自転車のレンタルですが、この内容はどうなっているのでしょうか。児童センターのところでは、職員の採用はどのような状況か尋ねました。","respondent":"立川保育課長、伊崎子育て支援課長、堀越人事課長","answer":"延長夜間保育をご利用になる保護者の方と園長が１対１で面接をいたしまして、具体的に聞き取った上で、適正な利用をお願いしています。幼児二人同乗用自転車レンタルです。こちらは、現在２２台貸し出しておりまして、まだ一定の需要があると考えています。児童センターの職員数ですけれども、現在６４名の職員がおります。","id":"exchange-103"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひ、児童センターとしての配置をしてほしいと求めましたが、まず、その実態がどうなっているかをお聞かせください。その中では、こういう第三者評価をするための助成金というのは、非常に有効活用ができるのではないかと思いますが、いかがか尋ねました。","respondent":"立川保育課長、伊崎子育て支援課長、堀越人事課長","answer":"量的拡大、今後とも各事業者には第三者評価制度を活用していただいて、積極的に保護者の方に評価内容については公表していただきたいと指導してまいります。一時の利用でしかないものですので、子育て世代の方たちの経済的な負担を考え、貸し出しは継続していきたいと考えております。職員の配置の件ですけれども、実際、保育園から児童センターのほうに、異動等によって配置をしているという面もあります。","id":"exchange-104"},{"speaker":"西本委員","kind":"質問・要望","question":"まだ需要があるということですが、状況を見据えながら、見直しをするなり考えていただきたいと要望しておきたいと思います。しっかり、児童センターは児童センターの職員として、ノウハウを構築していくという人材育成という形を考えられているのか、そこをお伺いします。","respondent":"今井制度改革・待機児童対策担当課長、堀越人事課長","answer":"そして設置基準につきましては、その中で保育の質、そして設備運営基準なども確認してまいります。 実際に異動して、一定の年数在籍して、児童センターの中核職員として育成していますので、そういう形で配置管理を行っていきたいと考えております。","id":"exchange-105"},{"speaker":"飯沼委員","kind":"質問","question":"１２６ページの就労移行支援等、１２８ページの通所施設関係、そして１３３ページの延長夜間保育の３点お伺いします。７,４４９万８,０００円予算化されていますが、この予算の使い方、そして障害者の就労支援の現状の評価と今後の課題についてお知らせください。","respondent":"中山障害者福祉課長","answer":"それから、一般就労ができない方については福祉的就労の場ということで、就労継続支援Ａ型とＢ型がそれぞれあります。障害者の持てる能力を活かしながら、経済的にもできるだけ自立の方向へということで、向かっているのが現在の状況です。","id":"exchange-106"},{"speaker":"飯沼委員","kind":"質問","question":"わかる範囲でいいのですけれども、人数をお伺いします。一般就労につながった方、福祉就労のところ、別々に仕事につながった人数も、できれば実人数で説明を求めました。","respondent":"中山障害者福祉課長","answer":"げんき品川の相談実数ですけれども、１,５９２人というのは延べ人数になります。実際に平成２４年度、企業に就職した人数ということですが、こちらは２５人になっております。","id":"exchange-107"},{"speaker":"飯沼委員","kind":"提案","question":"専門職の配置をまずお伺いしたいのですが、そして障害者福祉課に配属をされています専門職の人数を教えていただきたいのが、まず初めです。専門職の配置の充実を求めますが、いかがか尋ねました。","respondent":"中山障害者福祉課長","answer":"受け入れ前の支援、受け入れ後の支援ということで、長く継続して就職できていくようにという支援をしています。げんき品川のほうですけれども、今手元にありませんので、後ほどお答えしたいと思います。","id":"exchange-108"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私はここを強く求めますが、これをもう１回お願いしたいのと、その上で相談に乗ってほしい。ぜひぜひ品川区でも、げんき品川、たいむにおいても、専門職の充実をお願いしたいのですがいかがか尋ねました。","respondent":"堀越人事課長","answer":"区としての、自立それから社会参加等を進める上で、そういった障害のある方の雇用は大変重要な課題であるという部分では認識しております。今後も、お持ちの能力ですとか適正、そういったものを考えながら、適正に応じた採用を行っていきたいと考えているところです。","id":"exchange-109"},{"speaker":"飯沼委員","kind":"質問・要望","question":"何とかこの苦しい状況を改善してほしいという声が届いています。通所施設の定員に対して利用状況を教えていただきたいのと、現状の認識と今後の対策もあわせてお伺いいたします。","respondent":"中山障害者福祉課長","answer":"来年の４月になりますと、上大崎の旧ＡＣＣ跡施設を利用しまして、新たに就労継続Ａ型とＢ型の施設が１０人分ずつできます。その整備が終わりますと、平成２７年４月には５０人の就労継続Ｂ型ということで、ふれあい作業所が変わってまいります。","id":"exchange-110"},{"speaker":"飯沼委員","kind":"質問・要望","question":"定員の全体平均で１.３２倍受け入れているということなので、１日の生活の場であって、ぜひ改善をしてほしいと求めました。ぜひ通所施設を増やしていただきたいという声が出ていますので、ぜひ増設を求めたいと思いますが、いかがか尋ねました。","respondent":"中山障害者福祉課長","answer":"特別支援学校および城南特別支援学校の卒業の見込みということです。そういった推移を見ながら、今後、施設の整備については考えていきたいと思っているところです。","id":"exchange-111"},{"speaker":"飯沼委員","kind":"質問・要望","question":"保育園のところなのですけれども、本日、何人かの方から延長夜間保育の質問がありました。十分配慮していただきたいのと、それを取り除く改善をぜひ行っていただきたいので、この点を答えてください。","respondent":"立川保育課長","answer":"お子さんが数少なく残っているような状態なのですけれども、保育者といたしましては、そうした状況におきましても常に最善の保育を実施しています。ですから、保護者が利用しづらいという環境については、各園に配慮を求めていきます。","id":"exchange-112"},{"speaker":"若林委員","kind":"質問・要望","question":"４点ありますが、最初に１点お聞きして、あとで３点伺いたいと思います。私立幼稚園について理解を進めることの要望に対しての答弁がありまして、研修についてもお願いしていきたいというご答弁をいただきました。","respondent":"立川保育課長","answer":"区ではアレルギー対応につきましては、私立の施設を含めまして定期的に研修会を実施しているところですので。幼稚園協会が実施する研修会等がありますので、そういう機会に、アレルギー対応の研修についても開催してほしいということを要望しております。","id":"exchange-113"},{"speaker":"若林委員","kind":"質問・要望","question":"改めて確認、また区の要望もしている中で、各職員がスキルを身につけて今努力をしていますという確認をぜひしてほしいと求めましたので。続いて２１８ページの居宅介護サービスについてですが、いわゆるデイサービスで、障害者が利用している実態はあるか尋ねました。","respondent":"立川保育課長、中山障害者福祉課長","answer":"ご指摘のありました私立幼稚園に対するアレルギー対応に関する研修につきましては、機会を捉えて要望していきたいと考えております。それに伴いまして、入園、在籍する児童も増えたことから、助成につきましても増となったところです。区内の高齢者施設、こちらはそれぞれのデイサービスセンターのうち、各２名までは障害者枠ということでとっていただいているところです。","id":"exchange-114"},{"speaker":"若林委員","kind":"提案","question":"一つ最後の提案になるかと思いますけれども、今回４カ月が３カ月になりましたが、理想です。品川はみこしが盛んですので、そういう提案をしますので、答弁も時間があればとの意見を述べました。","respondent":"立川保育課長、中山障害者福祉課長","answer":"事務改善をやったばかりなのですけれども、保護者の利便性ということを考えますと、今後とも改善に向けて研究していきたいと考えております。 障害者の方が少しでも多くお祭りに参加して楽しんでいただけるよう、ご提案のことも含めて検討してまいりたいと思います。","id":"exchange-115"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"社会福祉費から１３４ページのぷりすくーる西五反田運営費、１３６ページの品川児童学園運営費、この辺で確認をさせてほしいと求めました。４月からはどうなるかわからない状況はありますけれども、年度が変わって平成２６年４月からは、その辺を区に確認をさせてください。","respondent":"立川保育課長","answer":"新制度のいわゆる幼保連携型の認定こども園ということだと思いますが、学校法人または社会福祉法人、それから地方自治体のみが運営できるという規定になってあります。","id":"exchange-116"},{"speaker":"鈴木（真）委員","kind":"質問","question":"継続して、さっき言ったようにどうなるかわからないですけれども、運営自体がいいということなのですか。それとも、今のＮＰＯ法人はだめという、その辺はどうなのか尋ねました。","respondent":"立川保育課長","answer":"詳細について明らかになっていない現状ですが、仮に認定こども園化ということになりますと、やはり運営形態という部分については見直しを図っていかなければならないと考えております。","id":"exchange-117"},{"speaker":"鈴木（真）委員","kind":"確認","question":"ぷりすくーるだけを考えたときに、あそこは社会福祉法人にならなくてはいけないのでしょうかという、学校法人なり。そこはちょっと確認させてください。","respondent":"立川保育課長、金子子ども未来事業部長","answer":"ぷりすくーるにつきましては、公設民営で実施していますけれども、運営形態自体を認定こども園化するということになりますと、現状の法人の形態では運営できないです。 設置主体は、先ほど課長が申し上げましたとおり、ここだけ決まっているのです。明確になった時点で、このぷりすくーるも含めた私どもの幼保一体施設をどうしていくかということを検討したいという考え方に立っているところです。","id":"exchange-118"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"来年３月から、ＮＰＯから変わらなければいけないといった場合は、指定管理の契約自体がどうなるのかとその辺の心配があります。そこら辺も早めに、先方また我々にも教えてほしいと求めましたけれども、その辺。","respondent":"立川保育課長","answer":"大型の遊具についてのご質問ですが、こちらにつきましては、年度ごとに計画的に取り替えの必要なものについては取り替えるということで対応を図っているところです。","id":"exchange-119"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"順次計画的というか、なるべく早く要望に応えていただけるように、その辺もご判断をよろしくお願いいたします。その辺はどのように考えたらいいのか、答えるよう求めました。","respondent":"中山障害者福祉課長","answer":"現在、そういう意味では相談につながるまでに３カ月お待ちただいているような状況があります。こちらとしましては、部屋の工夫も含めまして、できるだけ３カ月の相談を短くするような努力をするために、児童学園と打ち合わせをしています。","id":"exchange-120"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"区に対して、不満を持たせないように、なるべくその辺もうまくつないでもらいたいと思います。この間私も控え損なったのですけれども、改築はどのくらいの建物の方向性を考えているのか、この点についてお答えをいただきたいです。","respondent":"中山障害者福祉課長、柏原行財政改革担当課長","answer":"建替え後は、かなり広い面積がとれるものと考えられております。 建物につきましては、今の面積に対しての建てられる建物は、かなり大きなものが建てられるという、建ぺい率等々はありますので、そういったところを踏まえながら、ボリュームはチェックしていきたいと思います。","id":"exchange-121"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"担当の課長がどこまで答えられるかわからないですけれども、やはり、これが障害者施設だけで１本で決まったのかどうかも確認したかったところです。もちろん、障害者施設として利用していただきたいというのは、その中でいろいろな要望事項もそれぞれのところから出ています。","respondent":"柏原行財政改革担当課長","answer":"先ほども申しましたように、かなりのボリュームの建物が考えられます。そういったものを確保した上で、どういったところで使えるか、総合的な判断も踏まえて考えていきたいと考えております。","id":"exchange-122"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"障害者も高齢化してくるという中で、障害者の高齢化ということも踏まえた上で、今度は高齢者施策との兼ね合い。区として、どういうつながりを持って、連携をとっていらっしゃるのか、健康福祉事業部としての考え方をお答えほしいと求めました。","respondent":"早津健康福祉事業部長","answer":"区の人口が平成３７年にピークを迎えますが、その後も高齢者人口はずっと増え続けていくです。ますます障害者施策と高齢者施策の連携を深めて、長期的な物の見方を持ちながら、施策を展開していきたいと考えています。","id":"exchange-123"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"いろいろな立場で品川区の要望を訴えていると思うのですが、現実的に一番動いているのは、区長会での動きだと思っています。いろいろそういう都に対する要望も出ていると思うのですが、現状的なものを確認させていただきたいと思うのですが、。","respondent":"濱野区長","answer":"あり方検討会がいったん閉じたような状態で、しかしそういう中でも、児童相談所だけはぜひ移管をということで運動を繰り広げてまいりました。ただ、これは本当に区長会として、懸命になってやり遂げようという決意で進んでいるところです。","id":"exchange-124"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひ区長の力で、実現に向けて頑張ってほしいと求めました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-125"},{"speaker":"原委員","kind":"質問・要望","question":"この２００万円を、具体的に中身を教えていただきたいということと、何で市民なのか、区民でもいいのかという、その辺はお話いただきたい。それから１２３ページ、これは２カ所で８９６万円となっておりますけれども、これも具体的に教えてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"地域の身近な存在として、きめ細やかな、行政ではできないような細かい生活の中でのサービスをやっているところです。さらに５法人のほかにクリオスや新井湯にも助成をしているところですけれども、基本的な考え方として、法人に対して無償貸与する。","id":"exchange-126"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、ちょっと確認しなくてはいけないのですけれども、不合理であるような契約自体がないのかどうか。いろいろ展開を大きく発展させていかなければならないという思いが私自体にあるものですから、その辺についてもお答えほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"バランスを持った資金のやりくりが法人の中で必要となっておりまして、当然、安定的で継続的な経営が求められています。出したと同時に、この中で履行されないことについての規定等はきちんと明文化されておりまして、その中での正式な契約でとり行っているところです。","id":"exchange-127"},{"speaker":"原委員","kind":"質問・要望","question":"世間が何と言おうと大いに活用していただきたいと考えています。そうなのかという思いも私自体があるものですから、１点ご答弁で漏れたのが、その辺をもう一つほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"品川区の５法人に対するやり方というのは、他区にはない独特のやり方をしていると思います。その議論を聞いて、また助言、指導しています。","id":"exchange-128"},{"speaker":"あべ委員","kind":"質問・要望","question":"これは１食１万２,０００円余の計算になってしまうのでけれども、このコストが妥当と思われているかどうか、お考えを伺いたいと思います。区として、何らかの形で支援をしていただきたいと思うのですが、お考えはいかがか尋ねました。","respondent":"永尾高齢者福祉課長、立川保育課長、白鳥高齢者いきがい課長、伊崎子育て支援課長","answer":"認知症の方を支えるにはどうしたらいいか、どんなことがあったらいいかというような夢を語り、それを実現するための検討を始めたところです。… 委員お尋ねの幼保連携型認定こども園に移行する場合、現状、各保育園の保育士に対しては情報提供を進めているところです。… それから、外出習慣化事業で１人当たりのコストがおおよそ１万２,０００円余というお話です。栄養士３名をこちらに配置しまして… こちらは思春期のお子さんとのコミュニケーションのとり方やコーチングなど大変好評を得ております。","id":"exchange-129"},{"speaker":"あべ委員","kind":"提案","question":"先ほど、他の委員からもご提案がありました既存の飲食店を使ってというのも、私はすごくいい方法だと思います。１回当たりのコストを下げていけば、同じ金額でより多くのサービスが提供できるわけですから、ご検討をほしいと求めました。","respondent":"白鳥高齢者いきがい課長","answer":"そのために座ってしまうと。多くの方が利用できないというようなこともあるのですけれども、やはりパイプ椅子……。","id":"exchange-130"},{"speaker":"あべ委員","kind":"質問","question":"どうして途中で８万円だけ足してあるのかというのがよくわからなかったので、その理由、この数字の意味を教えてほしいと求めました。何で流用が必要だったのか、私よくわからないので。","respondent":"永尾高齢者福祉課長","answer":"日常生活支援総合事業ですけれども、こちらは要支援の方を対象に、今すぐ答えが出ません。かなり個別性が高いものがございまして、当初目標としていたものに比べると、どうしても現実追いつかなかったというところが原因だと考えております。","id":"exchange-131"},{"speaker":"あべ委員","kind":"質問・要望","question":"別の機会にでも伺うことにしたいと思いますが、かなり執行率が低め、低めになっているように感じております。ですから、大変言い方は悪いですけれども、多目の予算を何とか使おうとしているかのような組み立てになっているように感じております。","respondent":"永尾高齢者福祉課長","answer":"なかなか外に出るのが難しい方がたくさんいらっしゃる中で、どうしても講座を設置すると、基本的な人件費がかかってきてしまうという難点があります。これからも、要介護にならないような施策のために工夫をしていきたいと考えております。","id":"exchange-132"},{"speaker":"浅野委員","kind":"質問","question":"成果報告書の１２７ページの福祉タクシー、それと１３３ページの児童福祉施設費、障害者施設なども含めてお伺いしたいと思います。そういうところで実施をされたのかどうかということと、どういうところをメインにやられてきたのかとか、そういう特徴的なところを説明を求めました。","respondent":"立川保育課長","answer":"保育園、幼稚園関係ですけれども、公立の幼稚園、保育園、また幼保一体施設全ての園で、非構造部材耐震対策については実施いたしました。","id":"exchange-133"},{"speaker":"浅野委員","kind":"質問・要望","question":"棚とか時計などが多かったと伺っておりますけれども、そういう施設に関しましては、指導していっていただきたいと思うものであります。区では非構造部材の耐震対策をやるけれども、認証保育所とか私立の認可保育園についても、何らかのアクションをとられたのかどうか説明を求めました。","respondent":"立川保育課長","answer":"私立保育園、認証保育所等につきましては、東京都で耐震対策についての事業を実施しておりますので、そちらの申し込みを、区で取りまとめたという状況です。","id":"exchange-134"},{"speaker":"浅野委員","kind":"質問","question":"都のほうでということですが、耐震対策は認識しておるのですけれども、同じく非構造部材についてもやられたのか、また私立の保育園も、そういう意味では全部、実際に行われたのか説明を求めました。","respondent":"立川保育課長","answer":"今、お話しましたのは非構造部材の耐震対策ということで、東京都のほうで事業化しています。","id":"exchange-135"},{"speaker":"浅野委員","kind":"質問","question":"障害者の施設ですとか、さまざまな社会福祉施設がありますけれども、こちらについては全て行われているのか。区の直営でありますとか、委託、指定管理とかさまざまありますけれども、それらについても、それぞれ説明を求めました。","respondent":"柏原行財政改革担当課長","answer":"そのほかもろもろの施設があります。それからお子さまのいるような施設ということで、あと二次避難所になるようなところであるとか、こういったところは順次進めていく予定です。","id":"exchange-136"},{"speaker":"浅野委員","kind":"質問","question":"このような施設関連につきましても順次やられるということですので、また決算が出てきたらお伺いしていきたいと思うわけであります。タクシーのほうは私の計算によると約８割の計算で、燃料費の助成が９５％くらいだと思いますけれども、この数字で正しいのか説明を求めました。","respondent":"中山障害者福祉課長","answer":"委員お尋ねの福祉タクシーの利用率につきましては、交付枚数から利用枚数を勘案しますと、おおむね８割程度の利用率と考えていいかと考えています。","id":"exchange-137"},{"speaker":"浅野委員","kind":"質問","question":"おおむね８割ということで、使用期限等がありますので使われ方はさまざまだと思いますが、交付額につきましては、今までもなかなか上げていただけないというのはあると思いますけれども、全額利用されていない主な理由は、どういうところにあるのか説明を求めました。","respondent":"中山障害者福祉課長","answer":"そういった中で、ご利用される方の利用目的が、例えば通院ということになりますと、利用が集中することがあろうかと思います。そういった中で、交付はされたものの未執行のものが出てしまったということが、一つの原因として挙げられると思います。","id":"exchange-138"},{"speaker":"浅野委員","kind":"質問・要望","question":"そういうところにも焦点を当てて、検討をしていただけないかという要望ですけれども、いかがか尋ねました。","respondent":"中山障害者福祉課長","answer":"福祉タクシー券の交付、そして自動車燃料費助成というのは、少しでも外出支援の一部に役立てていただければということでやっております。今のところ、両方の支給は難しいと考えていますが、利用の実態等を見ていきたいと考えています。","id":"exchange-139"},{"speaker":"須藤委員","kind":"質問","question":"成果報告書１２１、１２２ページで何点か、本日もう出ましたので、成年後見人で質問させてもらいます。先ほどお聞きしたら、どんどんと利用者が増えてくるのではないかと思うのですが、そのあたりの対応としてはいかがか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"品川区では、区長申し立ての件数ですけれども、現在２０８件の区長申し立てが決定されておりまして、その方の後見の活動をしています。今後、ただし悪用されないような方法を考えつつ、そういうところを進めるなどの別のやり方についても検討していきたいと考えております。","id":"exchange-140"},{"speaker":"須藤委員","kind":"質問・要望","question":"いろいろな事業をされているのですが、このことをやって、１年たってみて、福祉人材が確保されているのか、定着してきているのか。行政からこういう形でやったのか、事業者から声があったのでこういう事業をやってきたのか、その結果について説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"八潮南特養を中心にやっているのですけれども、ユニット化に対応するためのスキルアップの事業ということで、研修をやっているところです。家族への効果的な支援策検討事業ということで、介護教室等の研修等に出やすくするための方策を検討したりとか、まだ。","id":"exchange-141"},{"speaker":"須藤委員","kind":"質問","question":"内容でなくて、法人から来たのか、行政がやったのか。結果はどうなっているのかということを説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"申しわけありません。訪問介護２級取得受講費助成ということもやっておりますけれども、依然として人材不足というのは続いている状況かと考えています。","id":"exchange-142","title":"町会・自治会支援"},{"speaker":"須藤委員","kind":"質問・要望","question":"いろいろな工夫をされて、しっかり定着して、安心して区民の方が介護できる環境というのをさらに研究してほしいと求めました。１２５ページ高齢福祉費全体で、そのあたりについては、どんなふうに考えていらっしゃるか説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"例えば高齢者クラブ等の会合には必ず説明をしたり、また民生委員協議会の地区の会合にも、警察の方が必ず１年に１回は来て説明をしております。","id":"exchange-143"},{"speaker":"須藤委員","kind":"質問・要望","question":"１２７ページ、いろいろと高次脳の方々からご要望があるのですが、リハビリ。就職活動につながるようなことは、いろいろなことがあると思うのですが、これからどのように考えていらっしゃるか説明を求めました。","respondent":"中山障害者福祉課長","answer":"そういった中で、できるだけ高次脳機能障害の方が社会生活に復帰できるようにという支援をしております。区としても、これからも高次脳機能障害の方の居場所づくり、そして社会生活の支援というところで対応していきたいと考えております。","id":"exchange-144"},{"speaker":"須藤委員","kind":"質問・要望","question":"いろいろなご努力をしていただいているのはわかっているので、感謝申し上げます。家族の方からのいろいろなご要望はいろいろな形で出てこようかと思うので、またいろいろな声を聞いて、ぜひ対応もろもろ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-145"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"介護保険と国保、後期高齢者について、お伺いしたいと思います。介護保険なのですが、平成２４年度末では２０億４,９００万円余という基金残高になるということで確認させていただいてよろしいか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"今、委員ご指摘のとおりで正しいということです。","id":"exchange-146"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１０億円取り崩しても８億円にはならないと思うのですけれども、第５期終了時の８億円余という計画の額も変わってくるのか、その見通しについてもお聞かせほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"実績で見てみますと、実際の保険料収入の中で給付費が賄われているということで、結果的に最初の予定よりも支出のほうが少なくなっているという状態になっています。","id":"exchange-147"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この基金というのは６５歳以上の方の保険料そのものですから、基金に積み増していくのではなくて、そのことについてお伺いしたいと思います。逆に、要介護が９％少ないということになるのですけれども、なぜこれほど軽い認定になっているのかお聞かせほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"品川区の介護認定の方法ですけれども、認定調査がほかの自治体に比べると、かなりきめ細かくやっておりまして、医師の診断書だけの書類上の認定だけではなくて、実際の調査をしたりという内容になっているところから、実態に合わせてやっているという結果になっているところです。","id":"exchange-148"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"要支援１、実態を反映したものにしていただきたいということで常々思っていますし、お願いしたいと思っているところです。私は、生きていけないという実態を改めて伺ってきたのですけれども、要支援の方のサービスの必要性の認識についても改めて伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"要支援をサービスから外すというお話ですけれども、国の会議で検討されている内容でありまして、まだ決定している内容ではありません。要支援１、区といたしましても第６期の計画に向けて、そういう動向も見ながら考えていきたいと考えています。","id":"exchange-149"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はどう考えても、全国平均より９％も要支援が多いというのは、ここのところ区としてもしっかりと見てほしいと求めました。今度は３以上ということで検討されているわけですけれども、問題なのではないかと思いますけれども、その点はいかがか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"今、国で検討されている部分、特養についての検討をされている状態ですけれども、特定施設について、どういう検討になるかというのはこれからになるかと思いますので、一概に今の段階で、どちらが不公平ということは言えないと考えています。","id":"exchange-150"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"お金がある人でもない人でも入れるわけですから、ぜひとも区としては立っていただきたいと強く要望して、国保のほうに移りたいと思います。差押え件数と金額、収納率の件数と金額について、説明を求めました。","respondent":"間部国保医療年金課長","answer":"平成２３年が８５．１１％、平成２２年が８３.３１％ということで、ここ２年で２％ほどアップしております。やや景気が持ち直している部分と、保険料算定を旧ただし書きに変更しまして、納付率が上がっているという状況が見られるところです。","id":"exchange-151"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本人と連絡がとれないのにもかかわらず差押えをするというのは、ぜひともやめていただきたいと思うのですが、その点が１点。今後２０１５年に向けて広域化が進められようとしていますけれども、このことでどう変わるのかということについても説明を求めました。","respondent":"間部国保医療年金課長","answer":"広域化につきましては、制度改革国民会議のほうで、国保につきましては平成２６年から平成２９年の間に都道府県単位化で進めるという報道があります。重ねて保険者に対する財政支援ですとか、現行よりは一歩進んだ内容となっていますので、ご期待していただければと思います。","id":"exchange-152"},{"speaker":"須貝委員","kind":"質問・要望","question":"これを受けて、全国の受給者が引き下げの取り消しを求める審査請求を都道府県に行う運動を進めているということです。区として、自治体として、物価値上がり分の助成は行うのか尋ねました。","respondent":"竹田生活福祉課長","answer":"今般の基準改定は、平成２０年度以降の物価の動向を勘案するという合理的な考え方に基づき適正化が図られたものです。委員ご指摘の、自治体の財政から負担してはどうかというお考えですが、こちらは国の基準で定めている事業ですので、そういう考えはございません。","id":"exchange-153"},{"speaker":"須貝委員","kind":"質問","question":"国のやり方はおかしいではないですか。それは筋が通らないと思うのですが、もう一度、区として、何もしないのかご見解を説明を求めました。","respondent":"竹田生活福祉課長","answer":"検証するには所要の時間がかかりますので、経済状況がその間に若干変わるということはやむを得ないことだと思います。ただ、一般財源で補填するつもりはございません。","id":"exchange-154"},{"speaker":"須貝委員","kind":"質問","question":"次に、先ほどの職員の勤務実態についてお聞きするということで、質問は聞いているのかな、各所管で、窓口で直接いろいろな区民の方と接しています。これの原因によって、何人くらいお辞めになっている方がいるのか、説明を求めました。","respondent":"堀越人事課長","answer":"窓口でのクレーム対応の研修ですとか、職員の対応能力と、職員を守るという観点で行っているところです。申しわけございませんが、そういった観点での退職者数という数字は手元にございませんので、お答えできません。","id":"exchange-155"},{"speaker":"須貝委員","kind":"質問・要望","question":"そして、ここ３年くらいで結構ですが、介護保険、予算は毎年幾らくらい増えているのでしょうか。そして、介護認定者数も、ここ３年くらいでいいのですが、何人くらい増えているのか、説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"申しわけありませんでした。平成２４年３月ですと１万１,５６７件ということで、それぞれ認定率でいくと１５.４％と１５.９％となっております。","id":"exchange-156"},{"speaker":"須貝委員","kind":"質問","question":"何とか介護予防しよう、とめようとして努力をしているわけですが、なぜ増え続けてしまうのですか。私、毎年言っているのですが、その辺についても説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"区でも、それに対応するためにいろいろな保健事業だとか、そういうところの啓発も含めてやっていきたいと思っています。ただ、そういう意味では、区でも定着するために働きがいのある事業だからというところでの充実を十分に進めていきたいと考えています。","id":"exchange-157"},{"speaker":"須貝委員","kind":"質問・要望","question":"介護に関して、これからどんどん増えるわけですが、認知症の方も含めて、健康診断のような仕組みはあるのでしょうか。ただ、そのまま、認知症になりました、介護を受けられましたということなのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"介護予防の関連で、区で実際にやっている事業といたしまして、二次予防事業対象者把握事業というのがあります。自立した生活を営むようにということで、その調査を行って、結果をスクリーニングしていくようなことを始めているところです。","id":"exchange-158"},{"speaker":"須貝委員","kind":"意見","question":"５年前に医者に見てもらった家族の方が、今、引きこもっている方が相当いらっしゃると思うのです。私はやるべきだと思うのですが、その辺についてご見解を説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"近所の方が、講座に参加をするときに声かけするとか、そういう仕組みを考えていったらいいかと思います。いろいろなアイデアを出しながら、検討してまいります。","id":"exchange-159"},{"speaker":"須貝委員","kind":"意見","question":"私、受け身もいいのですが、やはり積極的に、もっと区役所が出ていくべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-160"},{"speaker":"井上委員","kind":"質問","question":"１３７ページの被保護者自立促進事業、１２２ページの福祉団体に対する助成金、１２７ページの日中一時支援事業についてお伺いいたします。高校入学の方と中退の方の数を伺いまして、生保のほうではお伺いをしたのですけれども、中退をされたお子さんたちの把握はされていますか尋ねました。","respondent":"竹田生活福祉課長","answer":"こちらの受験生チャレンジ支援貸付事業は、生活保護受給者ではなく低所得者を対象にした事業ですので、貸付終了後、中退したかどうかということは把握しておりません。","id":"exchange-161"},{"speaker":"井上委員","kind":"質問","question":"こういう形で見られるということで、中退者の方がいて、どのようなフォロー体制をとっていただいているのか説明を求めました。","respondent":"竹田生活福祉課長","answer":"子どもの健全育成支援の観点から、生活保護世帯への養育相談や学習支援などに取り組んでおります。高校進学後の状況の把握や相談、サポートを行って、高校中退の防止をするための支援を行っております。","id":"exchange-162"},{"speaker":"井上委員","kind":"質問・要望","question":"これは要望です。福祉団体についてお伺いしますけれども、障害者の総数と障害者団体と言われる７団体の会員数の総数は、何人ということで把握されているか尋ねました。","respondent":"中山障害者福祉課長","answer":"障害者の人数といたしましては、おおむね身体障害者が８,０００人程度、知的障害者が３,５００人程度だったと思います。それに対しまして、障害者７団体の構成人数ですが、こちらはおおむね７００人程度ということになってあります。","id":"exchange-163"},{"speaker":"井上委員","kind":"質問","question":"実際に今お伺いをしたところによれば、手帳をお持ちになられている方たちの１割にも満たない状況ということなので、いかがか尋ねました。","respondent":"中山障害者福祉課長","answer":"それで、７団体以外の方、多くの障害をお持ちの方をどうやって拾っていくかですが、まずは窓口の相談でも直接的にお話を伺っているところです。今回ヘルプカードの作成を課で進めておりますが、こういった中でも７団体だけではなく、広報等を通じて呼びかけているところです。","id":"exchange-164"},{"speaker":"井上委員","kind":"質問・要望","question":"７団体以外に多くの障害者のグループの方たちがいらっしゃいますから、情報交換をする場を設置してほしいと求めましたが、いかがか尋ねました。","respondent":"中山障害者福祉課長","answer":"個々のご意見を伺うことはできるのですけれども、なかなか団体ではない方、まとまった場での意見ということでは難しいのかとは考えているところです。あるいは、うちの窓口で今後充実していくことは何なのかということを把握しています。","id":"exchange-165"},{"speaker":"井上委員","kind":"質問・要望","question":"続きまして、日中一時支援事業についてお伺いしたいと思います。お伺いしたいのは、タイムケア事業当時の実績と２０１２年度の実績の比較で、事業者への人件費相当の補助費の変化を説明を求めました。","respondent":"中山障害者福祉課長","answer":"最大で８時間以内であれば２,０００円、８時間から１１時間まででも３,０００円ということで、かなり安くなっていると考えているところです。送迎車の経費ですとか、かなりの部分を負担することで、利用者が利用しやすい料金でサービスを提供できる仕組みに変えたところです。","id":"exchange-166"},{"speaker":"井上委員","kind":"質問","question":"決算書で、利用者が今お答えいただいた人数で、結果的に２０１２年度は１.６倍の利用者になっているのですけれども、この事業の指導員の配置基準の考え方は、区はどのようにお考えか尋ねました。","respondent":"中山障害者福祉課長","answer":"職員の配置人数ですが、こちらはどちらも８人から９人の指導員を配置しています。ほかの、例えば通常の法内サービスと比較しても、十分な職員配置がされていると考えているところです。","id":"exchange-167"},{"speaker":"井上委員","kind":"質問","question":"当事者の方たちに伺うと、１対１でないとケアができないという重い方たちもいる中で、どのようにお考えか尋ねました。","respondent":"中山障害者福祉課長","answer":"確かに人数が増えたこと、それから個別的な支援の必要なお子さんが増えているということは事実です。そういった中では、まだ法人で対応できるのかと考えているところです。","id":"exchange-168"},{"speaker":"井上委員","kind":"質問","question":"先ほど人件費だけでお話をしたときに、３人のお子さんを１人で見てできるという金額の中で、単純に言って、相当難しいのではないかと思うのですけれども、そのようには、私の試算というか、計算が間違っているのか、その辺の認識はいかがか尋ねました。","respondent":"中山障害者福祉課長","answer":"人件費としては８９７万６,０００円を想定しておりますが、全体の運営費補助というところでは１,７００万円を超える額を補助しております。そういった全体の枠の中で、ＮＰＯ法人で対応していただいているところだと、私は思っているところです。","id":"exchange-169"},{"speaker":"井上委員","kind":"意見","question":"本当にこれがなくなってしまうと、困ってしまうお子さんたちがたくさんいらっしゃるので、その辺はお願いしたいと思います。今後見直しをされるのか、どのようにお考えなのか、残っている時間でお願いしますとの意見を述べました。","respondent":"永尾高齢者福祉課長","answer":"糖尿病対応だとか、刻みとか。そういうところから見直しをしたいと考えています。","id":"exchange-170"},{"speaker":"たけうち委員","kind":"質問・要望","question":"私は成果報告書から３点伺います。９月１５日くらいの新聞に出ておりましたけれども、そういう動きがあるというふうに伺っていますが、区の考え方を説明を求めました。","respondent":"永尾高齢者福祉課長、竹田生活福祉課長","answer":"品川第二地域センター内と荏原第二地域センター内で実施しているところですけれども、件数もどんどん伸びているところで、好評を得ているところです。もう一つの、東京都の場合… 就労指導する年齢についてのご質問ですが、国の通知によりますと、１５歳から６５歳となっております。ただ、高校に進学された方は高校卒業後ということになると思います。","id":"exchange-171"},{"speaker":"たけうち委員","kind":"質問","question":"どちらかというと各地域でどう進めていくかということのほうが、今、課題になっているということで思っておけばいいでしょうか。就労支援は難しくても、今いろいろな形で区もボランティアが必要になってくる時代の中で、そういうことに仕向けていくというというのか尋ねました。","respondent":"永尾高齢者福祉課長、竹田生活福祉課長","answer":"財源は東京都のシルバー交番設置事業補助金を使っておりまして、現在のやり方にするのか、そういうところも含めて検討していきたいと考えております。それで、もう一つの特養の関係ですけれども、現在… 委員がおっしゃるとおり、受給者の中には、６５歳以上の方でも生きがい、あるいは社会参加のために就労されている方はいらっしゃいます。","id":"exchange-172"},{"speaker":"たけうち委員","kind":"質問・要望","question":"どうしてもやっている地域とやっていない地域で、できれば全区展開をしてもらいたいと思いますので要望します。近いところでという気持ちもありますけれども、違うニーズもあるかもしれませんので、そこは視野を閉ざさずに研究していただきたいと要望します。","respondent":"竹田生活福祉課長","answer":"生活保護受給者の方も、６５歳以上になっても社会参加に非常に生きがいを感じている方もいらっしゃいます。ぜひ、委員ご指摘のとおり、能力を最大限発揮していただいて、実りある人生にしていただきたいと考えております。","id":"exchange-173"},{"speaker":"本多委員","kind":"確認","question":"１２５ページの障害者福祉費について質問しますが、その前に１点だけ確認させてください。その辺の確認だけさせてください。","respondent":"立川保育課長、今井制度改革・待機児童対策担当課長","answer":"幼保一体施設、ぷりすくーる、また保育園、幼稚園におきましても、既存の施設につきましては、そのまま新しい制度に乗るということはできるです。子ども・子育て新制度におきましては、現在の認可を受けている保育園、幼稚園などの事業につきましては、そのまま移行することが可能です。","id":"exchange-174"},{"speaker":"本多委員","kind":"質問","question":"障害者福祉費について伺いますが、先日の開会式で、障害のある方もない方もというフレーズが何回も何十回も出たのです。私、一般的によく健常者も障害者の方もという言葉の使い方があるのですが、その辺の気持ちのところだけお聞かせほしいと求めました。","respondent":"中山障害者福祉課長","answer":"委員ご指摘の健常者、障害者という言い方ではなく、障害のある人もない人もというところは、やはり障害者基本法の基本理念にのっとった、そういうところから来ている表現でないかと思います。","id":"exchange-175"},{"speaker":"本多委員","kind":"質問","question":"さらに、まだまだ障害のある方に対する理解というのを深めてほしいという意見をいただいたのです。全日本ろうあ連盟の創立６０周年記念映画でつくられた「ゆずり葉」、基本に返って、その辺について説明を求めました。","respondent":"中山障害者福祉課長","answer":"ノーマライゼーションの考え方にのっとりまして、人権尊重都市品川宣言もありますし、積極的にやってまいりたいと思います。昨年度から行っております障害者作品展、ああいったものを通じる中で、障害者の方への理解を進めていければというふうに思っているところです。","id":"exchange-176"},{"speaker":"本多委員","kind":"質問・要望","question":"福祉施設や障害者支援施設の充実というのは求めていきますけれども、あれもこれもというふうになってはいけないと思うのです。そういったものの改善をしていくという点についてお聞かせいただきたいのと、現場の声を、改めて吸い上げできているのかという点を説明を求めました。","respondent":"中山障害者福祉課長","answer":"身体障害の方の通所施設であれば、そういった入浴の対応もできるところです。そういったご意見もいただきながら、充実した在宅生活が送れるよう、区としてもサービスの組み立てをしていきたいと考えているところです。","id":"exchange-177"},{"speaker":"本多委員","kind":"質問・要望","question":"先ほども渡部委員から結成強化を求める声があったり、または、高齢者に対する食を通してきずなを深めるという渡辺委員からのお話もありました。前、活動の人のカウントによって算定されていたのが、公平性が課題だというのがあったので、公平性が保たれているかという確認だけお願いします。","respondent":"白鳥高齢者いきがい課長","answer":"やはり会員の人数、それから活動状況によりまして算定するということは、これまでどおりです。公平性を保った、そういう支援ということで行っているところです。","id":"exchange-178"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/571589?Template=document&Id=1376#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":110949,"voices":425}},{"id":"h25-20131007-4","meetingId":"h25-c-settlement","date":"2013年10月7日","dateIso":"2013-10-07","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時１４分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を153件整理しています。","topics":[{"id":"topic-01","title":"◯伊藤委員長 おはようございます。 ただいまより決算特別委員会を開きます。 それでは、平成２４年度品川区一般会計歳入歳出決算","agenda":"◯伊藤委員長 おはようございます。 ただいまより決算特別委員会を開きます。 それでは、平成２４年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"１３８ページの予防接種費についてですけれども、主に子宮頸がんワクチンのことで何点かお伺いさせてほしいと求めました。本年４月以降は国の定期接種になりましたけれども、予防接種を受けた方で副反応が起きた場合、区の補償制度というものを改めて確認させてください。","respondent":"伊津野保健予防課長","answer":"これが普通の任意接種の場合の救済制度であります。おおむね半額程度なので、品川区では自治体総合賠償責任保険に特約をつけまして、定期接種と同等程度の補償になるようにしております。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"いまだに原因がはっきりしないという点で、医師が診断書を書けないという部分もあったりして、大変問題になっています。この事態が発覚したのが５月か６月ごろだったかと思いますが、それから４カ月たった現在の状況についてお伺いします。","respondent":"伊津野保健予防課長","answer":"慢性の痛みが続くということでなかなか診断がつかないということで、治療にも結びつかないというのが一番問題でした。現在では１１の大学病院で痛みについての専門外来というのを設置しまして、そこでの受診を勧めまして、原因を究明するような形になっております。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"もうわかってから４カ月たって、こういった場合の治療費というのは先ほどの補償制度の中から、定期予防接種と同様に出るということでよろしいのか尋ねました。","respondent":"伊津野保健予防課長","answer":"残念ながら現在のところまだ因果関係がはっきりしていませんので、対象になっていないと聞いていますが、今後こういう１１カ所での診断とか原因究明が進んでいけば、補償の対象になる可能性はあると思います。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"４カ月以上経過してもはっきりとしない、杉並区とかではほかの部分で対応していくというところもあると。かなり病院を回られたり、区としても緊急な場合の一時的な補償というのを考えられないかと思いますけれども、そのあたりのお考えはどうか尋ねました。","respondent":"伊津野保健予防課長","answer":"杉並区のほうでも審査会を開いておりますが、なかなかすぐには結論が出ないという、難しい問題だと考えています。区では幸いなことにこういう事例はありませんが、もしあった場合はそういう対応も考えていきたいと考えています。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"次に、不妊治療助成事業についてお伺いします。区のほうの、今後の一般不妊治療に対する対応の考え方を説明を求めました。","respondent":"江部健康課長","answer":"国・都で実施しております特定不妊治療費の助成というものですが、考え方といたしますと。ただ、今の段階で国のこの方針に同調するかということについては、もう少し精査が必要であろうと考えています。","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問","question":"今、品川区では４９件の方が４３歳以上で受けられているということでしたけれども、この中で成功した方というのは大体何組いらしたのでしょうか。以前もお伺いしましたけれども、改めて年齢制限を設けての助成ということは考えられないのか、説明を求めました。","respondent":"江部健康課長","answer":"基礎体温、タイミング療法ですとか薬物療法などをやりまして２年ほどたちますと、人工授精に移るという各段階があります。特定不妊治療については東京都の制度があるということから、今のところはそれぞれの役割分担があるという認識をしております。","id":"exchange-006"},{"speaker":"沢田委員","kind":"質問・要望","question":"次に、資源持ち去り防止対策費についてお伺いします。１,１１７万円余ですけれども、この決算の金額を改めて確認ということで、使われ方を確認させてほしいと求めました。","respondent":"小林品川区清掃事務所長","answer":"これは現在、２名ずつの組で２台配車してパトロールに出ておりますが、これに従事しております職員の非常勤職員としての報酬を計上したものです。","id":"exchange-007"},{"speaker":"沢田委員","kind":"意見","question":"平成２３年度から見て約２,０００万円、大体その資源持ち去りによってどれだけの損害が出ていると予想されておりますか。説明を求めました。","respondent":"小林品川区清掃事務所長","answer":"持ち去りの影響ということですが、大変申しわけないのですけれど、正確にそのうちどの程度が持ち去られているかということは把握できておりません。多くはパトロールの中で原状回復をしておりますが、若干一部がそのまま持ち去られているところは否めない、あるという現状です。","id":"exchange-008"},{"speaker":"沢田委員","kind":"意見","question":"それなりの効果が出て問屋をつかまえたり、持ち去りがそれで減ったという効果が出ていると聞いています。取り締まりをさらに強化していくということも考えられるかと思いますけれども、そういったところのお考えを説明を求めました。","respondent":"小林品川区清掃事務所長","answer":"都下の市ではやっておりますし、区も数区で検討していると言われております。その実効性等、視認した後、どう対応していくかも含めて、今後研究してまいりたいと思います。","id":"exchange-009"},{"speaker":"つる委員","kind":"提案","question":"これを提案しようと本日準備をしていたのですが、健康マイレージ事業も含めて視察に行かれるということで伺っております。長泉町、埼玉県のときがわ町、こうしたところで実施されていると伺っておりますとの意見を述べました。","respondent":"江部健康課長","answer":"地方を中心に今広がっているというお話ですが、実際品川区としてこれについてと言われましても、現段階では意見は今のところ持っておりません。申しわけございません。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問・要望","question":"今後の大きな流れとしても注視すべき施策であると思いますので、厚生委員会の皆様も含めて、ぜひ行政の皆様も積極的な検討をお願いしたいと思います。１４１ページ、保健指導費の中でいろいろとお尋ねしたいと思います。","respondent":"亀井品川保健センター所長、伊崎子育て支援課長","answer":"沐浴実習、いわばイクメンとしてのモチベーションを上げていっていただこうという形で取り組んでいまして、非常に盛況の形でやっております。これからも充実させていきたいと考えています。 イクメンという名前はついていないですけれども、父親の子育て参加促進講座といたしまして、児童センターのほうでも行っております。","id":"exchange-011"},{"speaker":"つる委員","kind":"質問","question":"あれをやって、しかしなかなか出産後というのは、父親と言われる側が出席をする機会というのはなかなかないのかと。１歳６カ月とか３歳児健診があると思うのですが、こうしたものも検討してみてはと思いますけれども、いかがか尋ねました。","respondent":"亀井品川保健センター所長","answer":"例えば乳児健診でも１組、２組、今後の課題かと考えております。","id":"exchange-012"},{"speaker":"つる委員","kind":"提案","question":"次に産後ケアセンター、これについては公明党の会派からも提案しています。産後の家庭への紹介やドゥーラの養成をしているということなのですが、品川ではこのドゥーラについてのご認識はいかがか尋ねました。","respondent":"亀井品川保健センター所長","answer":"申しわけありません。今後、委員ご指摘のように国のほうでもいろいろなモデル事業等考えているようですので、方向性というものを考えていきたいと考えています。","id":"exchange-013"},{"speaker":"つる委員","kind":"提案","question":"初めての提案なので、またいろいろと調査、研究してほしいと求めました。厚生労働省から配布されている、「赤ちゃんが泣きやまない～泣きへの理解と対処のために～」があると思いますが、この活用状況を説明を求めました。","respondent":"亀井品川保健センター所長","answer":"もちろん職員は見ていますけれども、区の保健センターの母子関係の事業の中で、これを見せてということはやっておりません。保健師や助産師がかかわって伝えたり、親御さん同士で話し合っていただくという形の中で、このＤＶＤの趣旨が伝わるような努力はしています。","id":"exchange-014"},{"speaker":"つる委員","kind":"質問・要望","question":"これが出たときに、ぜひそれぞれの自治体で積極的に活用してほしいということで直接訴えられたものですから、品川区の状況はどうなのかと思いまして。世界から悲惨な核をなくすこのシンボル的取り組みとして、この花火大会をぜひ検討してほしいと求めましたが、このあたりいかがか尋ねました。","respondent":"米田商業・観光課長","answer":"いわゆる春の桜とか花と一緒で、花火というのはいわゆる観光振興、集客に一つの大きな役割は果たしていると考えています。今年の経験をまた来年に結びつけていこうということで、観光協会とも連携しながら今後のあり方を探ってまいりたいと思います。","id":"exchange-015"},{"speaker":"木村委員","kind":"質問・要望","question":"１４４ページの環境対策費からの質問をいたします。ＣＯ２削減が目的の一つだと思いますけれども、一応この事業の趣旨を、３・１１の大震災との関係もございましたらお聞かせほしいと求めました。","respondent":"野呂瀬環境課長","answer":"一般家庭または事業所において、太陽光発電システムを設置していただき、その際の費用の一部に充てるというものです。３・１１以降、いわゆる自然エネルギーが脚光を非常に強く浴びてまいりまして、ますます私どもとしても取り組んでいきたいと思っているところです。","id":"exchange-016"},{"speaker":"木村委員","kind":"意見","question":"３・１１以降、節電とかそういうことでいろいろ、省エネ、省エネという形で動いておりますけれども、この事業の終点、終点という言葉も変ですけれども、どこに設定している事業なのか、そして太陽光発電システム等のこの「等」というのは。","respondent":"野呂瀬環境課長","answer":"終了予定ですけれども、先ほど申し上げました趣旨に基づいているということで、具体的な数値というものは設定しておりません。その普及啓発事業の一環として取り組んでおりまして、社会変化等の状況を見極めながら進めていく、このように考えているところです。","id":"exchange-017"},{"speaker":"木村委員","kind":"意見","question":"今年の９月に、スポーツの祭典である２０２０年、２度目となる東京オリンピックの開催が決定されました。まずはここ品川から、大きく変動させるべきと考えますけれども、行政としてのお考えをもう一度説明を求めました。","respondent":"野呂瀬環境課長","answer":"今、オリンピックの話が出ましたけれども、２０２０年というのは環境行政にとっても一つのエポックの年と考えております。３・１１の事故でなかなかその目標がままならないところはありますけれども、環境都市として、一つのチャンスかと考えているところです。","id":"exchange-018"},{"speaker":"木村委員","kind":"質問・要望","question":"平成２３年度と平成２４年度で助成金が大きく金額が変わったということをお聞きしました。３キロワット仕様で大体１５０万円程度するということをお聞きしましたけれども、そこのところを教えてほしいと求めました。","respondent":"野呂瀬環境課長","answer":"これにつきましては当然製造コストが下がったとか、パネルが軽量化して設置工事代金等も以前に比べて安くなったです。このように思っております。","id":"exchange-019"},{"speaker":"木村委員","kind":"質問","question":"行政で使う電気を、区役所の屋上や小中学校の屋上、また区所有の施設等の屋上でソーラーシステムを使った発電のことをお聞きしたことがありました。まずはやはり模範となるべき行政が先頭になって、できる限り節電をするべきと思いますけれども、行政としてのお考えをもう一度説明を求めました。","respondent":"野呂瀬環境課長","answer":"品川区の中では、他の自治体と違ってメガソーラー、大規模な発電システムについてはなかなか難しいということで、お答えさせていただいたと思います。","id":"exchange-020"},{"speaker":"木村委員","kind":"質問・要望","question":"そういうふうに前向きな姿勢でどんどんとやってほしいと求めました。いろいろな事業があると思いますけれども、それも一つとしてお願いしたいと思います。","respondent":"野呂瀬環境課長","answer":"すみません、節電につきましても同じように取り組んでまいります。","id":"exchange-021"},{"speaker":"吉田委員","kind":"質問・要望","question":"１４７ページの雨水利用タンク設置助成事業、同じく１４７ページ、その下の区有施設等雨水利用タンク整備事業についてお伺いいたします。その装着状態をご存じでしたら教えていただきたいのと、マイクロチップの読み取り体制の整備状態も説明を求めました。","respondent":"高山生活衛生課長","answer":"これにつきましては、区としましては推奨する立場で、犬の年間の予防接種などを勧奨する際に、そういったご案内なども付してご案内しています。","id":"exchange-022"},{"speaker":"吉田委員","kind":"質問","question":"ご寄附いただいた個体識別の読み取り機ですが、具体的に保健所のほうですとかに置いていただいて、これから始めていくのでしょうか。その辺のこれから将来に対しての取り組みなどをお願いいたします。","respondent":"高山生活衛生課長","answer":"は区に１台ご寄附いただきましたので、有効に活用するということが一つと、各動物病院におかれましても、通常そういった読み取り装置を備えていただいているというふうに伺っておりますので、災害時も含めて、平時とあわせて活用されるものと考えております。","id":"exchange-023"},{"speaker":"吉田委員","kind":"質問","question":"先ほども申しましたけれど、２７件、１８件と、効果がどのぐらいあるのか、つけた方への聞き取り、またアンケートなどございましたらお聞きしたいのですけれど、お願いします。","respondent":"奥田河川下水道課長","answer":"平成２５年度上半期でも９件ついてございまして、非常に役に立っていて有効的、効果的に使っていると。別のところに２件つけたいという方もたびたびありますので、非常に有効的に活用されているのではないかと考えています。","id":"exchange-024"},{"speaker":"吉田委員","kind":"質問","question":"想定外の雨量とかに対して、浸水被害の軽減とかの効果があるのかお伺いしたいのと、これで一番気になるのはボウフラ対策などもあるのかと思いました。その辺をお願いいたします。","respondent":"奥田河川下水道課長","answer":"個人の方がつけていただくだけでなくて、区のほうでも実は個人の方の設置促進のために中学校ですとか小学校に。ボウフラとかということも、特に発生しているということは聞いてございませんので、特に問題ないと考えています。","id":"exchange-025"},{"speaker":"吉田委員","kind":"質問","question":"やはり件数だけを見てしまうと、魅力がないのかとちょっと考えてしまう部分もあるのですね。災害にもということでしたら、ＰＲに関しての努力などお聞きしたいのですが、お願いします。","respondent":"奥田河川下水道課長","answer":"東京都と連携いたしまして毎年雨期前の６月の浸水対策強化月間、あと庁舎の相談窓口にはチラシなどでもＰＲしてきてあります。今後につきましてもより一層、ＰＲという形で努力していきたいと思いますので、どうぞよろしくお願いいたします。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問・要望","question":"これを伺ったきっかけは「広報に載っていたので、どんなの」と聞いてくださったものですから取り上げさせていただきましたけれど。区有施設の雨水利用タンク整備事業が書いてありますが、平成２３年度は４カ所、平成２４年度は４カ所ということで８カ所に増えているのか尋ねました。","respondent":"奥田河川下水道課長","answer":"これをもっと促進させるということで８カ所ずつつけていく形にしてございまして、平成３０年度までには完了させるような形で考えてあります。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"私からは、成果報告書１５１ページの商店街活性化推進事業にかかわって、商店街の活性化と商店街装飾灯について伺いたいと思います。伺いたいのは、そしてその中で生鮮三品が一つもない、ほとんどない商店街数を伺いたいと思います。","respondent":"米田商業・観光課長","answer":"この間生鮮三品店支援事業を行っている中で、魚屋がどれぐらいあるのだろうということを、そちらが５８の商店街にあるということになっております。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問","question":"住民としてあったらいいなとお年寄りからも子育て世代からもよく伺うのが、ケーキ屋など加工するお店というのでしょうか、これはよく伺います。独立したいと願う方への商店街での新規店舗の開設を応援する仕組みというのも検討されてはいかがかと思いますけれども、いかがか尋ねました。","respondent":"米田商業・観光課長","answer":"今後生鮮三品店以外にどういう形態での支援ができるかということは検討しますが、今既にマイスター店支援事業の中で、夜。こういう事業を今後も区商連とともに進めていきながら、今後も事業に取り組んでまいりたいと考えています。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひそこをつなげる仕組みを考えてほしいと求めましたので、改めて伺いたいと思います。この電気料金値上げ分について、商店街の負担とならないよう助成額を引き上げていくべきだと思いますけれども、あわせて伺いたいと思います。","respondent":"米田商業・観光課長","answer":"商店街連合会とも十分連携をとりまして、親身になってご相談をさせていただいて、今後も取り組んでまいりたいと考えています。平成２１年度からそちらのほうの対策を打ってありますが、こちらについてはこの実績も踏まえて今後考えてまいりたいと考えています。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、今頑張っているお店、これから新規にオープンするお店、その個店への支援を進めていただきたいと思うのと、原発事故に伴う電力料金の値上げ分を商店街が負担することのないよう、区の助成額を引き上げていただきますよう強く要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"渡部委員","kind":"質問・要望","question":"１４０ページ、女性の健康診査のことについてお伺いしたいと思います。１６歳以上、平成２４年ですから４０歳未満の女性の区民の方で、括弧書きで勤務先等で受診機会のない方が対象者になっています。","respondent":"江部健康課長","answer":"もうどんどん、企業での労働安全衛生法での健診を受ける方が、数字的にちょっとつかんでおりませんが相当数いるだろうと思います。ということで、現実的には受診率はかなり低い、このような数字になっているものと思われます。","id":"exchange-032"},{"speaker":"渡部委員","kind":"質問・要望","question":"ということは、次にお伺いしたかったのが、この健康診査についてどういう周知をされていますか。そういう女性の方々に対してどういうふうに、こういう仕組みがありますよというのをお伝えになっているか、説明を求めました。","respondent":"江部健康課長","answer":"２００数カ所ありますけれども、知人が行くであろうということで、まずやっているのが一つです。それから、行かない方についてはというと、やはり一般的な広報しながわとホームページによる広報でやっているところです。","id":"exchange-033"},{"speaker":"渡部委員","kind":"質問","question":"子宮頸がんの検診でしょうか、２０歳以上の女性の方には通知が行きますよね、こういう診査がありますよと。もし入っていれば、それで周知としてはその世帯には行くのだろうけれど、入っていなければ、入れたらいかがですかということですが。","respondent":"江部健康課長","answer":"例えば３５歳からの健診をやるときなどもやりましたが、若者の料理教室などもそこで見たという方が数人いらっしゃったりします。委員ご指摘の件は検討します。","id":"exchange-034"},{"speaker":"渡部委員","kind":"質問","question":"今は３４歳まで受けられると、２３歳だから、わからないケースというのはあるのではないですか。そういう場合のやりとり等はどのようになっているのか尋ねました。","respondent":"江部健康課長","answer":"社会保険に入っているからこの健診を受けられないということではなくて、自己申告でやっております。各医療機関でそのような対応、では健診しましょうということで、つないでいただいていると認識しております。","id":"exchange-035"},{"speaker":"渡部委員","kind":"意見","question":"すみません、意地悪な聞き方を一つしますけれど、そうしたら会社で受けていてもこの健診は、要するにその人のモラルですけれど、受けさせてくださいと言ったら受けられてしまう仕組みということですねとの意見を述べました。","respondent":"江部健康課長","answer":"検査項目はかなり限定的でございまして、女性の健康診断は、血液検査と問診等に限ります。目とかさまざまありますが、かなり限定的なので、そういうこととは差別化されているというふうに認識しております。","id":"exchange-036"},{"speaker":"渡部委員","kind":"質問","question":"これはページ数といいますか、商業・観光の全般のことでお伺いしたいと思います。競馬場といわゆる品川区の関係、商業・観光の面でのことでお伺いしたいと思います。","respondent":"米田商業・観光課長","answer":"現在行っている取り組みといたしましては、あるいは商店街との連携も含めまして、８月にも取り組んでおります。地元の商店街等とも連携し、いわゆる品川を広く知っていただくというための、観光面からの推進も行っていくような形で考えてあります。","id":"exchange-037"},{"speaker":"渡部委員","kind":"質問・要望","question":"それも８月にというのもお伺いしたんですけれど、プロパティサービスも当然民間ですから、品川区の中でご商売なさっているグループであります。おもしろいな、何かいいことできないかなと思ったんですが、いかがか尋ねました。","respondent":"米田商業・観光課長","answer":"ほかに常設の店舗等があって、いわゆるそこに出ていっての経済的な効果ということについては、いろいろ検討の余地があるだろうと思います。今ご提案の趣旨は十分検討いたしますが、その辺も含めましていろいろ検討してまいりたいと。","id":"exchange-038"},{"speaker":"渡部委員","kind":"質問・要望","question":"そのような状況でありますので、ぜひ商業・観光課長、頑張って何か進めていただきたい。もう一言。","respondent":"米田商業・観光課長","answer":"８月に出店したときの経験を踏まえて、１１月はこう変えていこうというようなことでの出店も考えておられるようです。委員ご提案の趣旨も今後検討の材料に含めさせていただきながら、区商連とも相談いたしまして、取り入れてまいりたいと考えているところです。","id":"exchange-039"},{"speaker":"塚本委員","kind":"質問","question":"それから１４９ページの観光アクションプラン推進事業をお伺いしていきたいと思います。犬の登録・予防注射ということで年１回予防注射のために、どのような対策等、現状なされているものがあるのかお伺いしたいと思います。","respondent":"高山生活衛生課長","answer":"区道などの道路、公共の空間におけるふん害ということで、保健所にも多数の苦情などが寄せられているところです。区といたしましてはまず現地に看板類の設置、お困りの方にも寄り添うような形で対応させていただいているところです。","id":"exchange-040"},{"speaker":"塚本委員","kind":"質問","question":"なぜかというと、どうせ回収してくれるんだから放置しておいてもいいんだということで、非常に難しいと頭を悩ませていたそうです。非常に参考になるし、有効なのではないかと私も認識を改めたところなんですけれども、区としてどのようにお考えなのかお伺いしたいと思います。","respondent":"高山生活衛生課長","answer":"既に区において類似の取り組みもしているところですので、そういったものをご活用いただくのはひとつ、委員ご案内のとおり有効かと考えております。そういった飼い主に対します犬の生理、習性を踏まえた飼い方、散歩の仕方なども今後普及してまいりたいと考えております。","id":"exchange-041"},{"speaker":"塚本委員","kind":"質問・要望","question":"続きまして１４９ページの観光アクションプラン推進事業につきまして、先ほどつる委員からも、ボイジャー・オブ・ザ・シーズの話がちょっと出ました。いつごろできるのかとか、こういった情報はどの程度つかんでいらっしゃるか、わかる範囲で教えてほしいと求めました。","respondent":"米田商業・観光課長","answer":"レインボーブリッジがくぐれないために従来の客船ターミナルに着けないということで、暫定的に大井埠頭を使っているということは事実のようです。","id":"exchange-042"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういった品川区の将来にぜひ花を添えるという意味で、花火大会の開催というのを私からもぜひ要望したいと考えています。こういったことを研究、調査していただいていいのではないかと思いますけれども、ご答弁を。","respondent":"米田商業・観光課長","answer":"そういうものは、ぜひ品川にもつなげていけるような取り組みを、今後も続けてまいりたいと考えています。今現在ああいう形でやっていて、昨日も会話をして別れておりますので、今後もそのような形で十分検討してまいりたいと思ってあります。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"それに対しまして、区としての対応をどう考えられているかということもお聞きします。女性起業家支援は今どうなっていますかということ、これらの過去２回において成果があったのか、まずお聞きいたします。","respondent":"伊津野保健予防課長、米田商業・観光課長、山崎ものづくり・経営支援課長","answer":"中学１年生から高校２年生までの５,３３０名、２０歳から２２歳の３,７７５名、計９,１０５名が総対象という形になります。その中で副反応につきまして… 商店街の支援の基本的な考え方ですけれども、それからさらなる発展をということで、そちらを目的に商店街の支援を行っているものです。起業家の支援につきましては、それぞれビジネスモデルを考えておりまして、専門家の目線を入れて助力するということでやっております。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"ですからその評価についても、しっかりと提示していくべき時期に来ているのではないか。それから、女性起業家、これは実際に商売が成り立っているところはあるんか尋ねました。","respondent":"伊津野保健予防課長、米田商業・観光課長、山崎ものづくり・経営支援課長","answer":"あるいはメーカーからの報告で把握しておりますが、現在のところ重篤な副反応は、当区では発生しておりません。もし発生していれば… 地域の一員であるということの位置づけを持って、こういうものは、地元の商店街等でも行っていただいているものと考えています。… 武蔵小山創業支援センターを出まして、近隣でいわゆるフェーシャルマッサージ等を開業している方がいらっしゃいます。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問・要望","question":"それから子宮頸がんワクチンはきちっと対応できるようにしてほしいと求めました。商店街については、いろいろな助成金のやり方をやはり再考していただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"鈴木（博）委員","kind":"意見","question":"本日は成果報告書の１３９ページの定期予防接種、同じく感染症予防費のうちで感染症対策費、１４０ページの肝炎ウイルス検診に関連してお尋ねします。任意予防接種と健康診査の肝炎ウイルス検診から、Ｂ型肝炎についてお尋ねいたしますとの意見を述べました。","respondent":"伊津野保健予防課長","answer":"Ｂ型肝炎は、患者の血液や体液によりましてＢ型肝炎ウイルスを感染しまして、症状としましては倦怠感、黄疸、腹痛などの症状を起こします肝臓の病気であります。","id":"exchange-047"},{"speaker":"鈴木（博）委員","kind":"意見","question":"３億５,０００万人の持続感染者、キャリアとなっていて、年間世界中で５０万から７０万人が死亡していると推定されております。品川区の肝炎ウイルス検診の受診者数、およびその中でＢ型肝炎ウイルスの陽性者数と、陽性率についてお尋ねしますとの意見を述べました。","respondent":"江部健康課長","answer":"肝炎ウイルス検診実績は４,１７２件でございまして、陽性者は１６人、０.４％です。","id":"exchange-048"},{"speaker":"鈴木（博）委員","kind":"質問","question":"Ｂ型肝炎ウイルスの感染者は約１％と推定されており、肝臓がんに進行して、死亡しております。Ｂ型肝炎ワクチンは現在任意接種に位置づけられておりますが、我が国では現在どのような方が、Ｂ型肝炎ワクチンを主に接種しているのか質問します。","respondent":"伊津野保健予防課長","answer":"我が国におきましては、妊娠中にＢ型肝炎ウイルスの抗体をはかりまして、感染しているかどうかを検査します。妊婦が感染していた場合、生まれてくる赤ちゃんに対してリスクが大きいということでワクチンを、健康保険の適用で接種しております。","id":"exchange-049"},{"speaker":"鈴木（博）委員","kind":"質問","question":"世界保健機関、ＷＨＯはＢ型肝炎ワクチンについて、今どのような方針を推奨しているのでしょうか。我が国で現在、Ｂ型肝炎の患者は、どのような年齢層に多く見られるのか尋ねました。","respondent":"伊津野保健予防課長","answer":"ＷＨＯでは、そういうことに限定することなく、全ての赤ちゃんにＢ型肝炎ワクチンの接種を勧奨しております。Ｂ型肝炎ですが、我が国でも２０代から３０代の男女ともに、その年代に多い感染を示しております。","id":"exchange-050"},{"speaker":"鈴木（博）委員","kind":"質問","question":"持続感染を起こし、一生苦しむことがないように、定期接種化されるより以前に接種費用の助成を始めてほしいと考えております。区のご見解はいかがか尋ねました。","respondent":"伊津野保健予防課長","answer":"昨年５月の国の検討会におきましても、第２次提言としましてＢ型肝炎ワクチンを含みます７つのワクチンが、定期接種化について提言されております。残りの４つのワクチンにつきましても、国の動向を見据えながら検討していきたいと考えております。","id":"exchange-051"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"Ｂ型肝炎に感染した方の大体１０％は慢性肝炎に移行していくという、非常に憂慮すべき状態になっています。それと任意接種でありますがワクチンの積極的な接種の勧奨を行っていただきたいと考えますが、区のご見解はいかがか尋ねました。","respondent":"伊津野保健予防課長","answer":"Ｂ型肝炎は、先ほど申しましたように２０代、３０代に感染のピークがありますし、多くは性交渉によって感染するということですので、エイズ予防啓発の中で、予防あるいはワクチンの接種を考えていきたいと考えております。","id":"exchange-052"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"ぜひＢ型肝炎に対する理解と積極的な取り組みを区に強く要望いたしまして、次の質問に移りたいと思います。日本全国、東京都、品川区のこの夏以降の風疹の流行状況は、現在いかがか尋ねました。","respondent":"伊津野保健予防課長","answer":"品川区におきましては、東京都と同じような推移を示しましたが、なかなかゼロにならず、１名あるいは２名の発生が続いておりました。先週やっとゼロとなっております。","id":"exchange-053"},{"speaker":"鈴木（博）委員","kind":"質問","question":"それともまだまだ十分な警戒が必要と考えるべきなのでしょうか。ご見解を伺います。","respondent":"伊津野保健予防課長","answer":"今回の風疹の流行によりまして、風疹の抗体を持っていない方が全て抗体を持ったかというと、そこまでは言えないと思いますので、まだまだ今後の流行には注意を払う必要があると考えております。","id":"exchange-054"},{"speaker":"鈴木（博）委員","kind":"意見","question":"そもそも風疹とはどういう病気なのか、あわせて今回の流行も終息に向かっておりますので、今回の風疹の流行について簡単なまとめをお願いしますとの意見を述べました。","respondent":"伊津野保健予防課長","answer":"特に妊娠初期に感染しますと、胎児に大きな重い障害を起こす可能性が高い病気であります。制度的に風疹ワクチンを接種する機会がなかった、あるいはあっても接種率が低かった２０代から４０代の男性を中心とした流行でありました。","id":"exchange-055"},{"speaker":"鈴木（博）委員","kind":"質問","question":"２０１３年１０月現在、今回の流行で何名の先天性風疹症候群の赤ちゃんが生まれているのでしょうか。あわせてお尋ねします。","respondent":"伊津野保健予防課長","answer":"この赤ちゃんにつきましては、今後重い障害を持って生活されることを余儀なくされるものと考えております。一旦おさまったというふうに考えられますが、妊娠中の障害ですので、これからこのような先天性風疹症候群の患者さんが増えることは予想されます。","id":"exchange-056"},{"speaker":"鈴木（博）委員","kind":"意見","question":"このまま２０１３年、再々度の流行が再び勃発するのか、現在見通しを立てることは極めて困難だと思われます。品川区の現在の風疹流行対策をお尋ねしますとの意見を述べました。","respondent":"伊津野保健予防課長","answer":"同時に妊婦の夫につきまして、９月３０日まで全額助成をしておりました。妊婦の夫につきましても急遽女性と同じく、来年３月末まで助成を延長するように決定いたしたところであります。","id":"exchange-057"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"今なお一度も風疹、さらに１回しかＭＲワクチンを受けたことがなく、積極的にＭＲワクチンの接種を呼びかける必要があるのではないでしょうか。最も感染源となっている、風疹抗体をあまり持っていない２０代から４０代の成年男子に対する対策の強化を強く要望しまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"向委員","kind":"質問","question":"それから１４１ページ母子健康診査費、それから１４２ページの健やか親子学習、マタニティクラスなどに関してまずお伺いします。このあたり曜日に違いがある理由を説明を求めました。","respondent":"伊津野保健予防課長、江部健康課長、亀井品川保健センター所長","answer":"ですから、妊娠中の母親にはワクチンを接種することができないので、仕方なく妊娠されている夫にワクチンを接種するということです。… 平成２４年度妊娠届出数は４,１１５件です。それから出生届につきましては、我々としては４カ月健診の数字で押さえてありますが、対象者は３,３４６名で… 私からは健やか親子学習のマタニティクラス、母親学級と二人で子育てについてご説明申し上げます。","id":"exchange-059"},{"speaker":"向委員","kind":"質問・要望","question":"２３区内でも４カ月健診ですか、品川区ではどういう対策を、もしされているものがあれば教えてください。今後の対策はぜひとも検討していただきたいんですが、そのあたりのお考えをもう一度説明を求めました。","respondent":"伊津野保健予防課長、江部健康課長、亀井品川保健センター所長","answer":"ＣＲＳの今後の発生につきましては、先ほども申し上げましたように予断を許さないと考えています。軽い難聴とかは… 妊娠届出と実際に生まれるお子さんの差、７６９名ですが、これは率にしますと１８.７％あります。国のほうの統計でいいますと、十五… 確かに委員おっしゃることも十分一理あると、働いているお母さんたちが増えているということもあると思います。","id":"exchange-060"},{"speaker":"向委員","kind":"質問","question":"７６９人の赤ちゃんが、でも生まれてこなかったその７６９人のお母さんは、妊娠していない状態に戻る。改めて質問しますが、そのあたりのあいているところなどもフォローできるようなことを、検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"こんの委員","kind":"質問","question":"私からは、１３８ページの予防接種費、そして時間があれば１４６ページのみどりの保全事業をお聞きしたいと思います。他の自治体の予診票を使用して接種した場合、費用はどうなるのか、あるいはその予診票の扱い方はどうなっているのか説明を求めました。","respondent":"伊津野保健予防課長","answer":"特別区、２３区の中では相互乗り入れという形で行っておりますので、そのまま費用負担なしで受けることが可能であります。それ以外の自治体におきましては、一度お金を払っていただきまして、償還払いという形で行っております。","id":"exchange-062"},{"speaker":"こんの委員","kind":"質問","question":"２３区はそうではないということなんですが、この自己負担なく、定期接種ですからだれでも公平に受けられる体制というのが必要だろうと思うんです。品川区では、２３区は大丈夫だということですが、こういった予診票を統一するということを関係機関に働きかけていただくことは可能か尋ねました。","respondent":"伊津野保健予防課長","answer":"先ほどおっしゃいました３ワクチンが増えましたのでかなり混乱して、とりあえず２３区の中で何とか統一できないかという形の検討は始まっております。なかなか統一するのは難しい部分もありますが、まずは色を統一するとか、そういうところから始めていきたいと考えております。","id":"exchange-063"},{"speaker":"こんの委員","kind":"質問・要望","question":"５年を経過した人ですよ、２年後、どうかそういったお知らせも含めてご検討を進めてほしいと求めました。高齢者の方は掃くのに大変、保存樹の所有者の方は管理がなかなか難しいという、区はどのようにこの保存樹の管理を捉えていらっしゃいますか尋ねました。","respondent":"多並公園課長","answer":"それを３年に一度行ってあります。この剪定につきましては所有者の皆様にご負担いただいてしていただく、そのようなことでバックアップしています。","id":"exchange-064"},{"speaker":"こんの委員","kind":"質問","question":"事業の内容はそうなんですが、いわゆる管理する所有者の方、ご高齢の方がお持ちの木の管理は、３年に一度の中で、ご自分で１年目、２年目をするのが大変厳しくなっている状況もあるということは、どのように捉えていらっしゃいますか尋ねました。","respondent":"多並公園課長","answer":"ほかの近隣区の状況を見ますと、一律１本幾らという助成金で行っている区もあります。維持管理する場合にも、所有者の方とお話をしながら、どのような形で管理していくかというのもアドバイスしながら進めているものです。","id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問","question":"１４１ページの公衆便所費、１４３ページの帰宅困難者用物資備蓄倉庫設置工事の件についてお伺いをいたします。３７カ所の維持管理３,４２０万４,２７１円、もう一点疑問があるんですが、この衛生費のほうと土木費のほうにもあるのか尋ねました。","respondent":"多並公園課長","answer":"平成２４年度の決算の中で、公衆便所維持管理の一番大きなウエートを占めますのが、清掃委託が一番大きなところです。公園の中にあるものというのは、公園の利用者のためのトイレということで、公園管理費、いわゆる土木費の中で維持管理を行っているものです。","id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問・要望","question":"洋式トイレの設置状況、私は改善を進めてほしいという立場での質問なんですが、設置状況と今後についての考えをお聞かせいただきたいのが一点です。これはどのようなトイレなのか、非常時というのがどういう状況なのか説明を求めました。","respondent":"多並公園課長","answer":"もう一つの非常時対応型のものですが、これはトイレの下に、ピットと申しまして大きな便槽があります。非常時にはその中に汚物をため込んで使えるというものが、非常時対応型のトイレです。","id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問・要望","question":"３・１１以来トイレの重要性が、被災者の皆さんにとっても健康問題、衛生の問題で根本にかかわる問題だと思っています。災害時に使えるようにしていただきたい、災害時の大きな備えになると思うので、その点いかがか尋ねました。","respondent":"多並公園課長","answer":"文庫の森でもそのような形で整備させていただき、防災上の重要な公園を整備する際には、このような形も今後進めていきたいと考えています。もう一つは利用者の方から、そのようなところも総合的に考えまして、和式ということで公衆便所につきましては考えているところです。","id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問・要望","question":"トイレで困るのは目に見えていることで、我慢をすると健康に大きな被害を与えるということでは、ぜひ十分検討をしてほしいと求めました。健康センターにこの倉庫を備えるということがどういうことになるのか、そこの位置づけと、備蓄内容を説明を求めました。","respondent":"亀井品川保健センター所長","answer":"２階部分のレントゲン室をなくしましたので、実際にはペットボトルの水とか毛布とか、乾パンを備蓄していると。実際に３・１１のときも、かなりの方があそこで滞留されましたので、そういう方々に提供できるものをそこで用意しようという形で準備したものです。","id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ということは、いっとき滞在できるという理解でよろしいんでしょうか。ぜひ災害対応用のトイレにしていただきたいのと、情報の伝達のところで災害用の固定電話をぜひぜひ設置していただきたいんですが、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"通常のデジタル移動通信ですね、無線機を配備して、緊急時の対応ができるように準備をしています。","id":"exchange-070"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これは決算書上で立入調査件数が３２件と出ているんですが、品川区が今まで立ち入りをしてやっていたということでしょうか。こういう回収容器の設置ということについて、品川区としてどう考えているか、その３点を説明を求めました。","respondent":"野呂瀬環境課長、小林品川区清掃事務所長、江部健康課長","answer":"この間区といたしましてもエコドライブ講習会とか、また車のマフラーに取りつけるんですけれど、粒子状物質減少装置の助成とかも行ってまいりました。… お尋ねのありました区の方針ですけれども、品川区におきましては従前の体制を維持して、協議会と一緒に立入調査に入っているのが現状です。… 各種助成金の薬剤師会９０万円という中の一部になりますけれども、荏原の両薬剤師会に団体助成ということで４５万円ずつ助成金をお出ししています。","id":"exchange-071"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"エコカーにつきましては、まだまだ意識を持っていただく中で、いいほうに検討していっていただきたいということで、それは要望します。荏原と品川で４５万円ずつになるんでしょうけれど、その辺さらにご検討ほしいと求めました。","respondent":"野呂瀬環境課長、小林品川区清掃事務所長、江部健康課長","answer":"運輸部門におけるＣＯ２の削減効果もあるということですので、委員のご意見も含め、今後検討してまいりたいと思います。 許可業者が２３区の多くの区にまたがってやっている等の実態も加味して、共同処理の形にしましたが、その状況は各区同じであろうと思います。… 両薬剤師会のほうから実際にかかっている経費についてお示しいただいておりますので、それと助成金とのバランスを見ながら調整していきたいと思います。","id":"exchange-072"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それと当時に品川でスタートした中で、２年とか１年の契約ですから、相当の入れ替えもあったと思うんです。あそこに前、燃料のスタンドがあって、今もあるんでしょうけれど、そこが使われていないという話を伺っているんですが、現在の状況を説明を求めました。","respondent":"山崎ものづくり・経営支援課長、小林品川区清掃事務所長","answer":"転出された企業が３４企業ございまして、現在も事業を継続されている企業については２０社です。２人で延べ４０人ほどだったんですが、それが現在では４００人ということで、一定の評価に値する数字を出しているというような状況です。大崎清掃事務所内に従前たしか２０キロリットルの軽油の給油装置、いわゆるガソリンスタンドのようなものがございました。","id":"exchange-073"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"うまくいっている中で今後も各事業所との関連、そして品川の中にうまく生かしていただきたいということをお願いします。ちょっと大きさを聞いて、今後の検討をまた、いろいろ全体で考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"高橋委員","kind":"質問","question":"前年度との比較という観点で、どのような成果があり、どのような評価をされているのでしょうか。基本的なことなのですがお伺いいたします。","respondent":"山崎ものづくり・経営支援課長","answer":"こちらは２３区の中でも、対前年度増になりましたのは６区でございまして、減っていくトレンドです。ただ区としましては、増の３０億円というのは２３区の中で断トツ１位ということで、ニーズに応えてきたものというふうに評価しているものです。","id":"exchange-075"},{"speaker":"高橋委員","kind":"質問","question":"ニーズに応えた結果、２３区で３０億円増というのは断トツだというお話があったんですが、その突出した実績ですけれども、他の区に比べて非常に多かった要因というのはどのようなところにあるんか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"１３ページのほうに資金実績の一覧がございまして、こちらも先ほどと繰り返しになりますが、合計の欄の１つ上に経営安定化資金（緊急経済対策）です。","id":"exchange-076"},{"speaker":"高橋委員","kind":"質問","question":"４００件ぐらいですから１件当たり１,５００万円、そうするとこの１,５００万円の中で、区の助成の部分というのはどれぐらいになるのでしょうか。それが利用される方の動機にもなると思いますので。","respondent":"山崎ものづくり・経営支援課長","answer":"モデルケースで少しわかりやすくご説明しますと、限度額を３,０００万円にしたことと、返済期間を１０年という長期にしました。トータルで６５万円ほどになるということで、両方足しまして９５万円というものが、１,５００万円の融資に対しての補助額ということになります。","id":"exchange-077"},{"speaker":"高橋委員","kind":"質問","question":"１４３ページの保健所等管理運営費ですが、職員給与費１２３人という人数なんですが、保健予防課の職員の方が含まれているのでしょうか。そうすると１３８ページのほうの職員給与費１９人という保健衛生総務費のほうは、どちらの職員のことになるんか尋ねました。","respondent":"高山生活衛生課長","answer":"委員お尋ねの成果報告書１４３ページの１２３人の職員給与費ですが、保健予防課のほか、３センターの職員の給与費の数字を計上したものです。一方で１３８ページの１９名につきましては、健康課の職員の給与費を計上しているものです。","id":"exchange-078"},{"speaker":"高橋委員","kind":"質問","question":"そして税金のこともちょっとお尋ねしたかったので、税務課のほうに回していただいた。庁内では保健所のみ、それについての合理的といいますか、その理由はどのようなことになっているんか尋ねました。","respondent":"高山生活衛生課長","answer":"経緯としましては保健所が庁外にあった時代から時間外の対応ということで、こういったテープによるご案内をさしあげているところです。その効果としましては、時間外においても食中毒の発生などの際には即時に対応させていただいているところです。","id":"exchange-079"},{"speaker":"高橋委員","kind":"質問・要望","question":"食中毒でなくて、飲食店の方がお尋ねしたときにつながらないということですので、機械的に変わってしまうことと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"山元委員","kind":"質問・要望","question":"そして時間があればその前になりますけれども１３８ページの公衆浴場についてお伺いしたいと思います。その対象が子宮頸がんに関しては２０歳、乳がんは４０歳のみ限定と伺いましたけれども、その状況を教えてほしいと求めました。","respondent":"江部健康課長","answer":"これについては２３区保健衛生課長会でもちょっと議論になっております。現在のところはまだ未確定ですので、予算要求上は前年並みにしているところでございまして、今後の検討にさせていただきたいと思います。","id":"exchange-081"},{"speaker":"山元委員","kind":"質問・要望","question":"先ほど聞くのを忘れてしまったんですけれども、２００９年前といいますか、この無料クーポン券がスタートする前と、昨年度でもいいんですけれども受診率といいますか、使用前、使用後ではないんですけれども、その率がわかれば教えてほしいと求めましたが、いかがか尋ねました。","respondent":"江部健康課長","answer":"５年に１回のクーポンということで、ほかの方よりも１６％ぐらい高くなるという試算はしておりますので、クーポン事業の効果はあるというふうに認識しております。","id":"exchange-082"},{"speaker":"山元委員","kind":"意見","question":"４５歳から４９歳までに至っては、５割近くまで上昇したと聞いています。５０％を目指して品川区もいろいろと努力していらっしゃると思いますが、これを受けて品川区としてはどのような感想をお持ちでいらっしゃいますかとの意見を述べました。","respondent":"江部健康課長","answer":"私どもといたしましては、まず国の方針が出たときにちょっと驚きました。冷静に考えてみて、即答はできませんけれども何らかの対応を、ちょっとまだお時間をいただきたいと考えています。","id":"exchange-083"},{"speaker":"山元委員","kind":"質問・要望","question":"今度は２０歳だけ、４０歳だけとなると、もう一度ご答弁ほしいと求めました。","respondent":"江部健康課長","answer":"それ以外でも品川区では乳がん検診の実施機関について平成２３年度に倍増させて、受診者の受け入れを図ってきた経緯もあります。死亡率が下がりつつあるという中にいるという認識をしておりますので、今回の国の判断については慎重に対応していきたいと考えています。","id":"exchange-084"},{"speaker":"山元委員","kind":"質問・要望","question":"いずれにしましても健康課長の一言、一言の中には、品川区独自でも継続していこうと思っていらっしゃるように受け取りました。ぜひ継続を考えてほしいと求めましたが、その辺はいかがか尋ねました。","respondent":"江部健康課長","answer":"これから予算の編成ということですので、財源を確保できたらという条件でもって、考えします。","id":"exchange-085"},{"speaker":"山元委員","kind":"質問・要望","question":"受診率アップにつながることについて、もう一つ確認させてほしいと求めました。私は受診率アップのために個別に電話連絡等したらいかがですかというお話をさせていただきましたが、その辺確認をさせてほしいと求めました。","respondent":"江部健康課長","answer":"区が保険者という立場で被保険者に対応するという立場ですが、私ども健康課が行いますがん検診につきましては、区民全てです。実施できるか、実施に向けてといいますか、これはちょっと研究させていただきたいと思います。","id":"exchange-086"},{"speaker":"山元委員","kind":"質問・要望","question":"次に、ちょっと時間がありますので１３８ページの公衆浴場についてお伺いしたいと思います。一番聞きたいことは、この差がどういうことだったのか、その辺をちょっと教えてほしいと求めました。","respondent":"江部健康課長","answer":"建替工事をした場合の１,０００万円という補助金がありますが、ここ１０年建替えをされる浴場がないため残るものであり、部分的な改修をするものがほとんどです。","id":"exchange-087"},{"speaker":"山元委員","kind":"質問・要望","question":"東品川地域では１軒も銭湯がないということで、それに対して区としてどんな対応を考えていらっしゃるのか、一言教えてほしいと求めました。〔時間切れにより答弁なし〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"藤原委員","kind":"質問","question":"それと１５１ページの武蔵小山創業支援センターのところで、改めて聞きますが、しているんでしょうか。説明を求めました。","respondent":"高山生活衛生課長、亀井品川保健センター所長、山崎ものづくり・経営支援課長","answer":"私からは２１世紀成年者縦断調査についてのお尋ねにお答えいたします。調査開始年度であります平成１４年度に、２０歳から３４歳だった男女を対象としまし… ６カ月、９カ月の健康診査は医療機関委託でやっているんですけれども、６カ月児が８５.３％、９カ月児が８２.８％。… 改めまして、２０１２年度のグランプリでファイナリストの方々です。","id":"exchange-089"},{"speaker":"藤原委員","kind":"質問","question":"さっきの質問でその調査結果を品川区でどう生かしていくんですかと伺っているんですが、その答弁がなかったのでお願いします。乳児健診ですけれども、もちろん１００％に近いほうがいいんですけれども、この受診をしなかった人のフォローはどういうふうにするんか尋ねました。","respondent":"高山生活衛生課長、亀井品川保健センター所長、伊崎子育て支援課長、山崎ものづくり・経営支援課長","answer":"２１世紀成年者縦断調査についてのお尋ねです。実施等のために役立てるための基礎資料として活用されるものですので… 例えば４カ月健診が一番最初の健診ですけれども、電話がつながらなければお手紙を出したり、さらには訪問もします。… ３回ほど伺ってそれでもお会いできなかった方について、お会いできた方の状況も含めて保健センターのほうに状況報告をしております。","id":"exchange-090"},{"speaker":"藤原委員","kind":"質問・要望","question":"１５２ページのプレミアム付商品券なんですけれども、商業・観光課長の答弁は大体わかっているんですけれど、どうしても伺いたいのであれします。この金額を上げていただきたいという要望で、改めて質問しますが、いかがか尋ねました。","respondent":"米田商業・観光課長","answer":"これは当初から２回継続して組んだり、あるいは補正で追加計上したりというようなことは経済状況を勘案しながら決めているものです。来年の４月には大きな商業環境の変化もありますので、こうした部分も含めてまた検討してまいりたいと考えています。","id":"exchange-091"},{"speaker":"あべ委員","kind":"質問・要望","question":"ある程度はカウンセリングなどがあるのかどうか、それとも請求に応じてお金を出すだけなのかということをお伺いしたいと考えています。地域にとってもマイナスなことだと思いますので、品川区としては今後どのようにお考えか、伺いたいと思います。","respondent":"江部健康課長、柏原行財政改革担当課長","answer":"ベースとしてはそれほどのことは認識しておりませんので、個別のプラス何日という形での対応を今、考えているところです。国のほうで検討会が行われまして、一定の整理をされたところですので… ２０年という制約がございまして、今までも東京都、それから例えば２３区の関係部長会であるとか、いろいろなところで申し出等々やってきてあります。","id":"exchange-092"},{"speaker":"あべ委員","kind":"質問・要望","question":"ＡＥＤとあわせてというより、広く区民に広めてほしいと求めましたが、区の見解をお伺いしたいと思います。それぞれいかがか尋ねました。","respondent":"江部健康課長、米田商業・観光課長、柏原行財政改革担当課長","answer":"ＡＥＤ絡みで子どもの心肺蘇生の件と、不妊治療をされている方への対応という２点についてお答えいたします。生育歴等々… やはりどうしても必要だと思いますので、そういったものを十分醸成していくことが何よりも肝心だろうと思います。関係部署と連携をとりながら… 今、商業・観光課長からの答弁もございましたけれども、東京都に対して粘り強く交渉していきたいと思ってあります。","id":"exchange-093"},{"speaker":"あべ委員","kind":"意見","question":"特に不妊治療のクリニックに行くというのは、とてもリラックスした時間ではないと。どういう心持ちを持っていけばいいのか、どういう体づくりをしていけばいいのかというような、今後考えてほしいと求めました。","respondent":"江部健康課長","answer":"研究します。","id":"exchange-094"},{"speaker":"石田（ち）委員","kind":"質問","question":"私は成果報告書の１４０ページ、成人歯科健診について伺いたいと思います。今回この成果報告書では、２,５２０人ということでしたけれども、この対象人数と受診率、この受診率の達成目標というんでしょうか、それがあれば。","respondent":"江部健康課長","answer":"４０代、５０代半ばぐらいまでで徹底して、歯を失うという方は減ってきております。７０代半ばぐらいから上の方については歯磨き習慣がなかったということがやはり、認識しております。","id":"exchange-095"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この受診率に目標があればということを伺ったんですが、あればお答えいただきたいのと、あと６.９９％、徐々に上がっていると言っていますけれども、少ないなと本当に感じるんですが、そこへの課題があれば説明を求めました。","respondent":"江部健康課長","answer":"かかっている方は結構いらっしゃるだろう、それから不都合を感じていない方もいるだろうという推測をしております。２０％とか３０％を目標にしておりませんで、前年の実績を踏まえてプラスに、少し加算するというような形で毎年予算要求をしてきているところです。","id":"exchange-096"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"では特に課題と感じていることがあれば、教えていただきたいです。介護予防にもつながるということをお伝えしてきたんですけれども、区も、歯の健康は全身の健康に大事だという認識はお持ちなんか尋ねました。","respondent":"江部健康課長","answer":"もちろん歯で食べて、人間は生きるものですので、歯周疾患から糖尿病につながるとか、そういう報告もなされておりますので、そこは認識しております。","id":"exchange-097"},{"speaker":"石田（ち）委員","kind":"質問","question":"私は２定の一般質問でも、健診の対象年齢を拡大してほしいということで、歯周病は。ですので、４０歳からでは遅いとずっと言ってきているんですけれども、この予防という観点からの年齢拡大の考えはあるか尋ねました。","respondent":"江部健康課長","answer":"３０代から歯の健康状態が極端によくないというような情報を得ておりませんので、今、その年齢を下げるという考えは持っておりません。あくまでも３０代、４０代の方、自分の体ですから自分でやるというのを基本にやっていただきたいと思います。","id":"exchange-098"},{"speaker":"石田（ち）委員","kind":"質問","question":"歯科口腔保健の推進に関する法律が、２０１１年からつくられていまして２年たっているわけですけれども、これがどういう目的でつくられて、内容はどういうものなのか、説明を求めました。","respondent":"江部健康課長","answer":"平成２３年８月１０日施行されたということでございまして、充実を図る責任があるということで、規定されております。それにのっとりまして私どもは事業を展開しております。","id":"exchange-099"},{"speaker":"石田（ち）委員","kind":"質問","question":"ここに地方自治体が国民への認識を広げていくということがうたわれているんですね。そしてまた１５歳から健診を広げていこうという、自分もやるんだなということがわかるわけですから、なぜ品川区ではやらないのか説明を求めました。","respondent":"江部健康課長","answer":"それを受けてそれぞれが大人になりまして、自分の健康を自分で守っていくということが正常な考え方であろうと思うわけです。ただ、生活習慣が乱れて、その方については啓発事業の中で意識づけを図る方策を検討していくべきではないかと考えております。","id":"exchange-100"},{"speaker":"石田（ち）委員","kind":"質問","question":"これを縮小していこうというのを掲げているんです。口腔崩壊している実態も、この間の一般質問で出しましたけれども、こういった口腔の健康格差を、区はどうお考えか尋ねました。","respondent":"江部健康課長","answer":"先ほどの繰り返しになりますけれども、各種統計調査から健康格差が明らかであるということは、報告されておりません。","id":"exchange-101"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"厚生労働省からこういった特別区の各衛生主管部、部局長宛てに歯科口腔保健のさらなる推進を図るため、本資料もご活用いただきたいというふうに来ていると思うんですが、この検討はしっかり区としてやられているんか尋ねました。","respondent":"江部健康課長","answer":"それにつきましては、検討した上、歯科医師会とも相談しながらやっております。","id":"exchange-102"},{"speaker":"石田（ち）委員","kind":"質問","question":"この厚生労働省の法律には、方針をつくり、計画を立て、啓発をしていくということがうたわれているんですけれども、それが検討されているということでいいんか尋ねました。","respondent":"江部健康課長","answer":"歯の健康に関することにつきましては、現行の長期基本計画、総合実施計画の中でもうたわれ、健康づくりプランの中でも事業として展開しています。そこのところは、今回のその法律の趣旨を踏まえて、今後事業を充実させるという意味での検討はしていきたいと思います。","id":"exchange-103"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"方針を立て、目標を立てるということをやっていただきたい、そして健診も年齢拡大をしてほしいと求めました。いかがか尋ねました。","respondent":"江部健康課長","answer":"委員のおっしゃる健康格差という点、若者が極端に歯の健康状態がよくないということにつきましては、繰り返しになりますけれども統計として上がっておりませんので、我々としては今拡大を考えるという動きではありません。","id":"exchange-104"},{"speaker":"若林委員","kind":"質問・要望","question":"２つ目に、１４６ページの拠点回収について伺いたいと思います。融資を受けられなかった企業のフォローというんですか、支援の継続につながっているのか、ここらへんのご様子をお聞きしておきたいと思います。","respondent":"江部健康課長、小林品川区清掃事務所長、山崎ものづくり・経営支援課長","answer":"それから８０２０運動、４つでもって計画をいただいて、それに対して助成をしているものです。区といたしましては… その処理はアゴラ造園株式会社への委託でやっております。その所要の経費ですが、キロ当たり５５円ですので… 率にしますと７７.３％です。一番多く対応していますのが、起業して間もない部分について、いろいろ専門家の指導をさせていただいているというよう… ただ、びちゃびちゃに濡れていますと、搬送、その後の処理に支障がありますので、乾かしたものでというふうになっております。","id":"exchange-105"},{"speaker":"若林委員","kind":"質問・要望","question":"これは要望します。それだけ確認させてください。","respondent":"江部健康課長","answer":"それから件数が増えているのにということですけれども、ちょっとアップダウンがあります。平成２４年度は下がっておりますので、一概に多くなっているという認識は持っておりませんので、会との話し合いはしていきます。","id":"exchange-106"},{"speaker":"若林委員","kind":"質問・要望","question":"区の事業の目的は、全ての私立、公立の保育園、幼稚園の皆さんに適切な指導を受けさせたいという委託事業ですので、それに沿った適正な委託金をという要望をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"松澤委員","kind":"質問","question":"これは使用制限みたいなものがあるんだと思うんですけれど、この内容についてお聞きしたいと思います。実際にこの花火は港区で打ち上げられたようですけれども、品川区はどんなかかわり方をしていたかについてお伺いしたいと思います。","respondent":"小林品川区清掃事務所長、米田商業・観光課長","answer":"その後平成２１年４月から、粗大ごみの積み替え作業所として使用を開始しておりまして、現在もその機能を継承しております。なお移管当時に負担付譲渡ということで、原則２０年は清掃作業の用途として使用することが指定されているため… その中で屋形船を使った花火大会を実施したいということでの観光協会からの意向もありまして、それに必要な調整をさせていただいたものです。","id":"exchange-108"},{"speaker":"松澤委員","kind":"質問・要望","question":"船舶中継所跡地ですけれども、平成１２年ですから平成３２年まで、あと７年は清掃事業だけということですよね。その件について、しっかりと答弁をほしいと求めました。","respondent":"柏原行財政改革担当課長","answer":"２０年間は清掃業務という強い縛りがございまして、清掃業務以外では買い取りをしてほしいであるとか、いろいろな話が出てあります。オリンピックということもあります、なるべく早く品川区が自由に使えるように、今後とも粘り強く交渉していきたいと思ってあります。","id":"exchange-109"},{"speaker":"松澤委員","kind":"質問","question":"まさにオリンピックがその年に開かれるわけですから、やはり１年でも２年でも前倒しということが必要だと思いますので、さらに努力をお願いします。当然、産業振興のことに使うんだろうと思いますけれども、ちょっとご意見を伺いたいと思います。","respondent":"米田商業・観光課長","answer":"中小企業センターの４階ですけれども、商店街連合会、各工場協会連合会ということでご入居いただいてあります。まだ中小企業センターのほうに、そこの部屋を閉めて明け渡すというようなことについては、今現在聞いているものではございません。","id":"exchange-110"},{"speaker":"松澤委員","kind":"質問","question":"４階に観光協会がありましたよね、あれがあきました。そういうものに使われているかというと、商業・観光課で使っているように聞いているんですが、ちょっとその辺をお聞きしたいと思います。","respondent":"米田商業・観光課長","answer":"４階の観光協会のあいたところは、就業支援センターの方の一部詰め所であったり、そういった相談業務に転用しているものです。その他４階には、各団体が話し合いを行ったりする会議室等設けてあります。","id":"exchange-111"},{"speaker":"松澤委員","kind":"質問・要望","question":"もともと中小企業センターですから、今度ももしあくとしたらしっかりと後を考えていただきたいと、注文しておきたいと思います。改めてその考えを聞きたいと思います。","respondent":"米田商業・観光課長","answer":"中小企業センターのある種業務量が増えているということでは、それなりに部屋のほうの確保も必要にはなってありますが、委員ご指摘の趣旨も踏まえまして、工場協会のほうから特に何もお申し出いただいていませんが、その折にはまた考えてまいりたいと考えています。","id":"exchange-112"},{"speaker":"松澤委員","kind":"質問","question":"同じく成果報告書の１５０ページ、平成２３年度から始まった事業で３,０６５件だったのが、平成２４年度は５,４３２件と大きくふくれ上がりました。東北地方、それぞれ指定されていたと思うんですが、この関東と東北の内訳をお聞きしたいと思います。","respondent":"米田商業・観光課長","answer":"こちらの事業ですけれども、平成２３年７月から開始していますので、初年度は約９カ月間の事業でございました。平成２５年度からは、対象地域を東北地方に限定した実施を行っているものです。","id":"exchange-113"},{"speaker":"松澤委員","kind":"質問","question":"今現在、いろいろ話を聞きますと、被災地も震災前より観光客が来るようになったというようなお話を聞いています。いいことですから続けようという思いはあると思うんですけれど、やはり事業ですからどこかで仕切り直しというんですか、お聞きしたいと思います。","respondent":"米田商業・観光課長","answer":"風評被害等により観光客が減少している被災地の支援の一環と、お帰りになった後、区内の産業振興と両面からということでやっているものです。この辺につきましては、こちらの支援策が有効に働きますよう、また来年度に向けては検討を進めてまいりたいと考えています。","id":"exchange-114"},{"speaker":"原委員","kind":"質問","question":"ですから連携ですとかそういったことも踏まえて、ご意見があれば頂戴したいということ。ですから具体的に言ってしまうと運転資金、中小企業の経営者というのは、その辺のところについてもう少しお話をほしいと求めました。","respondent":"大石荏原保健センター所長、山崎ものづくり・経営支援課長","answer":"そういった側面もあるのかと思いますが、ただいろいろな手法に関しては、最新の手法なども取り入れながらやっていきたいと考えております。平成２３年には健康大学で立正大学の先生をお呼びして… 相談も充実させるとともに、現在区のほうでは融資の実施件数が延べ９,０００件あります。運営の関係なのか、そういうところを踏まえてしっかりと基本的な融資事業について、適正に運営してまいりたいと考えています。","id":"exchange-115"},{"speaker":"井上委員","kind":"質問","question":"私からは、１４７ページの清掃費全般からお伺いしたいと思います。２００９年から始まっていますけれども登録人数の推移と、実際に異変に気づかれたケースなどあったら、その推移を説明を求めました。","respondent":"小林品川区清掃事務所長","answer":"ふれあい清掃事業は、日常ごみ出しができない高齢者等を対象に実施しております。傾向といたしまして、やはり高齢者の方で足元等が不案内という形でお求めいただく例が増えているといった状況です。","id":"exchange-116"},{"speaker":"井上委員","kind":"質問","question":"２００９年には何らかのそういったものがあった場合には、質問させていただいたんですが、その件についてはいかがか尋ねました。","respondent":"小林品川区清掃事務所長","answer":"ごみが所定の場所に出ていないとき等は声がけをして、それで安否確認も含めて行っております。手元の平成２４年度、平成２５年度の数字では、あらかじめお申し出いただいた連絡先に通報したという実績はございません。","id":"exchange-117"},{"speaker":"井上委員","kind":"質問","question":"そういったホームページへの掲載とか、障害者福祉課とか高齢者福祉課の窓口での情報提供というのは、お考えいただけないか尋ねました。","respondent":"小林品川区清掃事務所長","answer":"この事業がより身近なものとしてその効果が図れますように、今、お寄せいただきましたご意見も含めて、高齢者福祉課あるいは障害者福祉課といった関係各課と連携を深めて、ＰＲに努め、対応してまいりたいと思います。","id":"exchange-118"},{"speaker":"井上委員","kind":"質問","question":"区の全体的な見守りネットワークというところでも活用をほしいと求めました。サーマルリサイクルの分別が２００８年から始まりまして、清掃工場がストップした事故があったのか、品川区の分担金への影響はあったのか尋ねました。","respondent":"小林品川区清掃事務所長","answer":"２１施設を含めて一体的に清掃一部事務組合は対応しておりますが、その施設の修繕対応の費用は、品川区も負担していると推定されます。ただその金額については、詳細は把握しておりません。","id":"exchange-119"},{"speaker":"井上委員","kind":"質問","question":"２３区全体で経費を示すとか、区民に公表すべきだというふうにその体制を整えるべきだと思いますけれども、いかがか尋ねました。","respondent":"小林品川区清掃事務所長","answer":"その清掃、整備等の費用も、こういった事故が起きたから特別分担金が増えているという意味ではございません。したがいまして日常の契約、費用負担の詳細まで全て報告させて周知するということは、技術的に困難な点が多かろうと思っています。","id":"exchange-120"},{"speaker":"井上委員","kind":"意見","question":"幾らぐらいかかりますよという大体の目安が報告されているという状況で、全体でどのぐらい増えているかを区民が知らないというのはやはり間違いだと思いますので、その仕組みをつくってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-121"},{"speaker":"浅野委員","kind":"質問","question":"１４９ページ、観光アクションプラン推進事業、時間があれば１４０ページの各種がん検診の中から胃がんリスク検診について質問します。品川区のこの２０１０年度の二酸化炭素の排出量の目標と、そして結果について、こちらの数値を教えてほしいと求めました。","respondent":"野呂瀬環境課長","answer":"でも３・１１がありまして、その後いろいろ状況が変わってまいりまして、２０１０年の第１回目の数字が出たところです。ですからマイナス２５％に向かっていくんだけれども、初年度がプラス８％になった、こういう結果です。","id":"exchange-122"},{"speaker":"浅野委員","kind":"質問","question":"日本におきましては、こちらの数値も決定して、これも結果的には品川区の地域推進計画に影響を与えていくのではないかと思うわけであります。こちらの推進計画も１１年間の計画という、それが今後出てくる国の数値とか、この件についてはどう考えていますか尋ねました。","respondent":"野呂瀬環境課長","answer":"この中間見直しが５年後ですので２０１７年に予定しております。いわゆる品川区全体の温室効果ガスの削減計画ですけれども、これについては見直しを図っていきたいと、このように考えているところです。","id":"exchange-123"},{"speaker":"浅野委員","kind":"質問","question":"私どももしっかりと、このような質問をしながら進めていきたいと、そのように思うところであります。これは本当にいい機会になるのかなと思いますが、この効果というものをどのように考えておられるのか説明を求めました。","respondent":"米田商業・観光課長","answer":"ホームページ等に活かしていこうということで、いい作品については観光協会内にも飾って、取り組んでいこうというものです。それを区民の方のみならず、広く区への誘導に、あるいは区に愛着を持っていただくための施策につながればという形で考えてあります。","id":"exchange-124"},{"speaker":"浅野委員","kind":"提案","question":"至るところでこちらについてはさまざまな提案をしていますけれども、以前、こういうような取り組みというのは間違いなく必要になってくると思います。悪いところも含めて検討して、さらに発展をさせていくという考え方もあるかと思いますが、いかがか尋ねました。","respondent":"米田商業・観光課長","answer":"外国の方のみならず、広域的な連携で無線事業者とやっているようですので、その辺のあたりもう一度研究してまいりたいと思ってあります。","id":"exchange-125"},{"speaker":"須藤委員","kind":"質問","question":"１４５ページの土壌汚染相談について、１,３４５件という数字がありますけれども、簡単にどんな相談があるのか説明を求めました。","respondent":"野呂瀬環境課長","answer":"いわゆるディベロッパーとか不動産関係の方が窓口に来て、過去にそういう土壌汚染があったかどうかというのをお尋ねになる、この相談です。","id":"exchange-126"},{"speaker":"須藤委員","kind":"質問","question":"例えば５メートル以上ということになってくると、かなり近隣の方々に、その掘削自体でいろいろな影響が出てくるだろうと。近隣に周知するとか、説明するとかという形をつくったらどうかと思うんですが、いかがか尋ねました。","respondent":"野呂瀬環境課長","answer":"たとえ不動産が来ても、いわゆる近隣の説明会等で例えば家屋を壊すときには届けを出さなければいけないとか、そういう届出はあります。今現在、それ以外のことで近隣に説明しなければならないとか、そういう形で条例に載っているわけではございません。","id":"exchange-127"},{"speaker":"須藤委員","kind":"質問・要望","question":"ですからそういったことをきちんと、現状ではこういう土壌汚染でどの程度深くまで、何が入っているとかということは必要ないかもしれない。そろそろそういうことを、やはり研究していただきたいと思うんですか、いかがか尋ねました。","respondent":"野呂瀬環境課長","answer":"いろいろ昭和に建てたものが建替えという時期を迎えて、今、委員がおっしゃられたような問題がこれから出てくると思います。区としましては住民のいわゆる福祉向上、これが第一の目標ですので、委員のご意見を踏まえた上で、今後検討してまいりたいと考えています。","id":"exchange-128"},{"speaker":"須藤委員","kind":"質問・要望","question":"そういうものを解体することに対してやはりある程度指示するような仕組み、届出をするような仕組みというのをつくっていったらどうかと。これも既につくっている区もあるわけですけれども、そのあたりも研究してみていただきたいと思うんですが、いかがか尋ねました。","respondent":"野呂瀬環境課長","answer":"１９７５年に全面禁止になったわけですけれども、そこから４０年たっているということで、これに対してはまず第一義的にやっていかなければいけない。前向きに、いろいろな形、いろいろな情報を収集しながらやってまいりたいと考えているところです。","id":"exchange-129"},{"speaker":"須藤委員","kind":"質問・要望","question":"いや、責任はどっちなんだということがあってはいけないので、まちの人たちがきちんと安心して住める状況をつくってほしいと求めました。１５２ページの品川技術ブランドＰＲ事業、短い時間で申しわけないですが、説明を求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"昨年度から開始しまして、昨年度につきましては、４つの製品について指定をさせていただいています。今回の震災でも使われたと、自衛隊のほうでも購入されている株式会社ライフセンサーのレスキューレーダーというものが指定されているものです。","id":"exchange-130"},{"speaker":"南委員","kind":"質問・要望","question":"私はこの会議に向けて、地域の隅々から２０２０年の目標を２５％に戻すよう国に求めていく、一つ質問したいと思います。したがって品川区はこの間、公共施設に太陽光パネルの設備を取りつけているんですけれども、そこの認識についても伺います。","respondent":"野呂瀬環境課長","answer":"この認識ですけれども、日々２５％に向かってやっていく、これは同様です。ですから今後もその考えは継続して、できるだけ可能な限り、設置できるところを見つけて、太陽光発電システムは設置していくという考えです。","id":"exchange-131"},{"speaker":"南委員","kind":"質問・要望","question":"それだけでなくて日本にはかつてから高い濃度でＰＭ２.５が発生していて、それが健康被害、改めて確認しなければいけないと思います。品川区内でも４カ所ですか、東京都の平均値から見て、品川区のこの４カ所の状況はどうかということをまず教えてほしいと求めました。","respondent":"野呂瀬環境課長","answer":"それに基づいてしっかりと守っていくように取り組んでいきたいと考えています。区民の皆さんに春先のほうに、もうご心配ありませんみたいなＰＲも含めてやっていきたいと考えているところです。","id":"exchange-132"},{"speaker":"南委員","kind":"質問・要望","question":"健康を守るという点で本当に必要なわけですから、そして東京都に、あるいは国に要望していただきたいということについての認識を伺います。したがって品川区は早急にまた、大気中の汚染状況がどうなっているかの調査を開始するべきだと思っていますので、その点についての見解を伺います。","respondent":"野呂瀬環境課長","answer":"継続的に高目になったときには、このような対策は２年前からずっと継続してやっておりますので、その姿勢は今後も同じです。ちょっとこれは意味合いが違ってまいりまして、今までどおりこの姿勢のまま継続して、行ってまいりたいと考えているところです。","id":"exchange-133"},{"speaker":"南委員","kind":"質問・要望","question":"私が測定のことを伺ったのは、東京都の大気汚染のＰＭ２.５です。したがって〔時間切れにより答弁なし〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-134"},{"speaker":"須貝委員","kind":"質問","question":"私は１４９ページ、産業経済費の全般についてお聞きしたいと思います。説明を求めました。","respondent":"米田商業・観光課長、山崎ものづくり・経営支援課長","answer":"なかなかそういう効果が、いわゆる個人の商店までには及ばないということでは、それぞれあるんだろうと思います。そういったものもまたお声を吸い上げながら、区内の商業の状況について把握してまいりたい、このように考えてあります。延べ９,０００件をさせていただいているもので、計算では３社に１社という割合で、融資を活用していただいています。","id":"exchange-135"},{"speaker":"須貝委員","kind":"質問","question":"でも、実際どうですか。実際に予算の７５％しか執行できていないということは、私は問題があると思うんですが、その辺についてどのようにお考えか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"区のほうでは、平成２１年度以来リーマン・ショックに対応して、いち早く経済対策を実施してまいりました。６区の中でも一、二億円増になったというのが精いっぱいだったんですけれども、これは先ほど申し上げた品川区の融資の成果かなと考えています。","id":"exchange-136"},{"speaker":"須貝委員","kind":"質問","question":"こういうのはきちんと把握しているんですか。先ほど経済がよくなっているという話も、景気がよくなっている話も今、出ましたけれど、その辺はどうなんか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"それからさまざまなアンケート調査、これは民間の機関も含めまして、そうした把握には努めております。こういった対応をさせていただいています。","id":"exchange-137"},{"speaker":"須貝委員","kind":"意見","question":"そういうご答弁だったんですが、やはりまちを歩けばわかりますよね。店に入って、そういう資料をきちんとそろえて、やはりその実態を見て政策というのは考えるべきではないかというふうに申し上げておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-138"},{"speaker":"いながわ委員","kind":"質問","question":"品川区の浴場組合のホームページで数を勘定しますと３２軒になっているんですが、品川の分布といいますか、軒数がわかれば地域別に教えてください。お願いします。","respondent":"江部健康課長","answer":"全体で３１浴場です。地域別というのは数えないとちょっと。","id":"exchange-139"},{"speaker":"いながわ委員","kind":"質問・要望","question":"３１軒以上まだドットが落とされているという現状もあるので、なかなか本当の数というのは、申請件数になると思うんですが。品川区がこの設備に助成する意義を改めてお聞かせいただきたいということと、今後の公衆浴場について、健康課長はどうお考えか、説明を求めました。","respondent":"江部健康課長","answer":"第一義的には入浴という行為が自宅でできない方の衛生面の確保、それからもう一方では浴場組合の経営の部分的な支援という２面があると思います。おそらく支援をしてもしても、どのように考えるかということだと思うんですけれども、どんどんどんどん減っているわけですね。","id":"exchange-140"},{"speaker":"いながわ委員","kind":"質問","question":"ここでグッとかじを切って、観光の視点で今度公衆浴場を考えたとき、それについてちょっとお伺いしていきたいんですが。テレビなど見ても、この外国人が日本の銭湯というんですか、公衆浴場に行くというのが、非常に今ブームだということも、報道されております。","respondent":"米田商業・観光課長","answer":"外国人向けの品川区の情報誌の中には、１つの銭湯にご協力いただきまして、銭湯の紹介をさせていただきました。銭湯スタンプラリーというような事業も平成２３年度には実施しておりますし、そういうことも可能性として十分あるのではないかと考えています。","id":"exchange-141"},{"speaker":"いながわ委員","kind":"質問・要望","question":"１４６ページの資源持ち去り防止対策費について、端的にお伺いしますが、今回予算ベースにおいては１件５万円の過料が予算の中に入っていました。それをまず説明を求めました。","respondent":"小林品川区清掃事務所長","answer":"規則に基づいて原状回復命令を行い、それに従わない者に対してあらかじめ弁明書をもって告知した後に、最終的に科していくという手続行為があります。全ての例が、基本的には原状回復の求めに従っているので、過料を科すに至っていないです。","id":"exchange-142"},{"speaker":"いながわ委員","kind":"質問","question":"軽自動車が２台回っているという、町会の新聞を自分の軽に載せていってしまっているんですけれど、それはどこへいってしまっているか教えてください。資源がキロ６円、町会に入るんですが。","respondent":"小林品川区清掃事務所長","answer":"これを行っておりますのは集団回収のものではありませんで、一部事情によってはそれをそのまま戻さずに回収してしまうということです。日にちも変えて出してくださいということを基本的にはお願いしておりますので、そういう間違いは多分そうはないというふうには思っております。","id":"exchange-143"},{"speaker":"いながわ委員","kind":"質問・要望","question":"次に１４９ページです、観光全般でお伺いします。２年後ぐらいから第１回目をスタートしていくこともいいのではないかと考えていますので、その辺改めて、強い意思のご答弁をほしいと求めました。","respondent":"米田商業・観光課長","answer":"それと同じように私どもも、地域の中でもやはりいろいろお考えがおありだろうと。進めるところは進め、観光協会とは連携しつつ、歩を進めてまいりたいと考えています。","id":"exchange-144"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ちょっと角度を変えて質問させていただきたいんですが、大井水産物埠頭に４月に着岸しました。それに対して品川区として７年間の限定された期間でありますが、どういったお考えで外国人をこの品川区に呼び寄せるか、説明を求めました。","respondent":"米田商業・観光課長","answer":"そのままバスに乗ってというような流れで、なかなかその場でお降りになってというようなことは、交通の便からも難しいということは思っております。まだまだこれから十分勉強しなければならないと考えていますので、その辺また考えさせていただければと考えています。","id":"exchange-145"},{"speaker":"いながわ委員","kind":"提案","question":"ぜひ前向きにしっかりとやっていただいて、あと一点提案なんですが、青海埠頭に接岸されてしまいます。おもてなしの観点でとの意見を述べました。","respondent":"米田商業・観光課長","answer":"いろいろ勉強させていただければと思います。","id":"exchange-146"},{"speaker":"たけうち委員","kind":"質問・要望","question":"私は成果報告書の１４０ページの環境衛生費の中の、狂犬病予防および動物の愛護について伺いたいと思います。それから毎年９月２０日から２６日が動物愛護週間というふうになっておりますが、また実施したことがあるかどうか説明を求めました。","respondent":"高山生活衛生課長","answer":"こちらは平成１７年に動物愛護管理法が一部改正されまして、その後５年を経たことから、さまざまな法施行上の状況等を踏まえて改正されたものです。しつけ教室でありますとか、そういった時期にとらわれず通年で、こういった動物愛護に関する行事を行っているところです。","id":"exchange-147"},{"speaker":"たけうち委員","kind":"質問・要望","question":"猫が１,９８７匹、ウサギ等で６頭、合計２,１９０の動物が殺処分されているという状況があります。周知、啓発していっていただきたいと思うんですけれど、考え方を説明を求めました。","respondent":"高山生活衛生課長","answer":"それ以外にも今回、平成２５年度におきましては、不妊・去勢手術の頭数の増でありますとか、そういったことを取り組んできているところです。","id":"exchange-148"},{"speaker":"たけうち委員","kind":"質問・要望","question":"全文を読ませていただいて、インターネットで『７８円の命』と打ちますと全部出てきますので、ぜひ読んでほしいと求めました。品川区としてこれをどう啓発していくかということを、しっかりやっていただきたいと思うんですけれど、その辺の思いを教えてほしいと求めました。","respondent":"高山生活衛生課長","answer":"例えば一例を申しますと、午前中の質疑にもございました犬、猫等へのマイクロチップ装着の義務づけなども検討されているところです。区といたしましてもホームページでの発信も含めまして、一層の啓発、充実に努めてまいりたいと考えております。","id":"exchange-149"},{"speaker":"本多委員","kind":"質問","question":"１５０万円ということで、ふれあい講座等でもう２０年以上も定着されてきておりますけれども、やり方はこのままでいいのでしょうかという点。それと平成２４年度の新製品について、内容をお知らせください。","respondent":"米田商業・観光課長","answer":"「伝統の技と味しながわ展」ですが、毎年１月の最終土曜・日曜で、きゅりあんイベントホールで開催しています。平成２４年度につきましてはハンカチをとめるブローチ、伝統工芸の技と味しながわ展等でも販売して、購入も一定あるということで聞いてあります。","id":"exchange-150"},{"speaker":"本多委員","kind":"質問・要望","question":"それで新商品のかき入れ時というんでしょうか、そういったものを聞きたいなと思いました。この伝統的産業に対する新商品開発への助成と、何か両方頑張っていただきたいと思うんですけれど、その辺いかがか尋ねました。","respondent":"米田商業・観光課長、山崎ものづくり・経営支援課長","answer":"それこそ今ご指摘があったように、それが相乗的にすごいものができるんですけれども、値段もそれなりにすごくなるというような問題もあります。比較的手軽に手にとれるような商品の開発と、こういうものをこれからの課題として… 市場も非常に狭いニッチな市場もあります。そういう市場の中で、トップをとっていくということを目指して、区のほうも支援し、販路拡大等につなげていくということでやっております。","id":"exchange-151"},{"speaker":"本多委員","kind":"質問","question":"伝統のほうも、ものづくりと同じように後押しをお願いしますという意味で、ちょっとお聞かせいただきました。外国人への日本でのお土産とか、現状と今後の発展性について、働きかけについてはいかがか尋ねました。","respondent":"米田商業・観光課長","answer":"本業もやられている中で、そういう日程の調整が難しかったり、また見学するに当たっては場所がなかったりというような課題もあります。そういう部分も含めて、さらなる伝統工芸の発展につながるような形での振興策を、また考えてまいりたいと考えています。","id":"exchange-152"},{"speaker":"本多委員","kind":"質問・要望","question":"メードイン品川ですとか、それぞれの分野で勝ち組になっていただきたい、そんな思いで我が会派から取り上げさせていただきました。国が２１５ぐらい、例えば神奈川県の箱根ですと寄せ木細工ということで昭和５９年に国指定を受けておりますけれども、その辺いかがか尋ねました。","respondent":"米田商業・観光課長","answer":"専門の事業者が当たっておりますけれども、なかなかやはり職人の方お一人お一人では、そういう取り組みが非常に難しゅうあります。伝統的工芸品の普及、発展にもつながるところもありますので、こちらについては十分研究してまいりたいと考えています。","id":"exchange-153"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/571589?Template=document&Id=1378#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":109246,"voices":371}},{"id":"h25-20131008-4","meetingId":"h25-c-settlement","date":"2013年10月8日","dateIso":"2013-10-08","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時１１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を145件整理しています。","topics":[{"id":"topic-01","title":"◯伊藤委員長 ただいまから決算特別委員会を開会いたします。 それでは、平成２４年度品川区一般会計歳入歳出決算","agenda":"◯伊藤委員長 ただいまから決算特別委員会を開会いたします。 それでは、平成２４年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"１６０ページの特定整備路線の計画推進費でお伺いします。自転車の交通安全のことでお伺いしたいんですけれども、そして人と自転車の事故の件数の推移、大体どういう状況なのか説明を求めました。","respondent":"谷口交通安全担当課長","answer":"全体的に割合でいいますと３５.６％が自転車の事故になります。いずれにしましても、事故全体、自転車の事故も前年より減少しているです。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問・要望","question":"それと、ああいった規格というか、ああいう状況の違いというのはどういう意味があるのかということをお伺いさせてほしいと求めました。そういったところのことというのは考えられるのか、そのあたりのことをそれぞれちょっとどうお考えなのか、説明を求めました。","respondent":"稲田道路課長","answer":"平成２４年度には都市計画道路の整備、２０５号線と合わせまして、２０５号線の一部カラー化を実施しております。最低でも一方通行で６メートル、相互通行だと９メートル以上の車道が欲しいところなんですが、なかなか難しいという状況です。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"まあ、やっぱり自転車と自動車ということで分けて通れるんじゃないかなと思うので、そのお伺いをさせていただきました。特にそういう道路はたくさんあると思うので、そういったことについてお伺いさせていただきたいと思っています。","respondent":"稲田道路課長","answer":"そこは今後、警視庁とどのような形で表示というのができるのかどうかというのは検討課題ですが、現在のところは警視庁の見解はそのような見解です。今後は、自転車走行レーン、自転車の誘導等、積極的にやっていきたいなと考えております。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"ちょっと時間があれなので、次、公園整備事業費についてお伺いさせてほしいと求めました。公園や児童遊園にある健康遊具についてお伺いさせていただきたいんですけれども、現在品川区の、そういうのというのは統計というのはあるか尋ねました。","respondent":"多並公園課長","answer":"公園利用者の比率ですが、そのような統計は現在ございません。大きな公園については分かれながら、その中でご利用いただいている、そんな状況です。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"それと、どこら辺にあるのかということをお聞かせください。新設というか、改良された、改修された公園で整備されたりとかということがあるのかということをお聞かせほしいと求めました。","respondent":"多並公園課長","answer":"健康遊具の区内の設置ですが、区内全体的に２１公園の中に８３基現在あります。近年の設置の状況ですが、ハード整備として区のほうが行い、そのような形の運動教室を行うということで行っているものもあります。","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問","question":"どうしても品川区の場合は、どこの公園に行って、また地域的にバランス的にどうなのかなというところもあります。これからさらに増設を進められていくとは思うんですけれども、こういった健康遊具の今後のあり方について、また広報体制について説明を求めました。","respondent":"多並公園課長","answer":"健康遊具につきましては、今後施設の改修時期に合わせまして、地域の皆様のご意見をお聞きしながら、設置してまいりたいと思います。広報につきましても、ホームページ等、わかりやすい広報ということで、今後改善してまいりたいと考えています。","id":"exchange-006"},{"speaker":"つる委員","kind":"質問","question":"１６１ページ、１５４ページ、駅周辺等放置自転車対策事業についてお伺いしたいと思います。事前に公園課の皆様に教えていただきまして、いわゆる桜の木が一番多いというふうに伺っておりますが、種類ですね。","respondent":"多並公園課長","answer":"いわゆる桜につきましては、公園の中以外でいいますと、例えばかむろ坂ですとか、街路樹として植えられているものが多くあります。","id":"exchange-007"},{"speaker":"つる委員","kind":"質問","question":"改めて自分で調べたいと思います。かむろ坂、品川区の桜の名所の一覧ということで出ているんですが、品川区内にある桜地図みたいなものというのは作成したことってありますか尋ねました。","respondent":"多並公園課長","answer":"桜の地図というものは実はございません。桜の時期になりますと、ホームページの中でお知らせさせていただいたり、そのようなところで区民の方には知っていただくような形をとってあります。","id":"exchange-008"},{"speaker":"つる委員","kind":"質問","question":"１０周年のときには、植樹祭的なことをされたというふうに、いろいろ過去伺っております。そういう思いからのお尋ねなんですけれども、駅周辺に桜の木を植えていったらどうかなと、その辺のご見解を説明を求めました。","respondent":"藤田都市計画課長","answer":"そういうものをやはり大切にしながら、樹木を、緑を増やしていこうというようなことで進めてあります。その中で、桜についても、駅前のことも、先ほど申したとおり、さまざまな調整の中で検討をしていくべきかなと考えています。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"時間の関係で一旦は要望にしたいと思いますけれども、こうしたところにだれでもトイレをつけてほしい、こういうご要望がありますので。次に１６１ページ、公園整備事業なんですけれども、公園の遊具の整備の流れ、これについて説明を求めました。","respondent":"多並公園課長","answer":"遊具の整備の流れですが、公園を整備する際に設計を行います。離隔、いわゆる離すような形もとりながら、領域をとりながら行えるようなところで設計しています。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問・要望","question":"遊具のいろいろ集約というんでしょうか、集合遊具というんですか、地元の方からもすごい要望があるんですけれども。スクエア荏原の広場のスペースというんでしょうか、何らかの遊べる道具というんでしょうか、この辺も説明を求めました。","respondent":"多並公園課長","answer":"ただ、１点、ホールでイベント等が行われるときに、非常にお子さんが集まって、それが想定以上の集まりがあるということを聞いてあります。別の場所に設置いたしますと、そういうところからして、非常に慎重に考えなきゃいけないかなと思ってあります。","id":"exchange-011"},{"speaker":"つる委員","kind":"提案","question":"２年前ですかね、質問させていただいて、それを違法駐輪が多いところに張ってということを大阪の事例を通して提案をさせていただいて。江東区がまさに小学校６年生に絵を描いていただいて、それを１６１枚ですかね、区道や緑道に張ったということで報道が出ておりましたとの意見を述べました。","respondent":"谷口交通安全担当課長","answer":"平成２０年以降、路面の放置駐車禁止ということでやっておりまして、大体８０枚ぐらいは路面にシートを張っております。ただ、今まで路面に張ってあるものはそのまま活用するということで警視庁のほうにはお願いしているという状況です。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問","question":"警視庁本庁とそれから現場の所轄というんでしょうか、そのやり方というんでしょうか、そうした違法駐輪そのものがより一層減っていく。商店街との絡みがある中で、やはり違法駐輪が多いんですが、この辺の日々行っていただいている違法駐輪対策があれば説明を求めました。","respondent":"谷口交通安全担当課長","answer":"ただ区域外につきましては、条例上なかなか撤去できないですので、ただ計画的に警告をして撤去しているという状況です。引き続きやっていきたいと考えています。","id":"exchange-013"},{"speaker":"つる委員","kind":"質問","question":"じゃあ、そうしたいわゆるスクールゾーンというんですか、通学路を中心に先ほどのシートですね、検討ほしいと求めました。お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"木村委員","kind":"質問","question":"この豪雨に対して本区のお考えを再度お聞きしますけれども、１００ミリを超えるような雨量が日本のあちらこちらで降ったと聞きます。その３点を、答えるよう求めました。","respondent":"奥田河川下水道課長","answer":"あるいは台風の激化ということで、実は集中豪雨が日本全国的に増えているということがあるのは、そういったものは考えられるかなと思ってあります。","id":"exchange-015"},{"speaker":"木村委員","kind":"質問・要望","question":"そのときに、例えば七十数ミリの雨が降ったということでありましたけれども、そのときの状況はどうだったのか、また教えてほしいと求めました。いつを目途に完成予定なのか、それも、答えるよう求めました。","respondent":"奥田河川下水道課長","answer":"このときというのは、実はこれまで都と連携して整備してきた下水道ですとか、浸水被害の軽減に大きな効果を発揮したと考えています。例えば目黒川ですと９０％を超えるということで、我が区につきましては、浸水対策につきましてはかなり高い進捗を示している形になってあります。","id":"exchange-016"},{"speaker":"木村委員","kind":"質問","question":"そして目黒川の船入場ですか、それ以外にも大小８カ所の調整池があるということですけれども、お聞かせをください。そして、すべての調節池の貯留量というんですか、それはどのぐらいの量を貯めることができるのか。","respondent":"奥田河川下水道課長","answer":"２７０杯分、８万トン以上貯めたというような形で、かなり大きな効果を発現したということになってあります。今７０％を超える形になっているんですが、それが８０％近い形ということで、大幅に進捗するような形になると考えています。","id":"exchange-017"},{"speaker":"木村委員","kind":"質問・要望","question":"確かに荏原の調整池ですか、これ、今お話ありました２０万立法メートルですよね。目黒川の船入場ですか、これは５万５,０００立法メートルですか、こちらが勝手に計算しましたけれども。","respondent":"奥田河川下水道課長","answer":"東京都では東京都豪雨対策基本方針に基づきまして、１００ミリを超える降雨でも生命、安全を確保することとしております。ということで、５０ミリを超える対策につきましても必要だということを認識してございまして、そういったのはやっていく必要があると聞いてあります。","id":"exchange-018"},{"speaker":"木村委員","kind":"質問・要望","question":"強い姿勢で要望していくと考えていますけれども、今、２０２０年には東京オリンピック・パラリンピックがまた開催されます。そういうことを踏まえましても、再度またお考えをもう一度だけお聞かせをほしいと求めました。","respondent":"奥田河川下水道課長","answer":"我が品川区はほかの区よりも高い整備水準では進んでいる進捗状況になっているところです。今後とも引き続き都との連携を一層強化するということで積極的に働きかけるとともに、浸水被害の軽減に全力で取り組んでいきたいと思ってあります。","id":"exchange-019"},{"speaker":"藤原委員","kind":"確認","question":"１年半が過ぎてどういう成果が出ているのか、その後の目標についてお伺いしたいのと、ちょっとほかの自治体とは違っている。それと、１６３ページは、建築確認全体の中の区に来る建築確認の割合を説明を求めました。","respondent":"谷口交通安全担当課長、奥田河川下水道課長、中村建築課長、大串住宅担当課長","answer":"２３区中に１１の区で警視クラスが行っておりますけれども、ほとんどが危機管理ということで参っております。引き続き… それから大仏、それから山王銀座商店街の浸水対策についてなんですけれども、前任からしっかりと引き継いでおります。… 確認申請の数ですけれども、まず品川区内の平成２４年度確認の総数が１,１０６件あります。その中で区が確認をしたものが１０２件ということで… あわせて、退去した場合に、今現在は原状回復工事というのを実施しております。","id":"exchange-020"},{"speaker":"藤原委員","kind":"質問・要望","question":"ワースト５位くらいまで挙げていただきたいのと、それぞれの駅の対策をどういうふうにしているのか、教えてください。２０年の契約期間が終わったんですから、契約にそれは入っていないんですから、いかがか尋ねました。","respondent":"谷口交通安全担当課長、平澤経理課長、堀越人事課長、中村建築課長、奥田河川下水道課長、大串住宅担当課長","answer":"放置につきまして、ちょっと若干成果としましては、平成２０年度につきまして、撤去が２万６,０００台を超えておりました。… 初めにお客様用の駐輪場、こちらが２５０台分あります。現在外壁の改修工事を実施しているということで、庁舎の１階のＪＲ側のところに１５０台ほど… 庁舎に勤務している職員のうち、自転車利用で通勤手当が支給されている人数は７０名です。そこで、今、建築課では、建築職の技術職員が２０名おりまして、その中で１０名が１級建築士の資格を持っております。","id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"学校内のトイレの配管の耐震化はどうなっているのかということなんですけれども、耐震化されていなかったらいつごろなるのかということが１点。もう１点は、下水道じゃなくて、上水道、そもそも上水道の耐震化は必要じゃないんですかという質問なんですけれども、お願いします。","respondent":"鈴木防災課長、小林施設整備課長","answer":"防災の対策上、また災害時以外にも重要なライフラインですので、その耐震化については重要だというふうに区としても考えております。東京都のほうの実施事業になりますので、都と連携をしつつ… 学校の耐震化の質問ですけれども、学校の１系統、便所の１系統を耐震化を行っております。場所については、避難所の体育館の近くだとか校庭の近くだとか、いろいろ学校によって若干違いますけれども、１系統を耐震化しています。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"都市計画道路の用地買収ですけれども、２９号線を念頭に、都市計画道路の用地買収補償額決定の仕組みを伺いたいと思います。そしてこの延焼シミュレーションでは、同じく冬１８時にどの方向から吹くという風向きなのか、伺いたいと思います。","respondent":"品川木密整備担当課長","answer":"平成２４年の４月に出されました被害想定、ここの中では北北西の風で８メートルというふうになっております。風速のみしか、風速８メートルというふうには聞いているんですが、方向のほうについては現在聞いておりません。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"４５度異なる風向きで、なぜこのシミュレーションが２９号線の防災に役立つ根拠と言えるのか、伺いたいと思います。縦に伸びる２９号線に沿って火災は上から下に燃え広がってしまうのではないかと思いますけれども、いかがか尋ねました。","respondent":"品川木密整備担当課長","answer":"ですので、北北西から風が吹きますと十分に延焼遮断効果があると考えています。地震の後の火災というのは、風向がどうだとか、そういうことで道路の延焼遮断効果がないというふうには区としては考えておりません。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"何で２９号線が防災の役に立つのか、改めて伺いたいのと、結局これでは上から下にも横にも広がってしまうと。２９号線で延焼が遮断するという説明は成り立たないと、事実が異なると思いますけれども、いかがか尋ねました。","respondent":"品川木密整備担当課長","answer":"先ほど私が申し上げたのは、道路のないところでの火災の燃え方についてご説明をしました。当然道路のあるところでは火災は止まるということで考えております。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"区は、２カ所突破する２９号線でも防災対策に役に立つと思っているのか、伺います。風向きだけでなく、実際の震災とは異なるこのシミュレーションでどうして防災に役立つと言えるのか伺いたいと思います。","respondent":"品川木密整備担当課長","answer":"現在木密１０年プロジェクトの中では、木造住宅を耐火建築物、または準耐火建築物に変えてもらうプロジェクトを行っております。あくまでもまちづくりの中での道路ができたときにどうかというときの想定でやっているものが延焼シミュレーションです。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"さらに、都のシミュレーションの前提を説明しますけれども、実際には補助４６号線ではそこまで完成する前に事業を終了。これでもなぜ防災に役立つと説明ができるのか、改めて伺いたいと思います。","respondent":"品川木密整備担当課長","answer":"ですので、建て替えますと耐火建築物等に建て替わりますので、後々には沿道の周辺はすべて耐火建築物になるというような考え方です。我々が何度も説明しているように、沿道周辺が耐火建築物になる、こういうことによって延焼遮断帯の効果が出てくるです。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"続いて都市計画道路の用地買収についても伺いたいんですけれども。基本的に同じルールで行われると伺っておりますけれども、誰が土地の価格を決めるのか、そこを伺いたいと思います。","respondent":"河内用地担当課長","answer":"これを上限とした価格交渉を行い、契約額となるものです。なお、こちらにつきましては、任意補償の範囲ですので、よろしくお願いいたします。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問","question":"事業主によって変わってきますけれども、話し合いによって決まるのか、誰が決定するのか伺いたい。建物の価格は、建物の経年劣化分は補償額の対象に含まれるのか、伺いたいと思います。","respondent":"河内用地担当課長","answer":"こちらにつきましては、先ほど申しました補償基準に従いまして行われるものです。したがいまして、不動産鑑定士の方が鑑定した価格をもとに決定されるものと認識しております。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問","question":"自分の持ち出しがなければ今と同じ家を建てることができないと、そういう仕組みになっているのでしょうか、伺いたい。やっぱりこういう計画そのものはやめるべきだと思いますけれども、いかがか尋ねました。","respondent":"河内用地担当課長","answer":"つまり、減価償却につきましては控除するという考えに至っております。話し合いで決まるものでなく、一定のルールの中で、全国共通公平に決まっているものと認識しております。","id":"exchange-030"},{"speaker":"松澤委員","kind":"質問","question":"そして、区民住宅の中には、長期滞納者対応経費が５４万５,０８０円、１４２万５,１６０円でしょうか、書いてあります。これについて内容を説明を求めました。","respondent":"大串住宅担当課長","answer":"その方につきましては、なかなか我々職員のほうでは対応が難しいということで、弁護士の方に、法律事務所のほうに委託をしているものです。長期滞納者の対応経費です。","id":"exchange-031"},{"speaker":"松澤委員","kind":"質問","question":"２０万２,０００円、６４万円、２９万４,０００円。実効が上がっていないのに何でこうやってまた予算を大きくつけているのか、そこもちょっとお聞きしたいと思います。","respondent":"大串住宅担当課長","answer":"現年度分につきましては、ご案内のように、区営住宅、あるいは区民住宅、指定管理者を使って管理を行っております。１カ月ですとか２カ月、あるいは連帯保証人の状況、なかなかその辺の交渉等々が進まないというのが一つ大きな原因になっているかと思います。","id":"exchange-032"},{"speaker":"松澤委員","kind":"質問・要望","question":"ところで、この区民住宅、区営住宅、何ていうんですかね、不納未済額というんでしょうか、期日までにお金が入らない。これについてどのように考えているのか、ちょっとコメントをほしいと求めました。","respondent":"大串住宅担当課長","answer":"１カ月、２カ月少ない段階での促進をしておりますし、また連帯保証人さんへの連絡といったことも２カ月目から行っているという状況です。なかなかそういった中でも滞納が増えているというのは、大きな課題と考えているところです。","id":"exchange-033"},{"speaker":"松澤委員","kind":"質問","question":"これ、指定管理者がいるんですから、やっぱりこれ、しっかりやらすべきじゃないんですか。滞納額が増えるようだったら指定管理者かえるということも考えるべきだと思うんですけれども、その辺しっかりとお聞きしたいと思います。","respondent":"大串住宅担当課長","answer":"委員おっしゃるように、ちょっとでもたまると次どんどん雪だるま式に増えていくという状況、そのとおりです。１カ月、２カ月目、こういった状況です。","id":"exchange-034"},{"speaker":"松澤委員","kind":"質問","question":"１５６ページに細街路拡幅整備事業、２項道路整備だと思うんですけれども、２項道路というものがあります。何としても４メートルに広がるようにということで、建物を建てるときは避けてくださいよという形で、この事業内容を両方ともお聞きしたいと思います。","respondent":"品川木密整備担当課長、中村建築課長","answer":"耐震の工事の件ですが、耐震の中には、実際の改修と、それから除却工事、それから建替え工事と３種類あります。ただ、建替え、それから除却につきましては、品川区内の俗に言われます木密地域ですと、３分の１ぐらいの地域… 細街路拡幅整備事業ですけれども、こちら、委員言われましたとおり、道路を４メートルに拡幅すると。生活道路というふうにも呼ばれる狭隘道路ですけれども、こちらも住みやすい環境をさらに確保するという目的も一つにはあります。","id":"exchange-035"},{"speaker":"松澤委員","kind":"質問","question":"ところが、その建物が、建て直すんじゃなくて、耐震改修しましょうという話、区に来た場合どうなるんですかね。２項道路、この政策がどうしても私は納得いかないので、その点について説明を求めました。","respondent":"品川木密整備担当課長","answer":"その中で、２項道路のところでの耐震改修が来た場合、これについては極力区のほうでセットバックはしてください。その中で、そういう場合については、少しでも下がっていただいて改修をしていただくというような形で指導をしながら改修のほうは進めている状況です。","id":"exchange-036"},{"speaker":"松澤委員","kind":"意見","question":"その改修経費、残ったのはいいんですけれども、２,１３２万円。この内容について聞きたいと思いますとの意見を述べました。","respondent":"多並公園課長","answer":"そちらを残す形でそれの補修をするというところが大きな内容です。結構大きな補修も行いながら、構造自体はいじくらず、残すような形で行っているというのが今回の内容です。","id":"exchange-037"},{"speaker":"松澤委員","kind":"質問","question":"三井文庫、公園の景観にマッチしてなかなかすばらしいなと思います。大変に防災機能、公開日を設けなくてはいけないなと思っているんですけれども、それの公開なんかについてはどう考えているか尋ねました。","respondent":"多並公園課長","answer":"イベント等で、我々が管理できる中での公開という形ではできるかと考えていますので、そのようなタイミングを見ながら行っていきたいと考えているところです。","id":"exchange-038"},{"speaker":"塚本委員","kind":"質問","question":"それから、次に１５５ページの路面維持管理費に関連してお伺いをしたいと思います。制限、何かしら手を入れないとそのままでは使い続けることができないというようなものがあるのかどうか、最初にお伺いしたいと思います。","respondent":"中村建築課長","answer":"例えば数年であっても亀裂などが生じて、構造上支障があるとすれば、それはそのときが寿命ということになります。調査をしてもらって、そしてその強度を確認していただいて、そこで強度がなければつくりかえていただくというような方法です。","id":"exchange-039"},{"speaker":"塚本委員","kind":"質問","question":"かかってきて、細分化されて、今は幾つかの一戸建てがその一つの擁壁の上に建っているというようなところも品川区内にも幾つかあるかと思います。その１軒１軒がそういった擁壁の管理、そういう一つの擁壁の上に何軒も建っているところの１軒が建て替える、お伺いしたいと思います。","respondent":"中村建築課長","answer":"既存の形のまま安定しているということであれば、擁壁にそれ以上負担をかけないような状態で設計をしていただくと。擁壁のさらに下のほうまで杭を打って、擁壁に土の圧力がかからないようにしていただくと、そんなようなことを現実的な対応として行っております。","id":"exchange-040"},{"speaker":"塚本委員","kind":"質問","question":"やはり擁壁というのが今後まちの防災の観点で、そういうものをしっかりと行政として把握していく必要というのがあるんじゃないかと思います。いわゆるまちの品川区内の擁壁の危険度、こういったものを現在品川区としてどの程度情報収集なり掌握をされているか、現状をお伺いしたいと思います。","respondent":"中村建築課長","answer":"大体おおむね５棟以上に被害が及ぶような規模のものにつきましては、今、品川区内で４３カ所ということで把握をしています。","id":"exchange-041"},{"speaker":"塚本委員","kind":"質問・要望","question":"今後のまちづくりといったことを検討していく中で、擁壁の危険度、しっかり管理をしていってほしいと求めました。どこに品川区の擁壁の危険というものが存在しているのか、そういったことをぜひ検討してほしいと求めましたけれども、いかがか尋ねました。","respondent":"中村建築課長","answer":"複数の棟に被害が及ぶ擁壁などについて４３カ所と申し上げましたけれども、こちらは、あるいは危険かというのを判断するのは非常に難しい話です。","id":"exchange-042"},{"speaker":"塚本委員","kind":"質問","question":"ぜひ前向きに対処のほう、よろしくお願いしたいと思います。ごみ屋敷に関連してちょっとお話をお伺いしたいんですけれども、これはそれで正しいかどうかということと、そこをお伺いしたいと思います。","respondent":"安井土木管理課長","answer":"基本的に道路法の４３条のほうの「何人も道路に関し」というところで、２号のところに、まずそれらを除却するような命令を出していくというような形が基本的に考えられているところです。","id":"exchange-043"},{"speaker":"塚本委員","kind":"質問・要望","question":"過去の事例としてあればご紹介していただきたいし、今の法にのっとって行政代執行のような形でこれは撤去できるものと、このように認識をしてよろしいんか尋ねました。","respondent":"安井土木管理課長","answer":"法の第７１条１項の規定によりまして、監督権を発動して、必要に応じて代執行等の処分をしていかざるを得ない。そういった手続をとっていくということで、違法状態の解消を図るということになっているところです。","id":"exchange-044"},{"speaker":"塚本委員","kind":"質問","question":"次に、公道についてはそのようなことなんでしょうけれども、今度私道についてお伺いをしたいと思います。こういったことも書かれているものもあるんですけれども、やっぱり無理なのか、というところのご認識をちょっとお伺いしたいと思います。","respondent":"中村建築課長","answer":"ただ、既存の道路そのものには指定をすることはできませんので、位置指定道路そのものに基づく指導というのはなかなか難しいのかと思います。道路の通行の安全と災害の危険性を低くするという観点から、お願いに行ったりして、撤去の働きかけを行っているというのが現状です。","id":"exchange-045"},{"speaker":"塚本委員","kind":"質問","question":"さらに、ちょっとこれもどの程度可能性があるのかをお伺いしたいんですが、即時強制という制度もあると。これはものの本をちょっと読んだときに書いてあったんですけれども、この辺につきまして区としてのご見解を最後にちょっとお伺いしたいと思います。","respondent":"中村建築課長","answer":"その辺は、条例の制定につきましては、今後研究をさせていただければと考えております。","id":"exchange-046"},{"speaker":"高橋委員","kind":"意見","question":"１５４ページ、１５９ページ、１６０ページの公園管理費についてお尋ねします。こちらは今年度の予算委員会でも所管が移ったという、そういう議論があったと思うんですが、その辺もお願いいたしますとの意見を述べました。","respondent":"永尾高齢者福祉課長","answer":"やさしいまちづくり推進費ですけれども、おたがいさま運動を進めるための選定委員会等を行いまして、またシンポジウムを行った、そういう経費です。","id":"exchange-047"},{"speaker":"高橋委員","kind":"質問","question":"今、高齢者福祉課と都市計画課が連携していくというお話があったんですが、具体的な連携の場というのはどのようなところになっているんか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"平成２４年の７月から８月にかけて応募いたしまして、高校生、また一般の方に対しても啓発も兼ねた意味での標語の募集を行いました。その中で、一般の区民の方や区役所の職員の方も対象に疑似体験等も行いながら、おたがいさまの運動について推進しています。","id":"exchange-048"},{"speaker":"高橋委員","kind":"意見","question":"別の款でも出てきましたが、品川区でも、視覚障害を持った方のサッカーの競技が予定されております。今ありましたやさしいまちづくり推進のそういった観点から、どのような区のお考えがあるか、説明を求めました。","respondent":"藤田都市計画課長","answer":"平成２５年、平成２６年につきましては、重点整備地区として大井町周辺バリアフリー基本構想、こういったものを策定していく考えです。こうした中にも、オリンピック・パラリンピックの開催についての視点も入れて検討していきたいと考えています。","id":"exchange-049"},{"speaker":"高橋委員","kind":"質問・要望","question":"しかし、大田区、品川区の方々が使用して、放置、そして撤去が随分あると思うんですが、平成２４年度で撤去がどれぐらいだったのかと。その平成２４年の状況を受けてどのように対応をされていく状況なのかということも確認させてください。","respondent":"谷口交通安全担当課長","answer":"昨年度の撤去の台数ですけれども、大森駅につきましては６７７台ということで、大変放置も多いと考えております。区内でも放置自転車の多い大井町と同じような位置づけで今取り組んでいるところでございまして、警備員、指導員等の今検討を進めているところです。","id":"exchange-050"},{"speaker":"高橋委員","kind":"意見","question":"１６０ページ、熱中症、あるいは熱中症寸前の利用者の方がたくさんいました。ベンチ等に日陰がないということで、その点についてどのような考えでおられるか、説明を求めました。","respondent":"多並公園課長","answer":"その利用をするときに、ベンチを可動式にする形にしないと利用に支障があるということで、そのようなところで行っております。その関係で、固定するような屋根は設置できないというところで、現在のところはそのように運用しています。","id":"exchange-051"},{"speaker":"高橋委員","kind":"意見","question":"このような今年のような猛暑で健康について害があると困りますので、ぜひ前向きに検討していただいて、よろしくお願いしたいと思います。以上で終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"あべ委員","kind":"質問・要望","question":"１５９ページ、治水対策、それから１６０ページの公園管理費、１６２ページの都市開発費からそれぞれお伺いをしたいと思います。これはどうなんでしょう、制度上、貯留設備の整備の進捗に合わせて基準を変えることってできないんでしょうかね。","respondent":"稲田道路課長、多並公園課長","answer":"１０分単位でも急激に上がってくるです。現在のところは、今まで使ってきたこの値でやっていきたい、吹鳴もやっていきたいと考えております。 区内には６カ所に設置しています。天王洲、八潮北、品川中央、南ふ頭、東品川、しながわ区民公園という、有料運動施設がある公園について設置しています。","id":"exchange-053"},{"speaker":"あべ委員","kind":"質問・要望","question":"それから、公園内のシャワーについて、近年の利用状況についても伺ったのですが、今ちょっとお答えがなかったように思います。区外からも来ていただく、そういったことがより魅力ある品川をつくるために有効なのではないかと思うのですが、いかがか尋ねました。","respondent":"多並公園課長","answer":"そのプールの横には、プールだけではなく、テニス利用者のための更衣室というのもありまして、そこのちょうど今設計を進めているところです。その中で、ランナー向けのサービスをその中でできないかというのをちょうど今検討している最中です。","id":"exchange-054"},{"speaker":"あべ委員","kind":"質問・要望","question":"一般質問でも伺いましたけれども、そろそろ設計も必要な時期になってきているかなと思うんですけれども、進捗を教えてください。パッチワーク状でどんどんまちがなっていくのは何か残念ですので、何かいい方法はないかと思うんですが、いかがか尋ねました。","respondent":"溝口都市開発課長","answer":"同じ北品川五丁目第１地区の産業交流支援施設につきましては、そういったところもにらみながら営業をかけていきたいと考えているものです。今後どのような材質を使っていって、将来的に持続的にきれいなまちづくりが図れるかというのを検討していきたいと考えています。","id":"exchange-055"},{"speaker":"あべ委員","kind":"提案","question":"現段階でもまだ提案事業で、提案を待っているということなんですけれども、ぜひ区としても共有してほしいと求めました。区も責任と熱意を持ってこの施設をつくることに当たっていただきたいと思うので、その決意と思いを語ってほしいと求めました。","respondent":"溝口都市開発課長","answer":"地域交流施設につきましては、やはり都市計画提案で定まったものです。集える、そういった施設になるようにこれからも組合側には指導していきたいと思いますし、区も一緒に考えていきたいと考えています。","id":"exchange-056"},{"speaker":"こんの委員","kind":"質問・要望","question":"地域の方々のさまざまなご要望があるので、ぜひその声を取り入れていただきたいという、こういう要望をさせていただきました。今回の城南第二小の子どもたちのワークショップがそれに当たるというものなのか尋ねました。","respondent":"安井土木管理課長、稲田道路課長、多並公園課長","answer":"その許可をおろしましてから、工事の着手、それで一旦仮復旧というような形で工事を行って、復旧の工事を行います。自費工事ということで… それで、毎年３年先を見通して、傷んだ状況によって計画を立てていきます。その３年先の状況を各企業者等にお知らせし、掘削調整会議というのを行いまして… 隣の小学校である城南第二小学校の３年生、４年生の生徒２０名を対象としまして、その意見を聞こうということでワークショップを行ったものです。","id":"exchange-057"},{"speaker":"こんの委員","kind":"質問","question":"さきの予算特別委員会でもあくつ委員からお聞きしました公園の定義、また信号機や道路交通標識、これを備えた公園であると。こうしたことが、こういう公園の整備をお願いしたいと思いますが、いかがか尋ねました。","respondent":"安井土木管理課長、多並公園課長","answer":"大井倉田保育園の前の道路ですけれども、現在ガス管の新設、それから旧配管の撤去工事を行っているところです。あちらの場合は、なかなか車等が通らないところですので、早期にこちらのほうについては対処してまいりたいと考えています。自転車のマナー啓発事業で子どもや高齢者の方に対して交通安全教室などを定期的に行うということで警察のほうからお伺いしています。","id":"exchange-058"},{"speaker":"こんの委員","kind":"質問","question":"景観という角度からもう１点あるんですけれども、例えば戸越銀座商店街などがおしゃれな舗装がされております。これは景観上あまりどうなのかなと思いますので、いかがでしょうかというところですが、意見として終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"渡部委員","kind":"質問","question":"三つぐらい伺っていくんですが、まず公園のことなんですけれども、先日地上波で見て、品川区って借地公園というのはあるんですか、ないんか尋ねました。","respondent":"多並公園課長","answer":"公園、児童遊園という中には借地で借りているところあります、幾つかですね。まあ、東京都が持っているところの上を借りて整備している、いろいろなさまざまなパターンの公園があります。","id":"exchange-060"},{"speaker":"渡部委員","kind":"質問","question":"４０年も親しんだのに借地ということがわからなかったとかというケースがあって、市で買い取ってくれと言ったところ、お金ないから買えない。ちょっとその辺の考え方、伺わせてください。","respondent":"多並公園課長","answer":"そこにつきましては、もともと借りてきているところからすればやむを得ないところだと考えています。あまり過度なものを設置しないだとか、改修等するときにでも考えながら整備してお返しできるような形、そんなような形で今も考えているところです。","id":"exchange-061"},{"speaker":"渡部委員","kind":"質問","question":"ちょっと質問変えるんですけれども、突然返せと言われて、返すような事例が発生していたのかどうなのか。その場合どのようなやりとり等があったのかというのを教えていただいてよろしいか尋ねました。","respondent":"多並公園課長","answer":"青空野球場という野球場がありまして、あれが東京都の港湾局の関係で事業で必要だということでお返ししたと。そのときにそういう事例が私の覚えているところではございました。","id":"exchange-062"},{"speaker":"渡部委員","kind":"意見","question":"買い取りで区の公園として続けるとなれば、やはり必要となれば区は買う用意があるのか、その辺の考え方が知りたいなとの意見を述べました。","respondent":"松代防災まちづくり事業部長","answer":"いかんせん、それを１０年、２０年しっかりと担保するものはなかなかできないというのが現状です。地域の方にもその辺のところをご説明しながら、公園として整備をしている、そういった状況のものです。","id":"exchange-063"},{"speaker":"渡部委員","kind":"質問・要望","question":"第３土曜日、かけてほしいというような意味合いの質問を、スクールゾーンの枠にかけてほしいという質問をさせていただいて。第３土曜日も品川区は学校やっていますから、そこを何とかスクールゾーンに指定をしていただきたいと思うんですが、そのお考えをお願いいたします。","respondent":"谷口交通安全担当課長","answer":"ただ、補助標識で第１、第３とか、そういう標識が、補助標識がつけられた場合、運転者にとっては大変わかりづらい状況になります。都内全域が第１、第３というふうになれば、また全体的に考える必要もあろうかと思うんですけれども、現在のままで行くものと考えているところです。","id":"exchange-064"},{"speaker":"渡部委員","kind":"質問","question":"そこだって、８月除くになっているわけではないですし、例えば長期休暇を除くというふうになっているわけではないじゃないですか。第１、第３の土曜日というのは、もう守れないで終わりになっちゃうんか尋ねました。","respondent":"谷口交通安全担当課長","answer":"やはり運転者の立場、確かに８月中は学校がお休みといいながらも、それは安全確保については当然警察としても考えていると聞いております。ただ、なかなか今の現状では難しいということをご理解いただければと思います。","id":"exchange-065"},{"speaker":"渡部委員","kind":"質問","question":"うまというんですか、また名前忘れちゃいましたけれども、出していただいている。一生懸命僕も研究していきますが、申し入れは続けてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問","question":"品川区は歓迎はしていますけれども、なぜ今、リニア新幹線なのか、魅力やメリットがあるのかどうか、この点をお伺いします。２点目は、非常口１カ所、お伺いいたします。","respondent":"藤田都市計画課長","answer":"ルートですけれども、地上になかなか出てこないので説明がしにくいんですけれども、先ほど非常口というお話がありましたけれども。こうした国の施策について十分に理解をする中で、区のまちづくりの中にこうしたものを十分に生かしながら進めていきたいと考えているものです。","id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問","question":"区民にとってどのように歓迎されるものになっているのか、お伺いしたいと思います。地下４０メートルを通るということを知って、勝手に通らないでほしい、品川区にも説明をしていく責任があると思うんですね。","respondent":"野呂瀬環境課長、藤田都市計画課長","answer":"さきに行われた９月２８日の説明会、私も傍聴してまいりました。その辺の質問に対してＪＲ東海が答えていたのは、４０メートル下を掘るということで、そういう説明を私も一緒に立ち会って聞いてきたところです。 最近では平成２５年７月３０日に町田市のほうで説明会をやってあります。中央新幹線の概要、それから、影響評価等の進捗状況などの説明をしたと聞いてあります。","id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２点目、運転手が乗車せず、安全確認への大きな不安と、大きな不安を置き去りにする建設であるといった点。そして、都営住宅の改修、改築、進めていただくことを求めますが、いかがか尋ねました。","respondent":"溝口都市開発課長","answer":"それにつきましては、都営住宅を動かすとか、動かさない、そういったものをしているものじゃありません。動かさない、そういったものの計画ではありませんので、ご理解いただきたいと思います。","id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なぜこのように切りかえたのか、説明会を変えた理由をお伺いしたいのが１点です。３点です。","respondent":"藤田都市計画課長","answer":"放射２号線の説明会、今回１０月の２１日、それから１１月の４日ということで、荏原第一区民集会所のほうで行う予定になってあります。それから、個別の説明の中身ですけれども、基本的には用地測量を行いますという説明になるんだと考えています。","id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問・要望","question":"改めてそこをお伺いいたします。ぜひ個別説明会をやめて、全体説明会に戻すべきであると思いますが、いかがか尋ねました。","respondent":"藤田都市計画課長","answer":"説明会の中ですけれども、もちろん用地測量の説明だけでなく、質疑が当然あるわけですから。なので、今の段階では郵送の数だけお示しをさせてください。","id":"exchange-071"},{"speaker":"山元委員","kind":"質問・要望","question":"初めに、１６４ページの耐震シェルターについてお伺いをさせてほしいと求めました。教えていただきたいということと、教えていただきたいと同時に、業者登録した方たちが携わったのかどうかも教えてほしいと求めました。","respondent":"品川木密整備担当課長","answer":"今までやっていた業者１社と、それから新たに８件登録していただいた業者の１社のみ、品川シェルターのほう対応していただきました。合計で結局２社の対応というふうになっております。","id":"exchange-072"},{"speaker":"山元委員","kind":"質問","question":"ここはやったほうがいいなというような、品川区内にそういうケース、何件ぐらいあるんでしょうか。やっている、やっていないに関係なくですけど。","respondent":"品川木密整備担当課長","answer":"ただ、そういう方については、シェルターのほうで対応していただくというような形になります。おじい様、おばあ様の部屋にシェルターを設置するというようなケースが非常に多く見られます。","id":"exchange-073"},{"speaker":"山元委員","kind":"質問・要望","question":"昨年の予算でいくと３２件に対してまだ１２件ということで、実態調査していらっしゃるかなと思いますが、その結果はどうなのか。デザインというんですかね、つくりというんですかね、その辺も教えてほしいと求めました。","respondent":"品川木密整備担当課長","answer":"なかなか、やはりシェルターのほうを説明しますと、いろいろ細かい制限があります。私は過去に答弁で検討しますというような形も言ったかと思うんですが、現状として、あまりデザインの変更のほうが進んでいないというのが現状です。","id":"exchange-074"},{"speaker":"山元委員","kind":"質問・要望","question":"では、１６０ページの勝島の海レンタルボート運営委託についてお伺いしたいと思います。今回この事務事業評価ではＣの見直しで、７月、８月、土日祝日に実施と書いてありましたけれども、実際これ、何日ボート遊びができたのか尋ねました。","respondent":"多並公園課長","answer":"平成２４年度の実績といたしましては、２２日間、土日祝日の運営ということで行いました。それで池に負荷がかかる、そういうところです。","id":"exchange-075"},{"speaker":"山元委員","kind":"質問・要望","question":"今後見直しと言われていますけれども、ぜひとも水辺に触れることのできるボート遊びをできれば継続していただきたいと、そう思っています。ご意見ほしいと求めましたが、そんな工夫をしてほしいと求めましたが、一言ご意見をほしいと求めました。","respondent":"多並公園課長","answer":"利用者の区民の方が１割という実態も踏まえながら、今後は慎重な検討ということで進めていきたいと思ってあります。","id":"exchange-076"},{"speaker":"原委員","kind":"質問・要望","question":"１６３ページから１６４ページにかけまして、建築確認事務、それとあとは防災全般に質問させてほしいと求めました。担当の課長は学生時代医学畑というような話も伺っているものですから、１０名ぐらい１級建築士がいらっしゃるということ、これが実に。","respondent":"安井土木管理課長、谷口交通安全担当課長、溝口都市開発課長、中村建築課長","answer":"私のほうからは屋外広告物の取り締まりについてご説明いたします。こちらは、屋外広告物法と都条例に基づきまして… 指導啓発を強化したということがございまして、平成２４年度は１,２７８台、年間を通して１３０日の撤去活動を実施したところです。… 公有地管理事務について私のほうから追加でご説明します。官官も含むもので３カ所、合わせて１３カ所の部分、境界確定を行っているところです。","id":"exchange-077"},{"speaker":"原委員","kind":"質問・要望","question":"何でそれを伺ったかというと、そういったことがあるものですから、先ほど防災全般についてお伺いしますと申し上げましたけれども。ですから、２点、よろしくお願いをいたします。","respondent":"中村建築課長、鈴木防災課長","answer":"今、そうでない場合があったときには、やはりこういったものもちゃんと守っていただくということももちろん大切なことだと考えております。ただ、法に抵触している部分については強く是正をしていただくとともに… 私からは防災と減災についての区の考え方についてお答えをいたします。さまざまな手法による防災対策、減災対策を組み合わせまして、品川区全体の防災力の向上に取り組むというのが現在の区の考え方です。","id":"exchange-078"},{"speaker":"原委員","kind":"質問","question":"それからあとは減災特別プロジェクトの最終成果報告、これ、実際には平成１９年から平成２３年の５年間ですね。ですから、各先進国の関係もありますでしょうから、その辺について区としての考え方をお聞かせほしいと求めました。","respondent":"鈴木防災課長","answer":"委員ご指摘のように、５年間にわたる研究の成果が今年の３月に報告書として出されたものです。地理情報等についての標準化を図ることで、それも区のさまざまなシステム導入の中で活用できる部分については活用したいと考えているところです。","id":"exchange-079"},{"speaker":"原委員","kind":"意見","question":"そうしますと、今の国際基準のいろいろなところで標準化したことによって、これは区に生かされてスタートしているという認識という形でおります。","respondent":"鈴木防災課長","answer":"これは減災特別プロジェクトの中で、その成果から各自治体等の取り組みについて参考となるような項目について例示をされたものです。それから、それを地方自治体へ導入する支援というようなところで、品川区に生かせるものは生かしていきたいと考えております。","id":"exchange-080"},{"speaker":"原委員","kind":"意見","question":"再度もう１点。地方自治体への導入と、ここのところについてもう１回お考えをほしいと求めましたので、よろしくお願いをいたしますとの意見を述べました。","respondent":"鈴木防災課長","answer":"先ほど申し上げました支援者生活再建システムの再建のための基本システムの開発の部分ですが、短い期間で対応ができるかと考えておりますので、しっかりと研究をした上で取り組んでいきたいと考えております。","id":"exchange-081"},{"speaker":"西本委員","kind":"質問","question":"そのためなんでしょうか、公園にたくさん自転車が放置されています。何のためにというところで目的ですね、あと、目標についてお聞きいたします。","respondent":"安藤文化スポーツ振興課長、溝口都市開発課長、品川木密整備担当課長","answer":"駐輪場については、今、２時間まで利用しても、誰が使っても無料ということで今はなってあります。それでもって無料になるというシステムです。少人数でありますが、それぞれの都市計画ですとかまちづくりを検討していく、どうしても委託に頼らざるを得ないという部分があります。… 最終的なところとしては、地区計画等、そういったものができればというような形で会のほうは進めております。","id":"exchange-082"},{"speaker":"西本委員","kind":"質問・要望","question":"要望だけ一方的な話をする、どうもあの会が、誰でも参加できるんですよという形で応用ができないかなと思っています。２８号線、放射２号線、その件に対するご見解をお聞きいたします。","respondent":"安藤文化スポーツ振興課長、溝口都市開発課長、品川木密整備担当課長","answer":"そこの管理事業者に言って、注意を促して、自転車の駐輪場にとめるような指示をこちらのほうもしています。電子マネーについては利用ができません。 再開発事業を進めていく上にはさまざまな専門的なコンサルタント、または民間事業者と、よりよいまちづくりができるように考えております。役割分担ですと… 今後不燃化特区を進めていく中で、まちづくり協議会等、密集事業でやっていることを参考にしながら進めていきたいと考えております。","id":"exchange-083"},{"speaker":"西本委員","kind":"質問・要望","question":"住民サイドの方たちと自由に意見を聞くことができるということもありますので、それを次の再開発に生かしていただきたいなと思います。放射２号線、これはやはり住民と一緒にまちづくりをつくっていくんだということでいい仕組みをつくっていただきたいと希望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"渡辺委員","kind":"質問","question":"成果報告書１６１ページ、しながわ区民公園北側ゾーンの関係、１５４ページ、土木総務費全般と１５９ページ、水辺空間の整備促進で伺います。その中で主な変更点等ありましたらお知らせください。","respondent":"多並公園課長","answer":"そのちょうど検討しているときと地域防災計画が同時並行で進んでいったところと、あと、同時並行で進めるところで進めてまいりました。その点を確認し、最終的には整備のときにボーリング調査を行い、今後進めてまいりたいというのが今の現状の大きな確認してきた点です。","id":"exchange-085"},{"speaker":"渡辺委員","kind":"質問・要望","question":"機材ですか、釣り堀の今、活用。釣り堀の要望も非常に多いかと思います。","respondent":"多並公園課長","answer":"そこら辺で中央ゾーンを行った後、どこで北側ゾーンを行うかというのを今後、実施時期も検討してまいりたいと考えているところです。そこのいろいろな今の利用者の方のご要望も含めながら、その中で検討していきたいと思ってあります。","id":"exchange-086"},{"speaker":"渡辺委員","kind":"質問・要望","question":"その辺の見解と、敷地がとにかく広いですから、もうちょっと一工夫。この区民公園、手を入れてほしいと求めましたが、いかがか尋ねました。","respondent":"松代防災まちづくり事業部長","answer":"委員からのお申し出がどのようにそれに反映できるのかというのが今後の課題だと考えていますけれども、それをするということが条件になっています。今もそれが続いておりますので、今の公園のあり方というものを考えていきたいと、このように考えているところです。","id":"exchange-087"},{"speaker":"渡辺委員","kind":"質問","question":"このあたりの船着場という視点で、現在の進捗状況を伺いたいのが１点。コーディネーターであったり、チャレンジするという点もあるかと思いますが、その点、水辺の整備促進の点からいかがか尋ねました。","respondent":"奥田河川下水道課長","answer":"例えば区のほうでも、東品川一丁目３番先の天王洲運河の水辺広場前に桟橋を建設いたしまして、本年４月から供用開始しています。平常時におきましては、そういった水辺のにぎわいとか、そういったような水辺のにぎわいなんかというものをどんどん広げていきたいと考えています。","id":"exchange-088"},{"speaker":"若林委員","kind":"質問・要望","question":"モデル的な事業のスタートなんでしょうかね、また、今後の展開の見通しなんかもお聞きしておきたいと思います。私のほうからも行っていただきたいという要望、予報をなぜ出すかといったら、これはぜひ必要ではないかと思いますので。","respondent":"奥田河川下水道課長","answer":"昨年の３月中旬から５月までの間に五反田ふれあい水辺広場区域内において、ケータリングカーによるランチの提供の社会実験を実施したところです。","id":"exchange-089"},{"speaker":"若林委員","kind":"質問・要望","question":"見直すつもりはないということなんですが、今のダブルスタンダード、これは、じゃあ、防災行政無線で二つ流すということになっちゃいますよね。これは絶対緊急に見直す必要があると思いますので、重ねてご要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１６２ページの都市開発費についてお伺いをします。計画されているものも、決定されたものと、まだ決定はされていないけれども、計画中だというところもわかったら説明を求めました。","respondent":"溝口都市開発課長","answer":"１地区についてはもう既に都市計画決定をしておりまして、もう１地区は今年度中の都市計画決定を目指しているものがあります。大井町の駅のところについても、再開発事業の中で、１００メートルを超える建築物を計画しているものです。","id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、７８プラス３棟ということで、ここには西品川一丁目とかは入っているんでしょうか。その理由もあわせてお聞かせほしいと求めました。","respondent":"溝口都市開発課長","answer":"建物だけ所有している方が６名おりまして、その方が地区外に転出された方が２名という形になります。そういった中で決まっていくものだと考えていますので、その方たちをそのような形での権利返還計画というのを立てて行っていくものと考えております。","id":"exchange-092"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今度は西品川一丁目地区についてお伺いしたいんですが、５８.６７人で、マンションには入らないという方もいるということもお聞きをしました。こういう状況になっているということが改めて地域の方々のお話を伺って思ったわけなんですけれども、その点についてはいかがか尋ねました。","respondent":"溝口都市開発課長","answer":"再開発事業の事業を実施するまでの流れですが、都市計画決定を踏まえて、その後、権利者の方たちが集まって組合を設立していく。ある程度のご理解をいただいて事業は進めてきているというふうには聞いておりますし、権利返還後、今後詳細に詰めていくものと考えているものです。","id":"exchange-093"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"しかし、そこに住み続けるという選択肢は、組合が設立されて、事業が認可をされていけば、もう許されないわけじゃないですか。その仕組みを判こを押す前に示すという、そういう方向ができると思うんですけれども、その点についてはいかがか尋ねました。","respondent":"溝口都市開発課長","answer":"再開発事業につきましては、これまでも同じようなやり方をしてきて進めておりますので、従前どおり淡々と再開発事業を進めていきたいと考えております。","id":"exchange-094"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そういうふうな状況というのもあるわけです。私はそういう中で、やっぱりきちんと見通しを持った中で進めていくと、そういう仕組みにこそ変えるべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-095"},{"speaker":"井上委員","kind":"提案","question":"議事録を確認する限り、２００７年から何度となく提案がされています。品川区で進まない理由をお伺いいたしますとの意見を述べました。","respondent":"藤田都市計画課長","answer":"その基本構想の中に重点的にエリアを決めて政策を推進する地区を求める、そういった地域になったところを優先的に整備を進めたいと聞いてあります。現在大井町駅周辺について、今年度、来年度でその計画を立て、その中で整備を進めていきたいと考えているところです。","id":"exchange-096"},{"speaker":"井上委員","kind":"質問・要望","question":"大井町駅周辺にそういった形ででき上がってくるんだろうということで期待をさせていただきたいと思うんですけれども、エスコートゾーンは音響信号のある横断歩道に付設するのが望ましいということですが、区内には音響信号が何カ所ありますか尋ねました。","respondent":"谷口交通安全担当課長","answer":"区内信号３５０カ所ございまして、そのうちの４９カ所が音響式信号になっております。","id":"exchange-097"},{"speaker":"井上委員","kind":"質問","question":"そのうちの何カ所が日中常時稼働している信号になるのか尋ねました。","respondent":"谷口交通安全担当課長","answer":"常時稼働しているのが、昼間帯４カ所あります。押しボタン式が４５カ所という状況です。","id":"exchange-098"},{"speaker":"井上委員","kind":"質問・要望","question":"日常使う横断歩道が押しボタン式音響信号ということを知っていれば、ボタンを押して安心して横断することができます。簡単ではありませんけれども、こういった必要とする方たちへのピンポイントで知らせる工夫を求めますけれども、区のご見解をお願いいたします。","respondent":"谷口交通安全担当課長","answer":"区としましても、今お話し申し上げました４９カ所につきまして、徐々に広報をして、周知を図っていきたいと考えております。","id":"exchange-099"},{"speaker":"井上委員","kind":"質問・要望","question":"それで、今年の６月に成立いたしました障害者差別解消法ですが、合理的配慮を行政に義務づけています。当事者意見を聞いて改善することによって、ここでぜひ警視庁との調整を積極的に進めていただきたいと要望しますが、ご意見お願いいたします。","respondent":"谷口交通安全担当課長","answer":"音響式信号につきましては、なかなか難しい問題がございまして、その設置している住民の方、付近の方からの反対もあります。音響式信号の設置については積極的に進めているところですが、それを踏まえながら、警視庁のほうにも要望を伝えてまいりたいと思います。","id":"exchange-100"},{"speaker":"井上委員","kind":"質問・要望","question":"次は、人感センサーつき街路灯、公園灯についてお伺いをいたします。プレス発表では３６０万円ほどの予算がついておりますけれども、決算額と事業の実績、そして検証の結果をお伺いいたします。","respondent":"稲田道路課長","answer":"真ん中ほどですが、こちらでは２２５万７,９００円の決算額になっております。公園灯部分につきましては、公園維持管理のほうから出ておりまして、トータルしますと、トータルの発注契約額決定額が３９２万７,０００円です。","id":"exchange-101"},{"speaker":"井上委員","kind":"質問・要望","question":"それに街路灯や公園灯は夜間常時点灯すべきものですので、人が来ないと点灯しないということでは防犯上もいかがなものかと考えています。なおかつ今データがとれていないということなので、そちらのほうに力を入れていただきたいなと思うんですが、いかがか尋ねました。","respondent":"稲田道路課長","answer":"使用する場所、それから今後、機種の向上、価格の安定というところ等あります。今後もこの動向を注視しながら考えていきたいと思っています。","id":"exchange-102"},{"speaker":"井上委員","kind":"質問","question":"決してむだになっていることではないと思いますので、よろしくお願いをしたいと思います。ちなみに、そういった対応をこれから進めていこうという計画などをお持ちなのか、お伺いをしたいと思います。","respondent":"稲田道路課長","answer":"私ども、これをやるに当たりまして、他区の状況を聞きました。１区、回答はなかったんですが、人感センサー等の考えはまず持っていないという状況でした。","id":"exchange-103"},{"speaker":"井上委員","kind":"質問","question":"では、続きまして、住宅費なんですけれども、住宅相談センターが２０１１年に八潮に開設されていますけれども、２０１２年度の決算がどこに入っているのか、ちょっとわからないので、金額とその使途をお伺いします。","respondent":"大串住宅担当課長","answer":"そちらにつきましては、住情報ネットワークサービス整備事業というものです。１６５ページ、今年度の成果報告書ですと１６５ページの上から１０行目に入っているものです。","id":"exchange-104"},{"speaker":"井上委員","kind":"意見","question":"２００８年に品川区に住情報センターの構想があったかと思うんですけれども、以前の構想はまだ検討が継続されているのか、その状況をお知らせくださいとの意見を述べました。","respondent":"大串住宅担当課長","answer":"この住情報の中で包含した形で今進めているというところでございまして、宅建協会を通じまして、まちまちの不動産屋のほうに配布をさせていただいた。こういった形で今現在は進めているといったところです。","id":"exchange-105"},{"speaker":"井上委員","kind":"意見","question":"なかなか活用ができないんじゃないかなと思うんですけれども、そういったところは、もっと広く展開をしていくのかというようなことでお願いしますとの意見を述べました。","respondent":"大串住宅担当課長","answer":"オーナー向け、あるいは不動産屋向けに出したパンフレットは品川区全域で配布をしています。こちらのネットワークの相談センターが八潮にあるということで、八潮の方を中心に住み替え関係の相談には当たっているといったところです。","id":"exchange-106"},{"speaker":"浅野委員","kind":"質問","question":"夜間の震災が起きて、大停電ですね、こちらのほうが発生をすることに対しての対策は何か考えられているのかどうかということをお伺いします。そして、「アシカの腹筋」、これも２万５,０００回を超えているということですけれども、これらに対する区の評価についてお伺いします。","respondent":"稲田道路課長、多並公園課長","answer":"蓄電池というんですか、そういうものがあるものを区は考えているかというご質問についてです。それから対応するものが出てきておりまして、それともう一つ、他の自治体の状況もよく観察しながらやっていきたいと考えています。 」というのは約１０万回以上ということで、非常に人気だということです。ＰＲをかけるという意味でＹｏｕＴｕｂｅを始めたところもあって、ここについても非常にＰＲ効果が高かったということで考えているところです。","id":"exchange-107"},{"speaker":"浅野委員","kind":"提案","question":"ＳＮＳを使ったらどうかなというのが提案なんですけれども、交流サイトになりますけれども、引きつける部分があるのではないかなと思います。サンシャインシティですから、例えばライブ映像も含めて提供してはどうかと思いますが、いかがか尋ねました。","respondent":"多並公園課長","answer":"Ｆａｃｅｂｏｏｋにつきましても、委員のご提案ということで、今後サンシャインとよく検討してまいりたいと思います。よくサンシャインと今の状況を聞きながら、今後どのようにしながわ水族館を進めるかというのは協議してまいりたいと思ってあります。","id":"exchange-108"},{"speaker":"浅野委員","kind":"質問・要望","question":"同居に至った件数というんでしょうか、これが何件ぐらいその中であったかなということを教えていただきたいのと、介護とか保育の観点からすると。区としてはこの３世代同居というものをどう考えられているかを含めて教えてほしいと求めました。","respondent":"大串住宅担当課長","answer":"昨年３５件、親元同居、近居ということで支援を行いました。３世代が同居することによるというメリット、区としてもそういった形で家族内で問題解決の一助になっていければよろしいと考えているところです。","id":"exchange-109"},{"speaker":"浅野委員","kind":"意見","question":"私の家も３世代同居でありまして、今後３世代同居というのは私もぜひとも推進をしていってもらいたいなと思います。３世代だから、じゃあ、これは区のほうの今後の検討にお任せしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-110"},{"speaker":"須藤委員","kind":"質問","question":"成果報告書の１５７ページ、立会川雨水放流管建設関連整備、これはどういう内容で、どの部分、場所で、どんな効果があるのか、説明を求めました。","respondent":"奥田河川下水道課長","answer":"東京都のほうで実施している事業でございまして、月見橋の家からなぎさ会館のところまでシールドマシーンで整備するような事業になってあります。","id":"exchange-111"},{"speaker":"須藤委員","kind":"質問","question":"第二立会川幹線と関連していると考えて、また別だよと考えるんか尋ねました。","respondent":"奥田河川下水道課長","answer":"今こちらの上流部と中流部ができておりまして、今、下流部の工事をやっております。あわせて立会川の雨水放流管、こちらの事業もやっておりまして、こちらの二つが東京都のほうで浸水対策に大きく寄与する事業となっています。","id":"exchange-112"},{"speaker":"須藤委員","kind":"質問","question":"今までいわゆる品川の駅を持ってこいという話も一生懸命行政サイドの皆さんがいろいろ働いて品川に発着駅を持ってきたというような努力があって品川…話が出てくるときには、品川区はどういうふうに絡んでいるのかというのをお聞きしたいので、お答え願いたいと思います。","respondent":"藤田都市計画課長","answer":"区のほうにも意見照会があり、その意見をもとに東京都のほうで取りまとめをし、事業者のほうに提示をしたと考えています。区のほうとのかかわりですけれども、品川駅の南地域、この辺についてのまちづくり等の検討についても行ってきたところです。","id":"exchange-113"},{"speaker":"須藤委員","kind":"質問","question":"４.６ｋｍという、区はどうのという話だけど、そのあたりはいかがでしょうか。まちづくりに関連してどういう話を持っていけるのかどうか。","respondent":"溝口都市開発課長","answer":"リニアの駅自体は港区にあります品川駅になりますが、当然リニアがつながることによって品川駅の乗降客というのはかなり増えると考えております。リニアの効果が品川区内にも波及するようにまちづくりを進めていきたいと考えていますし、そういったことを考えているものです。","id":"exchange-114"},{"speaker":"須藤委員","kind":"質問","question":"それぞれ本当に答えられるようなぴしっとしたものができてきていますので。文化財に関してどうするんだというところまで、それだけしっかりやってきているところなので、いかがか尋ねました。","respondent":"溝口都市開発課長","answer":"逆に品川区としてはいろいろ周辺まちづくり等進めていく中で、そういったところも必要になってくると思います。そういった観点でＪＲ東海と事あるごとにまちづくりについては連携しながら進めていきたいと考えております。","id":"exchange-115"},{"speaker":"須藤委員","kind":"質問","question":"２０日に時間ある方は、やはり区としては説明会がしっかりできるような仕組みはつくってやるべきじゃないかと、品川区でやるときにはね。いろんな環境があると思うんだけれども、そのあたりについてはいかがか尋ねました。","respondent":"藤田都市計画課長","answer":"そういった中で、しっかりと連携を図りながら、事業を進めるための説明会等についても協力をしていくべきと考えています。いずれにしても、連携しながら進めていくことが大切だと考えています。","id":"exchange-116"},{"speaker":"須藤委員","kind":"質問","question":"それから、１６３ページの荏原町の駅前地区の防災街区整備事業。その期待の反面、そういう心配なさるお客さんたちもいらっしゃいますけれども、その進捗状況について説明を求めました。","respondent":"品川木密整備担当課長","answer":"そしてこの最後の権利返還計画、この三つの山を越えましたので、今後は工事のほうに入っていきたいと考えております。工事車両等、商店街等に入る場合がありますので、その辺は、十分商店街のほうと話し合いをしながら、配慮しながら進めていく予定でおります。","id":"exchange-117"},{"speaker":"須藤委員","kind":"質問","question":"そのあたりを簡単に教えてもらいたいのと、いろんな配慮が必要だろうと思うんだけれども、そのあたりについてはいかがでしょう。","respondent":"品川木密整備担当課長","answer":"現在組合のほうと建設会社のほうが、やっと契約のほうこれからしていこうというような状況ですので、ちょっと細かいところはまだまだこれからの話になっていきますので、そういった面は十分配慮しながら進めていきたいと考えております。","id":"exchange-118"},{"speaker":"南委員","kind":"質問・要望","question":"１６５ページの区営・建設型区民住宅長寿命化計画策定費に関係して伺いたいと思います。改めてどういうふうに計画をつくられたのか、その内容について、棟数も含めて教えてほしいと求めました。","respondent":"大串住宅担当課長","answer":"そのうちの１棟につきましては、ご案内のように、西中延区営住宅ということで、現在建替えに向けての計画を進めているところです。残り４棟につきましては、計画を考えていきたい、このように考えているところです。","id":"exchange-119"},{"speaker":"南委員","kind":"質問・要望","question":"とりわけせっかく建替えをされるわけですから、改めて、今の段階でわかっているものがあれば教えてほしいと求めました。その辺がどうなっているのか、この現状維持というふうに計画上はした、そこのあたりはどういうことなのかを伺いたいと思います。","respondent":"大串住宅担当課長","answer":"一応こちらの計画期間は平成２５年度から１０年間という、この中で検討を加えるということになっております。今後の活用策等々含めて検討していきたいと考えていますし、住宅そのもののバリアフリー化、耐震改修だけではエレベーター設置が難しかった物件です。","id":"exchange-120"},{"speaker":"南委員","kind":"確認","question":"したがって、そこの長計とのこの関係で、どういうふうに考えているのか、そこを改めて確認したいと思います。生活寮、合築をする方向で検討をするべきだと思っているんですけれども、そのあたりの考え方はいかがか尋ねました。","respondent":"大串住宅担当課長","answer":"西中延区営住宅単体の建替えというだけではなく、地域ニーズに対応した形での建替え、こういったものを実現しております。再三の答弁になりますけれども、今後住宅を建て替える際には、こういったことも勘案しながら総合的に展開していきたいと考えております。","id":"exchange-121"},{"speaker":"須貝委員","kind":"質問","question":"私は１５４ページ、道路橋梁費と１６４ページ、建築物耐震化支援費についてお伺いしたいと思います。これらの耐久性、強度、期間もそうなんですが、どのくらいあるんでしょうか、まず説明を求めました。","respondent":"稲田道路課長","answer":"警察の標識では、警察のほうで管理していくというところで、その管理者ごとが把握しております。我々の区の標識におきましては、大型標識等、今年度も点検するんですけれども、点検をしながら、寿命等は考えているです。","id":"exchange-122"},{"speaker":"須貝委員","kind":"質問","question":"首都直下地震で大地震が起きて、マグニチュード７から８クラスのでかい大地震が起きた場合に、安全なんですかと。その辺についてどのようにお考えなんか尋ねました。","respondent":"稲田道路課長","answer":"国交省のほうから通達が来ておりまして、各管理者は道路ストックの総点検という名目で来ているんですけれども、それを実施しなさいと。大震災等でのそういう崩壊とか、今年度国交省のほうから来ておりまして、再三にわたり区のほうも報告等を定期的にやっているという状況です。","id":"exchange-123"},{"speaker":"須貝委員","kind":"質問","question":"そうしたら、これがもしねじ曲がったりして倒れたらどうするんですか、落っこちたら。電線という話をしましたけれども、大変なことになると思うんですが、その辺について認識がおありか尋ねました。","respondent":"稲田道路課長","answer":"笹子トンネルの天井崩落事故がございました。早急に実施するということで、全力を挙げて今取り組んでいるところでございまして、そういう事象が起こらないように頑張っているところです。","id":"exchange-124"},{"speaker":"須貝委員","kind":"質問・要望","question":"防災課についても、こういうことをどう考えているのかというふうに、後でお答えいただきたいんですが、ここで、特定緊急輸送道路ってありますね。これについて、区内には幾つかあると思うんですが、ちょっとこれについて簡単に説明と、どのぐらい、どういうものがあるのか、説明を求めました。","respondent":"品川木密整備担当課長","answer":"この特定緊急輸送道路、品川区内には約２０６とあります。こういった道路が、阪神の震災のときでもそうですが、倒れて、道路が閉塞しないように耐震化のほうを進めていくというような事業です。","id":"exchange-125"},{"speaker":"須貝委員","kind":"質問","question":"今診断は確かに今回も５５棟やって、実際その前に、そういう大震災が起きたらどうしようもないということじゃないですか。予算をつけて何とか変えようとしているのが、その前にやることがあるんじゃないかと思うんですが、それは違うんか尋ねました。","respondent":"品川木密整備担当課長","answer":"我々、それから５メートルぐらいの道路を６メートルに広げて、消火ができるような形で道路を買い取っていくというような事業もやっております。なかなか進まない事業ではありますが、こつこつと密集事業地区等で防災まちづくりというのは進めているような状況ではあります。","id":"exchange-126"},{"speaker":"須貝委員","kind":"質問","question":"それ、だって、地下１０メートル、２０メートル、基礎を下まで杭を打ってやっているわけじゃないですよね。ちょっとお答え願いたいのと、防災のほうとしてどういうふうに考えられているのか、お２人にお聞きしたいと思います。","respondent":"品川木密整備担当課長、鈴木防災課長、安井土木管理課長","answer":"こういった対策が非常に有効ではないかというふうには考えております。こういった活動をしながら防災対策のほうを進めているような状況ではあります。片方では建物の耐震化や不燃化を進めつつ、それぞれの耐震性なり安全性の確保というのも並行して進めるべきだというふうには考えております。… さらに電柱の強化を図るために交換巻き付け、耐震基準の整備をさらに進めていくというようなことで取り組んでいると聞いてあります。","id":"exchange-127"},{"speaker":"須貝委員","kind":"質問","question":"折れていないと、今、電話線か、電話のほうがありますけれども、実際、じゃあ、折れていなくて垂れ下がったらどうなんですか。東電さんも今お金ないからどうかわからないけれども、実際人がまず逃げられるということを最優先に、その辺についてご見解を説明を求めました。","respondent":"鈴木防災課長","answer":"そのための避難路の確保というのは本当に重要な課題というふうには認識をしております。不燃化、トータルで区民の皆様に伝えながら、それぞれ自分の役割を果たすということで対策を進めるというのが現実的な対応だと考えております。","id":"exchange-128"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後、要望だけ言っておきます。それだけは望んで、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-129"},{"speaker":"いながわ委員","kind":"質問","question":"調査というんですかね、それをやっているかどうかということと、自転車駐輪場の設置ということでいろいろ書かれております。これも、ちゃんとそこのマンションなり共同住宅がしっかりそれを守ってやっているかというのを調査したことがあるかどうかということをお伺いします。","respondent":"谷口交通安全担当課長、藤田都市計画課長","answer":"施設を新築する場合の自転車駐車場の設置ということで附置義務が定められておりまして、百貨店、ご案内のとおり定められているところです。調査につきましては、完了報告を受けまして、また確認… 集合住宅における住宅の面積別の戸数に係数を掛けて一定の附置義務の台数を出すものです。台数的にはなかなか、私どもの附置義務の台数そのもので足りているというような状況ではないんじゃないかというふうには感じているところです。","id":"exchange-130"},{"speaker":"いながわ委員","kind":"意見","question":"工事が完了して、その後終了検査というか、それを見に行くのは当たり前のことであって、その後、オーバーフローしてしまった場合の指導をされるのか。何かそういうアクションを起こしているかどうかというのを私聞きたかったので、その分、短めにお願いしますとの意見を述べました。","respondent":"谷口交通安全担当課長、藤田都市計画課長","answer":"今ご質問の個々の個別に対応しているところでございまして、終わってから、今委員ご指摘のように、現場調査を行っておりませんけれども、個々に陳情等が参りましたら、個別に対応しています。 事業者のほうで必要に応じて台数を増やすというような形になります。基本的に緑はこれだけ確保しなさい、なかなかすべてを満足するわけにいかないということで、そのようなご相談を受けるようなこともあります。","id":"exchange-131"},{"speaker":"いながわ委員","kind":"質問","question":"透水性舗装というんですか、よく平米数で出しますけれども、km数でどれぐらいあるのかということ。この周期というんですかね、どういった周期で掃除をしていくのか、説明を求めました。","respondent":"稲田道路課長","answer":"雨水流出抑制のために透水性舗装を実施しておるものです。この決算で出ています透水性舗装機能回復委託なんですが、これは年間３,０００平米を実施しております。","id":"exchange-132"},{"speaker":"いながわ委員","kind":"質問・要望","question":"車両の通行区分というんですかね、車両の規制というんですかね、そういった規制も必要になってくるのではないかなと考えています。４０フィートのトレーラーとか重トレが来たら、そのお考えと問題意識について、ぜひ都市計画のほうからも一言お願いします。","respondent":"谷口交通安全担当課長、藤田都市計画課長","answer":"大型自動車を規制するには道交法の８条に通行禁止というのがあります。地域の住民の方からのご要望があれば、警察のほうも現場を見まして、そういう対応も検討されていくと考えているところです。そういう面で、生活道路となる補助２６号線については、あまり入ってくるのはやはり好ましくないのかなと考えています。","id":"exchange-133"},{"speaker":"いながわ委員","kind":"質問・要望","question":"河川についてといっても、暗渠になっている立会川のことについてお伺いをいたします。暗渠になっていますけれども、当時の技術も含めて、耐震性が本当に大丈夫かどうかというのを１点お伺いをいたします。","respondent":"奥田河川下水道課長","answer":"東京都のほうで昭和４４年から昭和４９年度に施行されたもので、供用開始してからおおむね４０年程度が経過している形になってあります。そういった老朽化対応、耐震性ということは非常に優先度高い認識を持っておりまして、実は今年度から調査を開始いたしまして。","id":"exchange-134"},{"speaker":"いながわ委員","kind":"質問・要望","question":"二葉四丁目の第二京浜からちょっと入った１００円ショップのローソンがあります。これが技術的なものなのか、それともどうにかなるものなのか、それを説明を求めました。","respondent":"稲田道路課長","answer":"それから、土部分というところで、委員おっしゃる段差等ができております。それは長年の間でどうしようもなく発生するものでございまして、修繕等を日々やっております。","id":"exchange-135"},{"speaker":"たけうち委員","kind":"質問","question":"私は１５９ページの都市計画総務費、それから、１６３ページの密集住宅市街地整備促進事業について伺います。そこが基本的にはいわゆる防災広場とかになるんじゃないかと思うんですけれども、これがどうなっていくか説明を求めました。","respondent":"品川木密整備担当課長、藤田都市計画課長","answer":"のんき通りを歩いていますと、奥でボトルネックになっているんですが、そこのゆたか診療所のところなんですが、今、まさに解体工事をやっております。その後につきましては、地域の方々とワークショップ等開きまして… すいません。都市計画総務費の職員給与費についてはちょっと確認をさせてください。","id":"exchange-136"},{"speaker":"たけうち委員","kind":"質問・要望","question":"木密不燃化１０年プロジェクトの本格実施地区に応募、これが通ると、区としてはどう考えているのかというのを教えていただきたい。平成２５年度の予算の中で、この経費が入っているんですが、これの会議設置に向けての今進捗状況を説明を求めました。","respondent":"品川木密整備担当課長、藤田都市計画課長","answer":"豊町五丁目には防災広場が今ありませんので、現状としては、今の状態で一般開放のほうをしていこうかというように考えております。ですので、ご質問にありますように… 地域交通に関する基礎調査、それから、会議の運営の経費を見込んでいるものです。会議の運営については秋からスタートしたいということで考えてございまして、もう既に秋ですので、会議の開催に向けて進めていきたいと考えています。","id":"exchange-137"},{"speaker":"たけうち委員","kind":"質問・要望","question":"先ほどから２０２０年のオリンピック・パラリンピックの話も出てきまして、絡んでくる、ぜひしっかりとお願いしたいと思います。それに絡んで、ＪＴ、南のほうのところの地域を活用するということはないんか尋ねました。","respondent":"片田都市環境事業部長、品川木密整備担当課長、堀越人事課長","answer":"今後活用含めて検討していくというところもありますので、これ、いろんな区としての有効利用を考えていくというような状況で考えております。二葉四丁目のＪＴの跡のほうですが、現在木密１０年プロジェクトの中で、コア事業というような形でちょっと想定はしております。現在そういう方向に向けて… 都市計画総務費の人数のところですけれども、こちら、予算の段階では、前年の１０月１日の人員によりまして予算を編成しております。","id":"exchange-138"},{"speaker":"たけうち委員","kind":"質問・要望","question":"わかりました。その密集住宅関係と２９号のいろんな沿線絡みのことは、とにかく丁寧にやってほしいと求めましたけど、その決意だけ説明を求めました。","respondent":"品川木密整備担当課長","answer":"これから木密１０年プロジェクトを中心にしまして、それから防災まちづくりに向けて、整備のほうを行っていきたいと考えております。周辺の住民の皆さんに関しては、間違った情報が行かないようにきちっとした形で周知をして、この事業を進めていきたいと考えております。","id":"exchange-139"},{"speaker":"本多委員","kind":"質問","question":"１６２ページの市街地整備事業費について質問します。区のかかわりですとか、それぞれの地区で決めているのか、その辺の決め方について説明を求めました。","respondent":"溝口都市開発課長","answer":"どういった公園ですとか、そういったものも含めて緑化というのをどうやって取り組んでいくのか、そういったものに基づいて進めてきているものです。歴史的に感じられるとか、季節が感じられる木、そういったものが植えられるような形での指導はしていきたいと考えているものです。","id":"exchange-140"},{"speaker":"本多委員","kind":"質問","question":"大崎駅西口南地区の樹木の決めた内容について、わかる範囲で説明を求めました。","respondent":"溝口都市開発課長","answer":"１６３号線に植われている樹種があって、クスノキです、クスノキが植わっております。そのクスノキと合わせて連植するような、連なって公開空地の樹木を決めたり、そういったもので定めているものです。","id":"exchange-141"},{"speaker":"本多委員","kind":"質問・要望","question":"その辺を教えていただきたいのと、あと、区の街路樹との整合性ですね。サツキとか、その辺の整合性がとれているのか、その辺を説明を求めました。","respondent":"溝口都市開発課長","answer":"そういったものの配置も、植樹されている木を十分考慮して、民地内の公開空地の樹木というのは定めてきているというのが現状です。多摩産材の関係の補助金ですが、そういったものは使ったという事例は私どもは聞いておりません。","id":"exchange-142"},{"speaker":"本多委員","kind":"質問・要望","question":"それが使えるのかどうかはちょっと調べてみないとわからないんですが、よく枯れちゃっていたんですね、北側で。それをよく考えて原状復帰をしていただきたいと思うんですが、樹木を選ぶ選び方は、その辺についてはいかがでしょう。","respondent":"溝口都市開発課長","answer":"百反通り沿いにつきましては、開発側につきましては、北側といいますか、百反通りの上側と少し樹種を変えた形で植えてきているところもあります。地域のご要望等も踏まえて、樹木については検討していきたいと考えています。","id":"exchange-143"},{"speaker":"本多委員","kind":"質問・要望","question":"１６３号線に並行した区道を使えば、３人増やすだけでも迂回はできると思うんですが、いかがでしょうか。当然住友不動産への働きかけ等ありますけれども、区としてやる気になればできると思うんですが、いかがか尋ねました。","respondent":"溝口都市開発課長","answer":"そういった努力を重ねて、なるべく工事渋滞が起こらないように取り組んでいるものです。なかなか工事費等含めて、莫大な費用がかかることも懸念されますので、引き続きそれについては検討させていただきたいと考えています。","id":"exchange-144"},{"speaker":"本多委員","kind":"意見","question":"本当２人、３人増やすだけでできると思うので、検討してください。以上で終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-145"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/571589?Template=document&Id=1380#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":116089,"voices":360}}]);
